S("envgl",{cpu:"Qualcomm Snapdragon XR1",ram:"3 GB LPDDR4",sto:"32 GB",os:"Android 8.1 (Google Glass Enterprise Edition 2 hardware)",price:"Professional Edition $3,499",syns:"Envision's built-in voice output (engine not documented)",wt:"46 g"},["https://shop.letsenvision.com/products/glasses-professional","https://support.google.com/glass-enterprise/customer/answer/9220200?hl=en"]);
