const D6=(id,desc,s,src,ha)=>{U(DEV,id,{s:s||{},src:src||[],ha});DEV.find(d=>d.id===id).desc=desc;};
const AWBN1="https://afb.org/aw/1/6/16145",AWBN3="https://afb.org/aw/3/1/14967";
D6("bnclassic",["The original BrailleNote (BT with a braille keyboard, QT with a QWERTY keyboard) is a flat, rectangular notetaker about 9½ inches wide, 5 inches deep and 1 inch thick. AccessWorld weighed the 32-cell model at 2 pounds 9 ounces. The case is gray and the braille keys are green.","On the top surface, nine keys sit on a gentle curve for comfort: an eight-dot braille keyboard plus a space bar. The two outer keys, for the little fingers, act as Backspace (dot 7) and Enter (dot 8).","At the front of the top surface is an 18- or 32-cell refreshable braille display. Both sizes use the same case, and an 18-cell unit could be upgraded to 32 cells. Above each braille cell is a small touch cursor (routing button) that jumps the cursor to that spot.","On the narrow front edge facing you are four thumb keys, used to move back and forward through documents and menus without lifting your fingers from the braille. The thumb-key layout became a BrailleNote signature.","Around the edges are a PCMCIA card slot (for the optional disk drive and other accessories), serial and parallel ports, a modem phone jack, an infrared port, an earphone jack and the AC adapter socket. Power comes from a rechargeable nickel-metal-hydride battery."],{dim:"9.5 × 5 × 1 in",wt:"2 lb 9 oz (32-cell)",price:"BrailleNote 18 $3,799; BrailleNote 32 $5,499 (2001, plus $45 shipping)"},[AWBN1,AWBN3]);
D6("bnpk",["The BrailleNote PK, announced in July 2004, was the smallest Windows-based accessible PDA of its day. It weighs about a pound and measures roughly 7 inches wide, 4 inches deep and 2 inches thick, small enough to hold in one hand.","Unlike larger BrailleNotes, the eight square braille input keys sit behind the braille display, at the back of the top surface. The outer keys are set farther back than the inner keys to fit the shape of your hand. AccessWorld found these keys and the display among the quietest it had tested.","In front of the display are two smooth keys that both act as space bars. On either side of them are two small, slightly recessed control keys; you hold one down to turn the unit on or off, since there is no power switch.","The 18-cell braille display has a cursor routing key above each cell. On each side of the display are three small buttons stacked vertically for scrolling, and the top button on each side starts and adjusts automatic scrolling. On the front edge is a small four-way joystick that you can also press to select.","All connectors are on the back panel: power, headphone, USB, a CompactFlash slot and a non-standard serial port that uses supplied cables. A small Bluetooth antenna sticks out about half an inch from the back. There is no parallel port, infrared port or built-in modem. It comes in a fitted carrying case with a shoulder strap."],{dim:"About 7 × 4 × 2 in",wt:"About 1 lb"},["https://afb.org/aw/6/1/14662"]);
const MPS="https://www.afb.org/aw/7/1/14531";
D6("bnmp",["The BrailleNote mPower, introduced June 28, 2005, has the same size and keyboard as earlier BrailleNotes (about 9½ × 5 × 1 inches). It looks sleeker, with a silver case instead of gray and forest-green keys instead of teal.","The top has the curved eight-dot braille keyboard with space bar and an 18- or 32-cell braille display with a routing button above each cell. The four thumb keys stay on the front edge facing you.","The back panel has the power socket, a telephone jack for the built-in 56K modem, a serial port, a CompactFlash slot, an SD card slot, two USB host ports, one USB client port and built-in Bluetooth. There is no parallel port.","The PCMCIA slot is on the right side. On the left side are the earphone jack and power switch, plus a new external microphone jack and a small recessed Record button that starts a voice recording from any application. An internal microphone is built in.","Inside is a 128 MB flash drive. AccessWorld noted excellent stereo sound through headphones, while the built-in speaker is the same modest one as earlier models."],{price:"mPower BT32 or QT32 $6,195; BT18 or QT18 $4,395; VoiceNote mPower $1,995 (2005, plus $45 shipping)"},[MPS]);
D6("bnmpqt",["The BrailleNote mPower QT is the QWERTY-keyboard version of the mPower, introduced in 2005. AccessWorld says the mPower came with either a braille or a QWERTY keyboard, in the same case size as earlier BrailleNotes (about 9½ × 5 × 1 inches).","Instead of the eight braille keys, its top surface carries a typewriter-style QWERTY keyboard. The exact key count and layout are not documented in the sources found.","In front of the keyboard is an 18- or 32-cell refreshable braille display with a cursor routing button above each cell, and four thumb keys on the front edge for moving through text.","The ports match the braille-keyboard mPower: power, phone line, serial, CompactFlash and SD slots, two USB host ports and one USB client port on the back; PCMCIA on the right; earphone, power switch, microphone jack and recessed Record button on the left.","The case is silver, and it has the same 128 MB flash storage and Bluetooth as the BT model. A VoiceNote mPower QT version had speech only, with no braille display."],{price:"QT32 $6,195; QT18 $4,395 (2005)"},[MPS]);
const APX="https://www.afb.org/aw/13/4/15822",APXM="https://www.edvisionservices.org/manuals/braillenote%20apex%20bt%20user%20guide.pdf";
D6("bnapex",["The BrailleNote Apex BT32 is a thin, light notetaker that HumanWare called the thinnest and lightest braille notetaker anywhere. A dealer lists it at about 9.6 × 5.6 × 0.78 inches and 1.8 pounds (812 g). It ships in a slim wraparound leather case with a carrying strap, and you can use it without taking it out of the case.","On top is an eight-key braille keyboard like a braillewriter: six dot keys, plus Backspace (dot 7) under the left little finger and Enter (dot 8) under the right. A small scroll wheel sits in the middle between the dot 1 and dot 4 keys, with the space bar just below it.","Nearest you is a 32-cell display of eight-dot braille cells, with a cursor routing button above each cell.","On the front edge facing you are four thumb keys, named Previous, Back, Advance and Next from left to right. They can be set for right- or left-handed use, so you can move through text without lifting your fingers from the braille.","Around the edges are three USB ports, an SD card slot, earphone and microphone jacks, an Ethernet port and a VGA port for a sighted person's monitor. The battery is user-replaceable."],{dim:"9.61 × 5.63 × 0.78 in (244 × 143 × 19 mm) per dealer",wt:"About 1.8 lb (812 g) per dealer"},[APX,APXM,"https://boundlessat.weebly.com/store/p3/BrailleNote_Apex.html"]);
D6("bnapex18",["The BrailleNote Apex BT18 is the 18-cell version of the Apex, launched in May 2010. It shares the Apex design: a thin case in a wraparound leather carrying case.","The top has the eight-key braille keyboard (six dot keys plus Backspace and Enter), with a scroll wheel between the dot 1 and dot 4 keys and the space bar below it.","Nearest you is an 18-cell eight-dot braille display with a cursor routing button above each cell.","Four thumb keys (Previous, Back, Advance and Next) are on the front edge, set right-handed at the factory and switchable to left-handed.","Its ports and user-replaceable battery follow the Apex design. Exact dimensions and weight for the 18-cell model are not documented in the sources found."],{},[APX,APXM]);
const TCH="https://afb.org/aw/17/8/15305",BOD="https://www.braillists.org/wp-content/uploads/bod24.pdf";
D6("bntouch",["The BrailleNote Touch is an Android braille tablet launched at CSUN in 2016. The tablet itself is 9½ inches wide, 6.3 inches deep and 0.8 inch high and weighs 2 pounds (900 g). In its case with the keyboard it is about 10.2 × 6.9 × 1.6 inches and 3 pounds.","Most of the top is a glass touch screen with a 7-inch visual display that can be turned off. You can type braille right on the glass with TouchBraille: rest all ten fingers on the screen, feel a short vibration, and the virtual keys find your fingers.","The carrying case has a physical Perkins-style braille keyboard built in. It folds over the glass, held in place by magnets, and plugs into a port on the back of the tablet; fold it back to use the touch screen.","Nearest you is an 18- or 32-cell braille display with a routing button over each cell and a stereo speaker at each end. On the front edge are four thumb keys, two short and two long, with three small keys between them: a triangular Back key, a round Home key and a square key for the context menu or app switcher.","On the left side are a micro USB port, an oval power button and volume buttons. The back has a full-size USB port, an SD card slot and an HDMI port (video only). The right side has microphone and headphone jacks and a camera button. Under the tablet, two latches release the replaceable battery and there is a camera window."],{dim:"9.5 × 6.3 × 0.8 in (tablet); 10.2 × 6.9 × 1.6 in in case",wt:"2 lb (900 g); 3 lb (1,420 g) in case"},[TCH,"https://www.humanware.com/microsite/bntouch/specs.php","https://www.humanware.com/microsite/bntouch/faq.php",BOD]);
D6("bntp",["The BrailleNote Touch Plus (2018–2019) is the faster refresh of the BrailleNote Touch, in the same body: 0.8 inch high, 9½ inches wide, 6.3 inches deep and about 2 pounds. AccessWorld called it 'a bit on the hefty side'.","Like the original, it has a glass touch screen for TouchBraille typing and a case with a built-in Perkins-style braille keyboard that folds over the screen.","Nearest you is the braille display, 18 or 32 cells in the same size case, with routing buttons and four thumb keys on the front edge.","The power button is more recessed than on the original Touch, to stop it switching on in a bag. It charges and connects through USB-C instead of micro USB.","Its accessibility software is built into the device instead of a removable internal SD card. It ships with the Acapela Sharon voice, and other voices can be added."],{dim:"9.5 × 6.3 × 0.8 in",wt:"About 2 lb"},["https://afb.org/aw/20/7/16711"]);
D6("evolve",["The BrailleNote Evolve is HumanWare's 2026 braille computer, running KeySoft on Windows 11. HumanWare's specification sheet gives 243 mm wide, 175 mm deep and 20 mm thick (9.57 × 6.89 × 0.79 in), or 25 mm (1 in) on its feet, and 990 g (2.18 lb), or about 1.4 kg (3 lb) in its case.","It comes in 20- and 32-cell braille configurations. HumanWare's labeled drawings show the top surface with the braille keyboard and display; the full key layout is described in that sheet's figures, which are image-only.","On the left side edge are ports and buttons: a 3.5 mm audio jack that works with a microphone, an HDMI 1.4 port and two USB-C Thunderbolt 4 ports, both of which can charge it. There is also a USB 3.2 Type-A port.","Inside are an Intel Core Ultra 5 125U processor, 32 GB of LPDDR5x memory and a 512 GB NVMe drive. It has vibration haptics, stereo speakers, Wi-Fi 6, Bluetooth 5 and a programmable RFID tag for future use.","In the box are the Evolve, a carrying case, a nylon strap with shoulder pad, headphones, a power adapter, a print and braille Getting Started guide and command summary, and a modifier sticker."],{cpu:"Intel Core Ultra 5 125U",ram:"32 GB LPDDR5x",sto:"512 GB NVMe",os:"Windows 11 Pro with KeySoft",dim:"243 × 175 × 20 mm",wt:"990 g (1.4 kg with case)",price:"32-cell: $6,199 (HumanWare US store)"},["https://www.humanware.com/wp-content/uploads/2026/06/Technical-Specs-BrailleNote-evolve.pdf","https://store.humanware.com/hus/braillenote-evolve-32.html"]);
// BrailleSense line
D6("bsense",["The first BrailleSense was sold at first as the Braille Hansone, a Korean name meaning 'to see the world through one fingertip'. HIMS renamed it BrailleSense for English speakers. AccessWorld measured it at 9 × 5 × 1.5 inches and 2.7 pounds.","On top is an eight-key braille keyboard: dot 7 is Backspace and dot 8 is Enter. Four oval function keys sit beside the space bar, F1 and F2 on the left and F3 and F4 on the right. F1 opens the program menu, F2 the menu of the current program, F3 is Tab and F4 is Escape.","In the middle, above the keyboard, is a small LCD screen so sighted people can follow along, with a stereo speaker at each edge above Backspace and Enter.","Below the keyboard is a 32-cell braille display with 32 routing buttons. At the right end of the routing row is an Advance key and at the left end a Scroll Back key.","The front panel, from left to right, has a microphone jack, a stereo headphone jack and five audio buttons: Previous, Record, Stop, Play/Pause and Next. The right side has the power switch, AC socket and detachable lithium-ion battery; the left side has two CompactFlash slots. The back has infrared, two USB, LAN, parallel, video-out and serial ports."],{dim:"9 × 5 × 1.5 in",wt:"2.7 lb",price:"$4,950 (Braille Hansone, early 2005)",os:"Windows CE.NET"},["https://afb.org/aw/6/1/14662"]);
const NFB09="https://nfb.org/images/nfb/publications/bm/bm09/bm0902/bm090211.htm";
D6("bsplus",["The BrailleSense Plus (2008) was made by HIMS of Korea and sold in the US by GW Micro. The NFB measured it at 9.8 inches wide, 5 inches deep and 1.5 inches high, weighing 2 pounds.","On top is a six-dot braille keyboard with Backspace on the left, Enter on the right and the space bar centered below. Beside the space bar are F1 and F2 on the left and F3 and F4 on the right. Behind the keyboard, in the center, is an LCD screen that can be flipped so a person sitting across from you reads it right side up, with a stereo speaker on each side.","Nearest you is the 32-cell braille display with a routing key above each cell and scroll keys at both ends.","The front panel has a three-position Lock switch (all keys, top keys only, or none), microphone and headphone jacks, a three-position media switch (FM radio, DAISY or media), five media buttons, and a spring-loaded power slider: slide right to turn on, left to turn off.","The left side has CompactFlash and SD slots. The back has a reset button, an Ethernet jack, a serial port and a VGA output. The right side has two USB ports (one to connect to a computer, one for flash drives) and the AC socket. Inside are 128 MB of RAM, 8 GB of flash, an FM tuner, Bluetooth and Wi-Fi."],{dim:"9.8 × 5 × 1.5 in",wt:"2 lb",ram:"128 MB",sto:"8 GB flash",price:"$5,995 (2009)"},[NFB09]);
const OHAW="https://afb.org/aw/12/10/15988";
D6("onhand",["The BrailleSense OnHand (2010) is a small 18-cell notetaker. AccessWorld measured it at 4 × 7 × 1.5 inches; its weight is not documented in the sources found. It has a white top panel on a black body and comes in a sturdy case with a shoulder strap that leaves every button reachable.","On top is an eight-key Perkins-style keyboard, with a row of four evenly spaced function keys below it. The small speaker is on the top panel between and above the dot 1 and dot 7 keys.","Below the function keys are 18 routing buttons over the 18 eight-dot braille cells, with two scroll keys on each side of the display.","The front edge has a three-position audio mode switch and five audio buttons. The left side has the AC socket, a USB port and a lock switch; the right side has the SD card slot and external microphone and headset jacks.","The battery door is on the bottom back edge. The battery has clear tactile guides for removing and replacing it, and a spare battery and a charger that beeps when charging is done come in the box."],{dim:"4 × 7 × 1.5 in (AccessWorld)",price:"$4,995 (2010)"},[OHAW]);
const U2M="https://wyominginstructionalnetwork.com/wp-content/uploads/2020/04/Braille-Sense-U2-User-Manual-Ver-8.6-1.pdf",U2AVH="https://www.avh.asso.fr/implantations/certam/evaluations-de-produits/le-bloc-notes-braille-braillesense-u2";
D6("u2",["The BrailleSense U2 (Perkins-keyboard edition) has the shape of a small, thin rectangular box with rubber feet underneath. HIMS's manual gives 10 × 6.1 × 1.9 inches; a product sheet lists 250 × 130 × 39 mm and 924 g (about 2 pounds).","On top is a nine-key Perkins-style keyboard: dots 1 to 6, Backspace under the left little finger, Enter under the right little finger, and a long space bar under the thumbs. On the same row as the space bar are four rectangular function keys, F1 and F2 on the left, F3 and F4 on the right.","Below the keyboard is a 32-cell braille display, with 32 small oval routing buttons above it. Two capsule-shaped Up and Down scroll keys sit on each side of the display. Near the top center is an LCD with four status lights (Wi-Fi, Bluetooth, GPS and charging), and stereo speakers are in the top left and right corners.","The front edge has a microphone or line-in jack, a headphone jack, a three-position media switch (FM radio, DAISY or MP3), five media buttons and the power button. The left side has two USB ports and an SD slot; the right side has a mini USB port, the AC socket and a three-position lock switch.","The back has a reset button, an Ethernet jack, a third USB port and a 15-pin VGA output. Inside are a 1 GHz processor, 32 GB of flash and a removable lithium battery rated at about 17 hours."],{dim:"250 × 128–130 × 39 mm (9.8 × 5 × 1.5 in); manual: 10 × 6.1 × 1.9 in",wt:"924 g (about 2 lb)",cpu:"1 GHz mobile CPU",sto:"32 GB flash",os:"Windows CE 6.0",syns:"Eloquence (French product sheet)",price:"€6,890 incl. VAT in France (January 2014)"},[U2M,U2AVH,"http://insidevision.fr/pdf/Fiche_Produit_Braille_Bloc_Notes_Braille_Sense_U2_Perkins_01.pdf","https://docsbay.net/doc/635567/a-physical-description-of-a-braille-sense-u2-with-a-braille-type-keyboard"]);
D6("u2qt",["The BrailleSense U2 QWERTY (model H432Q) is the typewriter-keyboard version of the U2. Dealer and HIMS data give 250 × 160 × 20 mm (9.84 × 6.3 × 0.78 in) and 838 g (1.84 lb).","Instead of the Perkins braille keys, its top carries a standard QWERTY keyboard for typing as on a computer.","Nearest you is a 32-cell braille display with 32 routing keys and four scroll keys, two at each end.","The front has five audio buttons for the media player. It has USB and SD connections, GPS and a vibration motor.","It runs Windows CE 6.0 with 32 GB of storage and a detachable battery. It is discontinued; HIMS points buyers to the BrailleSense 6."],{dim:"250 × 160 × 20 mm (9.84 × 6.3 × 0.78 in)",wt:"838 g (1.84 lb)"},["https://www.ergoguys.com/bru2qwke.html","https://selvasblv.com/brochure/braille/HIMS-Braille-Sense-U2-and-U2-QWERTY-Data-Sheet.pdf"]);
D6("u2mini",["The BrailleSense U2 Mini (2013) fits in a purse, backpack or roomy jacket pocket. It measures 6.7 × 3.5 × 1 inches (172 × 90 × 27 mm) and weighs under a pound (about 427 g).","On top is a nine-key Perkins-style keyboard with four function keys.","It has 18 eight-dot braille cells with 18 routing buttons, and four scroll keys.","A panel of media controls is on the front. The power socket is on the left side, marked with a braille 'dc'. There are an SD card slot, an OTG USB port, a stereo headphone jack and built-in speakers that AccessWorld found clear and loud for the size.","The battery compartment is at the back left edge. Two user-replaceable lithium batteries come with it, with a separate charger, so one can charge while the other is in use; each lasted about 8 hours in AccessWorld's test. It has a vibration motor for silent alerts."],{dim:"6.7 × 3.5 × 1 in",wt:"Under 1 lb (about 427 g)",price:"$3,995 (2015)"},["https://afb.org/aw/15/5/15576","https://www.visiole.fr/basse-vision/anciens-produits/bloc-note-braille-sense-u2-mini/"]);
const POL="https://www.afb.org/aw/19/1/15168";
D6("polaris",["The BrailleSense Polaris (June 2017) was HIMS's first Google-certified Android notetaker, named for the Polaris office suite. It measures about 9.64 × 5.66 × 0.74 inches and weighs 1.65 pounds. Its case has a magnetic front flap and a shoulder strap.","On top is a Perkins-style braille keyboard that AccessWorld found springy and quiet. Control and Alt keys sit just left and right of the space bar, with the four function keys farther out. The LCD screen takes up the top center, flanked by stereo speakers.","Nearest you is the 32-cell display with routing buttons. Between the cells and the routing buttons is a thin touch strip for flick and tap gestures, and capsule-shaped scroll keys are at each end.","The right side has a combined USB 3.0 and micro USB port, with the SD card slot behind it. The left side, from front to back, has volume buttons, stereo headphone and microphone jacks, and a USB host port. The back has the AC socket, an HDMI port and a Kensington lock slot.","The front panel has a three-position key-lock switch, a three-position mode switch (media, DAISY or app control), the media buttons (the Stop button has a raised dot), and the power button at the far right. Inside are a 2.1 GHz Samsung Exynos 7420, 3 GB of RAM and 64 GB of storage, with a 13-megapixel camera."],{dim:"9.64 × 5.66 × 0.74 in",wt:"1.65 lb",cpu:"Samsung Exynos 7420, 2.1 GHz",ram:"3 GB",sto:"64 GB",os:"Android 5.1.1",price:"$5,795",syns:"Samantha TTS voice (per AccessWorld review)"},[POL,"https://afb.org/aw/20/7/16711"]);
D6("polmini",["The BrailleSense Polaris Mini (2018) is the 20-cell version of the Polaris. It measures 7.28 × 4.05 × 0.90 inches (185 × 103 × 23 mm) and weighs 0.91 pound, small enough for a briefcase or large purse.","The top has the nine-key Perkins keyboard, Control and Alt keys and four function keys. AccessWorld found its keys a bit more clicky than the full Polaris.","Nearest you is a 20-cell braille display with routing buttons and scroll keys.","The right side has a USB-C port for charging, file transfer and braille-display use, with a micro HDMI port toward the back. The left side has volume controls and stereo headphone and microphone jacks. The front panel has the same lock switch, mode switch and media controls as the Polaris.","The speaker and the camera are on the underside. The micro SD slot is inside the battery compartment. Battery life is about 11 hours, and a charge takes about 3.5 hours."],{dim:"7.28 × 4.05 × 0.90 in",wt:"0.91 lb",cpu:"Samsung Exynos 7420, 2.1 GHz octa-core",sto:"64 GB",os:"Android 5.1.1",price:"$4,195"},["https://afb.org/aw/20/3/16315","https://afb.org/aw/20/7/16711"]);
D6("bs6",["The BrailleSense 6 (2021) measures 9.64 × 5.66 × 0.86 inches (245 × 144 × 22 mm) and weighs 1.55 pounds (705 g).","Its top panel has a nine-key Perkins-style keyboard and four scroll keys.","Nearest you is the 32-cell braille display with 32 routing keys.","The top also has a small LCD, two status lights and stereo speakers.","The front panel has a key-lock switch, a media-mode switch, five media buttons and the power button."],{dim:"245 × 144 × 22 mm (9.64 × 5.66 × 0.86 in)",wt:"705 g (1.55 lb)"},["https://selvasblv.com/wp-content/uploads/2024/10/BrailleSense-6-User-Manual-English_V2.5_240912-1.pdf","https://selvasblv.com/wp-content/uploads/2024/06/DIGITALBrailleSense-6-brochure.pdf"]);
D6("bs6mini",["The BrailleSense 6 Mini (2022) is the 20-cell version of the BrailleSense 6. It measures about 185 × 103 × 23 mm (7.1 × 4.1 × 0.9 in) and weighs about 430 g (0.95 lb).","The top panel has a nine-key Perkins-style keyboard, Control and Alt keys and four function keys.","Below the keyboard is the 20-cell braille display. A routing key is above each cell, with a raised dot on every fifth key, and there are four scroll keys.","The right side has two USB-C ports. The left side has volume controls and headphone and microphone jacks.","It shares the BrailleSense 6 software and Android platform."],{dim:"185 × 103 × 23 mm",wt:"About 430 g"},["https://selvasblv.com/wp-content/uploads/2023/11/BrailleSense-6-MINI-User-Manual-V2.pdf","https://selvasblv.com/product/braillesense-6-mini/"]);
D6("bs7",["The BrailleSense 7, unveiled at CSUN 2026, comes in 20-, 32- and 40-cell models. The 32-cell model measures 9.84 × 5.53 × 0.89 inches and weighs under 1.54 pounds; the 40-cell is 11.86 inches wide and under 1.80 pounds.","It keeps the Perkins braille keyboard and adds a detachable QWERTY keyboard that attaches magnetically at the top through a secondary battery module. It also has a physical dictation button and an analog scroll wheel.","Its braille display has no physical routing buttons. Active Responsive Touch tracks your finger and refreshes the line automatically when you reach the last cell. To route the cursor you double-tap the display or press a front end button while touching the spot.","It has a visual LCD, HDMI output, dual USB-C and dual USB-A ports, a micro SD slot, a 4-pole headphone jack, stereo speakers and microphones, a haptic motor, dual-band GPS and a 20-megapixel rear camera with flash.","Inside are an octa-core processor up to 3.35 GHz, 8 GB of LPDDR5X RAM and 256 GB of storage, running Android 15. A long press on Home summons Google Gemini. The 4,600 mAh battery is removable and charges at 18 W through a magnetic connector."],{cpu:"Octa-core up to 3.35 GHz",ram:"8 GB LPDDR5X",sto:"256 GB UFS 4.0",os:"Android 15",dim:"32-cell 9.84 × 5.53 × 0.89 in; 40-cell 11.86 × 5.53 × 0.89 in",wt:"32-cell under 1.54 lb; 40-cell under 1.80 lb",price:"20-cell $5,295; 32-cell $5,995; 40-cell $6,495"},["https://selvasblv.com/product/braillesense-7/","https://selvasblv.com/price-list/"]);
// Victor Reader
D6("vrclassic",["AccessWorld described the Victor Reader Classic Plus, the fuller-featured model of the Classic family, in 2003. It is a CD player for DAISY books measuring 9.3 × 8.2 × 2.1 inches and weighing 2.42 pounds. The top slopes upward from front to back.","The built-in speaker is at the top left, with a carrying handle below it. On the right side, from back to front, are the AC socket, a line jack, a remote jack and an earphone jack.","It has 25 keys. Across the top, right of the speaker, are three pairs of keys stacked vertically for tone, volume and speed. Below them is a 12-key telephone-style keypad: 5 has a raised dot, 4 and 6 have raised left and right arrows, and 2 and 8 have fainter up and down arrows.","Below the keypad are Rewind, Play/Stop (square) and Fast Forward (arrow-shaped). The CD Eject key is to the right of Fast Forward, with the Power key above it.","With no CD inside, it enters a Key Describer mode that announces what any key does. The 1 key opens the Bookshelf, 3 the History list, 5 says where you are, 9 sets the sleep timer and 0 gives elapsed and remaining time."],{dim:"9.3 × 8.2 × 2.1 in (Classic Plus)",wt:"2.42 lb (Classic Plus)",price:"Classic Plus $375 (2003)"},["https://afb.org/aw/5/1/14793","https://www.mkprosopsis.com/Hardware/VictorReaderClassicX.htm"]);
const VS1="https://afb.org/aw/9/1/14279";
D6("vrs1",["The first Victor Reader Stream (2007) is a handheld player about the size of a deck of cards, measuring 4.6 × 2.6 × 0.9 inches and weighing about 6 ounces with its rechargeable battery. Its only visual indicator is a small LED for off, on or charging.","The front has a 12-button telephone-style keypad. The 5 key has a small nib, which AccessWorld found too faint. Above the 1 key is a square Go To key, above the 3 key a diamond-shaped Bookmark key, and at the top a small speaker grill and internal microphone.","Below the keypad is a raised separator line. Under it, centered, is the Sleep key, and below that are Rewind, Play/Stop and Fast Forward.","On the left edge are the round Power button and two arrow-shaped buttons for volume, speed and tone. On the right edge are the headphone and external microphone jacks and the Record button.","Across the top are a small USB port, the AC socket and, in the center, the SD card slot where all content is stored. The keys are high-contrast for low-vision users. The built-in speaker is quiet and mainly for status messages."],{dim:"4.6 × 2.6 × 0.9 in",wt:"About 6 oz"},[VS1,"https://afb.org/aw/9/5/14232"]);
D6("vrs2",["The second-generation Victor Reader Stream (2014) is about 28% smaller than the first. It measures 4.5 × 2.4 × 0.7 inches and weighs 3.9 ounces with the battery, keeping the same keypad spacing.","The top edge has the SD card slot in the center and a protruding headphone jack on the right. The right side has a recessed microphone jack and, below it, a Record key with a barely detectable dot.","Across the top of the front are three keys: a square Go To key with a raised center (with the internal microphone hole above it), a round smooth Wireless key with an LED beside it, and a diamond-shaped Bookmark key.","Below them is a phone-style keypad; the 5 key has two raised dots. A raised line separates the keypad from an oval Sleep key and a bottom row of a left-arrow Rewind, a square Play/Stop and a right-arrow Fast Forward.","AccessWorld puts the round Power key and the up and down arrow keys near the top of the right edge, though the same review elsewhere says left; check the unit. Most of the back is a battery cover with a release near the top."],{dim:"4.5 × 2.4 × 0.7 in (114 × 62 × 18 mm)",wt:"3.9 oz (110 g)"},["https://afb.org/aw/14/4/15708"]);
D6("vrs3",["The third-generation Victor Reader Stream (2023) measures 114 × 62 × 18 mm (4.5 × 2.4 × 0.7 in) and weighs 110 g, with a fully tactile interface.","Across the top of the front are the Go To, Online (Wi-Fi) and Bookmark keys.","Below them is the 12-key number pad, then Sleep, Rewind, Play/Stop and Fast Forward.","The left side has Power/Toggle, an LED, the Up and Down keys and the microphone jack. The right side has a red Record key.","The SD slot is on the top edge. The bottom edge has a USB-C port, the headphone jack and the speaker. It reads text with two Acapela voices."],{dim:"114 × 62 × 18 mm",wt:"110 g"},["https://shop.rnib.org.uk/products/victor-stream-3","https://www.humanware.com/wp-content/uploads/2024/11/Victor-Reader-Stream-User-Guide.html"]);
D6("trek",["The Victor Reader Trek (2017) combines the second-generation Stream with the Trekker Breeze GPS. It weighs 5 ounces and measures 114 × 62 × 24 mm, resting easily in one hand. It comes in a fitted silicone case.","The face has three distinctly shaped, widely spaced keys across the top. The middle one is the round Online key that also starts GPS.","Below them is a 12-key telephone keypad: the 5 has two dots, and the 2, 4, 6 and 8 keys have raised semicircles on their edges. A boldly raised line separates the keypad from the bottom keys.","Below the line is an oval key for time, date and sleep timer, then an arrow-shaped Rewind, a rectangular Play/Stop and an arrow-shaped Fast Forward.","The top edge has the SD slot and a 3.5 mm jack; the bottom edge a micro USB port. The left edge has the power button and up and down keys for volume, speed and tone; the right edge has the Record button. The lithium-ion battery is user-replaceable."],{dim:"114 × 62 × 24 mm",wt:"5 oz",price:"$699 USD / $895 CAD (2018)"},["https://afb.org/aw/19/5/15095"]);
// Braille+
D6("brplus",["The APH Braille+ Mobile Manager, made by LevelStar for APH, is a pocket-sized device about 5⅛ inches tall, 3¼ inches wide and 1 inch deep, weighing 7.4 ounces. Its gray plastic case has a brushed aluminum faceplate.","The face looks like a telephone. At the bottom is a 12-key rubber telephone keypad with a nib on the 5. Above it are OK, Menu and Cancel (Cancel is also the power key). Higher up is a four-way navigation pad with a Select button, with Status and Help keys beside it, Program 1 and Program 2 keys at the sides, and a long Applications key between them.","Flanking the rubber keys are nine blue plastic braille keys turned 90 degrees: six dot keys on one side and Shift, Space and Control on the other. To type braille you turn the unit a quarter turn clockwise, so the braille keys are farthest from you and Shift, Space and Control are nearest.","The left side has the volume key, a speaker toggle and a Record button. At the top are a phone-style earpiece in the middle and small stereo speakers on each side. The top edge has line-in, headphone and headset jacks and a mini SD slot. The bottom edge has the keypad lock switch and the power/USB connector.","It came with a 40 GB hard drive and a black nylon case with a belt loop. An optional QWERTY docking station plugs into the connector on the bottom edge."],{dim:"5.125 × 3.25 × 1 in",wt:"7.4 oz",sto:"40 GB hard drive (NFB); a later report says 60 GB"},["https://tech.aph.org/pda_doc.htm","https://nfb.org/images/nfb/publications/bm/bm09/bm0902/bm090211.htm","https://aphmuseum.org/record/aph-braille-mobile-manager/","http://earchive.tpu.ru/handle/11683/26197"]);
// VersaBraille II+
D6("versab2",["The VersaBraille II+ (about 1987) is a portable braille computer in an ivory aluminum chassis with rounded edges. The APH Museum unit measures 3.5 inches high, 15.25 inches wide and 10.25 inches deep. Four black rubber feet tilt the top slightly toward you.","On top are seven brown rubber keys: six braille keys that get taller from the center outward, with a long space bar below. On the left is a 12-key numeric keypad, slightly below separate On and Off buttons and a brown rubber joystick pad.","Above the keyboard, on a brown bar, is a 20-cell piezoelectric refreshable braille display. An aluminum TSI logo plate is in the upper right.","A built-in 3.5-inch floppy drive is in a recess at the front left; the original VersaBraille used cassette tape. A brown plastic carrying handle folds under the back and doubles as a keyboard stand.","The back jack panel has, from left to right, the power jack, an on/off slider, two RS-232 serial ports, an external disk drive jack and a parallel printer jack. Owners David and Howard Goldstein liked its disk drive and printer support but found its proprietary software clumsy and its keyboard hard on the wrists."],{dim:"3.5 × 15.25 × 10.25 in (H × W × D)",disp:"20-cell piezoelectric braille display",sto:"Internal 3.5-inch floppy disk drive"},["https://sites.aph.org/museum-virtual-exhibit/vex2/4C6CA28D-5B55-4717-BDF0-166038125352.htm"]);
// Romeo
const ROMS=["http://atkratter.com/braille/et/romeo.htm","https://www.yumpu.com/en/document/view/6157847/romeo-25-romeo-pro-50-enabling-technologies"];
D6("romeopro50",["The Romeo Pro 50 is the faster sibling of the Romeo 25, sold by Enabling Technologies for schools, small offices and personal use. It has the same rugged case: 21.25 inches wide, 13.25 inches deep and 8.25 inches high (6 inches without the lid), weighing 32 lb (14.5 kg).","It embosses single-sided braille at 50 characters per second on lines of up to 40 characters, with 6- or 8-dot braille and graphics.","Paper is continuous tractor-feed paper with sprocket holes, pulled through by sprocket wheels. Unlike the Romeo 25, it also takes hand-fed single sheets.","Its connections and menus follow the Romeo 25: parallel and serial ports on the back and a front control panel.","Its launch price is not documented in the sources found."],{dim:"21.25 × 13.25 × 8.25 in",wt:"32 lb (14.5 kg)"},ROMS);
D6("romeo",["The Romeo Attaché is a small, portable, single-sided impact braille embosser for teachers and students. It measures 17 × 11.25 × 5.75 inches and weighs 16.75 pounds.","It embosses at 15 characters per second on a line of up to 32 characters.","It uses tractor-feed paper up to 8.5 inches wide, letter-size, with sprocket holes along the edges.","It supports 6- and 8-dot braille and graphics.","Its launch price is not documented in the sources found."],{dim:"17 × 11.25 × 5.75 in",wt:"16.75 lb"},["https://manualzilla.com/doc/5765358/romeo-attach%C3%A9-romeo-attach%C3%A9-pro-romeo-25-and-romeo-pro-50","https://www.yumpu.com/en/document/view/38152810"]);
// Braille Lite 40
D6("blite40",["AccessWorld described Blazie's Braille Lite as identical to the Braille 'n Speak with a braille display added. The Braille Lite 40 (1996) has a 40-cell display. Its exact size and weight are not documented in the sources found; the smaller Braille Lite 18 measured 5 × 8.25 × 2 inches.","Like the Braille 'n Speak, it has a Perkins-style braille keyboard with a space bar, and commands are chords of the space bar plus dot keys.","Its 40-cell refreshable braille display has a cursor routing button above each cell, and it uses advance bars to move through text a display-length at a time.","Speech comes from a built-in DoubleTalk synthesizer through a speaker or earphones.","Its software includes a word processor, calendar, clock and calculator, with optional 8-dot and two-language braille support. It could also serve as a braille display for a computer."],{},["https://afb.org/aw/3/1/14967","http://leb.net/blinux/list-archive/blinux-list/1996/msg00254.html","https://sites.aph.org/museum-virtual-exhibit/vex2/179F821D-F5AB-42AF-9065-355222231963.htm"],"The Braille Lite 40 (1996) added a 40-cell refreshable braille display to the Braille 'n Speak design.");
// glasses
const ES4="https://afb.org/aw/21/11/17299";
D6("es4",["The eSight 4 (2020) is worn like large sunglasses rather than ski goggles. A visor sits in front of your eyes, mounted on a padded 'halo comfort band' that goes around your head. It weighs about 596 g (1.31 lb) with a battery.","The halo band adjusts to your head size. The visor slides closer or farther from your eyes so you can wear prescription glasses underneath, tilts in or out, and flips up out of the way. It doesn't cover your whole face, so you keep some peripheral vision.","An 18-megapixel camera is mounted on the visor just above your nose. Inside the visor are two 1280 × 960 OLED screens, one for each eye.","On the right arm is a small touchpad with a line of bumps before and after it. You slide forward or back to zoom. A power button and a context button are on the headset, and three speakers are built in. A separate wireless remote gives the full menu, and a phone app works too.","At the back of the head, a lithium-ion battery pack plugs into a quick-connect port. Two packs come in the box, each rated at 3 hours, and the headset holds enough charge to swap batteries without shutting down. It has 256 GB of storage, Wi-Fi, Bluetooth and HDMI."],{dim:"Not documented",wt:"596 g (1.31 lb) with battery",price:"$5,950 (2020)",sto:"256 GB",disp:"Two 1280 × 960 OLED screens",syns:"Spoken menus only (no document text-to-speech at review time)"},[ES4,"https://www.visionaid.co.uk/esight-4"]);
D6("es3",["The eSight 3 (February 2017) is a lightweight headset; reports give 104 g for the headset.","It has two OLED displays in front of the eyes and a 21.5-megapixel camera, with up to 24× zoom.","Reports from 2017 describe a separate handheld controller that carries the battery, connected to the headset by cable. Battery life is not documented in the sources used.","Its launch price is not documented in the sources used."],{wt:"104 g (headset)"},["https://www.theverge.com/circuitbreaker/2017/2/16/14637804/esight-3-augmented-reality-headset-legally-blind-see","https://displaydaily.com/the-esight-3-headset-offers-help-to-the-vision-impaired/"]);
D6("es1",["The original eSight, produced commercially from fall 2013, mounts on a prescription-style frame worn like glasses.","At the front is an HD camera, and in front of the eyes are two small near-eye screens showing the enhanced live image.","A wire runs from the headset to a hand-held controller that processes the image and adjusts zoom and contrast.","The controller has a separate battery pack rated at about four hours, carried on a belt or in a pouch. The headset itself has no battery. One user report found it heavier than expected.","It cost $15,000; an introductory 2013 price of $9,750 was also reported."],{price:"$15,000 (introductory 2013 price reported as $9,750)"},["https://betakit.com/kanata-based-esight-launches-smart-glasses-to-cure-the-legally-blind/","https://oepatients.org/esight-up-close/","https://newatlas.com/esight-seeing-aid/29514"]);
D6("es2",["The eSight 2 (May 2015) is a headset with two HD OLED screens in front of the eyes and a high-resolution camera at the front. 2015 reports call it lightweight but don't give a weight.","You adjust magnification, contrast and color for your vision.","Like the first eSight, it uses a separate controller. The controller holds a swappable battery giving about four hours, and it can stay plugged in to charge while you use the headset.","Its price was about $15,000, with financial help available through eSight.","Its exact dimensions are not documented in the sources found."],{price:"About $15,000"},["https://en.wikipedia.org/wiki/ESight","https://healthtechinsider.com/2015/09/03/esight-eyewear-making-daily-life-easier-improving-vision/"]);
D6("esgo",["The eSight Go is shaped like glasses rather than a headset. The glasses part weighs about 170 g.","Inside are two 1920 × 1080 OLED screens with a 45-degree field of view.","An autofocus camera at the front gives up to 24× zoom, with adjustable contrast and color filters.","Instead of a head strap, a battery pack hangs around your neck; a neck lanyard spreads the weight. Batteries in the device and the neck pack give about 3 hours (180 minutes) per charge.","Its price is not documented in the sources used."],{wt:"About 170 g",disp:"Two 1920 × 1080 OLED screens, 45° field of view",bat:"About 3 hours (device plus neck battery pack)"},["https://www.esighteyewear.com/wp-content/uploads/2024/08/eSight-Go-User-Manual_7_24_24.pdf"]);
D6("envgl",["Envision Glasses look like a band across your face: a thin titanium frame on the left and a wider black Glass body on the right. They come assembled in a protective carrying case.","The Glass body forms the right arm and holds all the electronics, about 45 g. At its back end are the USB-C port, the power button and the speaker.","Along the outside of the right arm, against your temple, is the touchpad for taps and swipes.","The body folds forward in front of your right eye. That front part holds a small display that can be switched off and the camera. Moving your finger along the body, you feel an indent at the hinge, which you press for voice commands.","The titanium frame makes up the bridge and left arm and attaches with round metal hinges. Smith Optics frames with swappable lenses can be ordered."],{},["https://support.letsenvision.com/hc/en-us/articles/7604953925777-Hardware-Form-and-Design"]);
D6("echovision",["EchoVision, by AGIGA, looks like everyday round-framed glasses in matte black. It measures 135 mm hinge to hinge, with lenses 52 mm wide and 39 mm tall, a 19 mm bridge and 138 mm temples. AGIGA calls it ultra-light but lists no weight.","It has a 13-megapixel camera for photos and video, a four-microphone array, and open-ear directional stereo speakers that sit near your ears without covering them.","There are two physical buttons, one on each side, and a touchpad on the left arm. It also answers voice commands.","The Pioneer Edition runs about 6 hours per charge and the V1 about 9, with up to 30 hours using the charging case. It connects by Bluetooth 5.3 and dual-band Wi-Fi 5 to a companion app for iPhone or Android.","The box includes a charging case, clip-on sunglasses and a getting-started guide in large print and braille. The price is $599."],{price:"$599",bat:"6 h (Pioneer), 9 h (V1); 30 h with charging case",cpu:"Not documented",wt:"Not documented (described as ultra-light)",syns:"Built-in AI voice (engine not documented)"},["https://agiga.ai/products/echovision-pioneer-edition"]);
D6("allysolos",["Ally Solos Glasses run Envision's Ally AI assistant. They have a classic rectangular frame and weigh about 50 g.","The S/M frame has lenses 51 mm wide and 37 mm tall, a front width of 138 to 149 mm and 163 mm arms.","The camera sits in a hinge (2K-class resolution), with an LED. Whisper open-ear directional speakers let you hear the AI without blocking surrounding sound.","The battery is in quick-swap USB-C charging stems. They run about 10 hours in use, and up to 16 hours claimed. They are IP67-rated.","They connect by Bluetooth 5.2 to the Ally app on iOS or Android and come in a foldable case. The price is $699."],{wt:"About 50 g",price:"$699",bat:"About 10 h operation (up to 16 h claimed); quick-swap USB-C stems",syns:"Ally app voice (engine not documented)"},["https://shop.letsenvision.com/products/ally-solos-glasses"]);
D6("nueasy",["The NuEyes Easy (2016) was developed with Osterhout Design Group (ODG), which made glasses for military uses. It weighs about 125 g, slightly less than an iPhone 6, with no wired controller or battery pack.","It is worn like glasses. Two digital microphones and stereo earphones that attach with magnets are built in, along with haptic vibration in the temples.","An autofocus high-definition camera and an LED light for dark places are at the front. It magnifies up to 12× and boosts contrast.","It is controlled by voice, by manual controls on the glasses, or by a wireless Bluetooth controller worn on a finger.","It has Bluetooth, Wi-Fi, GPS, and other sensors. Its price is not documented in the sources used."],{wt:"About 125 g"},["https://www.newswire.ca/news-releases/nueyes-visual-prosthetic-device-arrives-in-canada-579873661.html"]);
D6("nuepro3",["The NuEyes Pro 3, announced December 15, 2020, is a lightweight black binocular augmented-reality headset weighing 88 g. It is tethered by cable, with no built-in battery mentioned.","It has two 4K displays with a wide field of view of about 51 to 52 degrees.","The main version connects to a proprietary controller with two motion-tracking cameras and a forward-facing 20-megapixel camera.","The Pro 3-C version has a 5-megapixel camera and a USB-C plug for phones, tablets and laptops that output video. A third version is for thermal imaging.","It went on sale December 18, 2020. A UK retailer listed it at £3,995."],{wt:"88 g",disp:"Dual 4K displays, about 51–52° field of view",price:"£3,995 (UK retailer)"},["https://www.prnewswire.com/news-releases/nueyes-technologies-announces-new-pro-3-augmented-reality-smart-glass-solution-301192660.html","https://www.visionaid.co.uk/nueyes-pro-3"]);
// lengthen
const bnscD=DEV.find(d=>d.id==="bnsc").desc;bnscD.push("The APH Museum's Braille 'n Speak describes a sand-colored rigid plastic case with black braille keys and a space key, and black rubber rests on the bottom. The earphone jack and a switch are on the right side; the power jack and serial and disk-drive ports are on the left; the speaker is on top at the right.","In 1996 APH made the original 180K model available on quota funds and began calling it the Braille 'n Speak Classic, to tell it apart from the more powerful 640.","It has no braille display. Everything is spoken, and files can be sent to a printer, embosser or computer through the serial port.");
U(DEV,"bnsc",{src:["https://sites.aph.org/museum-virtual-exhibit/vex2/2AEEBF8E-D463-4207-AA5A-417408112058.htm"]});
const b640=DEV.find(d=>d.id==="bns640").desc;b640.push("On the right side are the earphone jack and a switch; on the left are the power jack and serial and disk-drive ports. The speaker is on top at the right, and black rubber rests are on the bottom (APH museum unit, model BS2).","APH added the 640 to its catalog in 1996, though not on quota. The museum unit has 640K of file memory, 256K of program memory and a built-in rechargeable battery.");
U(DEV,"bns640",{src:["https://sites.aph.org/museum-virtual-exhibit/vex2/2AEEBF8E-D463-4207-AA5A-417408112058.htm"]});
const o2=DEV.find(d=>d.id==="optacon2");o2.desc=[o2.desc[0],o2.desc[1],"Like every Optacon, it has two parts: a small handheld camera probe about the size of a penknife, and a main unit with the tactile pin array, joined by a thin cable. You slide the camera across a line of print with one hand while resting the index finger of the other hand on the array.","Its array is 20 rows by 5 columns of tiny metal rods that vibrate where the camera sees black. As the camera moves, letter shapes flow across your fingertip. Controls have traditionally been minimal: vibration strength, a black/white threshold and a polarity setting.","Canon redesigned the packaging. Special lens modules let the camera read typewriters, calculators and computer screens, and a dedicated computer interface let it read screen text directly. Long-time users largely kept their older 144-pin Optacons."];
U(DEV,"optacon2",{src:["https://interfacemuseum.com/exhibits/optacon-ii/"]});
U(DEV,"envgl",{src:["https://support.letsenvision.com/hc/en-us/articles/7604910350609-Technical-Specifications"]});
const WMV="https://en.wikipedia.org/wiki/Microsoft_text-to-speech_voices",VISTA="https://learn.microsoft.com/en-us/archive/msdn-magazine/2006/january/exploring-speech-recognition-and-synthesis-apis-in-windows-vista",TVR="https://github.com/LouisGameDev/Microsoft-Sam-Mary-Mike-TruVoice-WSAPI4";
U(DEV,"ms_sam",{src:[WMV,VISTA,TVR],ha:"SAPI 4 versions of Sam, Mike and Mary (SAPI 4.0 dates from 1998) and SAPI 5 versions (SAPI 5.1 shipped with Windows XP) differ in speech patterns, pronunciation and some words. Sam's SAPI 5 version has a known 'soy/soi' glitch. Redistributable SAPI 4 versions were offered for Windows 9x but are no longer on Microsoft's site; programs such as Speakonia and TTSReader still run them on XP, Vista and later. Microsoft's 2006 Vista article had Sam say 'Anna will make me redundant'. Windows Vista and 7 shipped no male voice."});
U(DEV,"ms_mike",{src:[WMV,TVR],ha:"Mike existed in SAPI 4 and SAPI 5 forms that sound different. The SAPI 5.1 SDK installs the SAPI 5 Mike, Mary and Sam on Windows NT 4.0 SP6a and Windows 98 onward, and on Vista and later. The SAPI 4 Mike runs on later Windows through third-party programs such as Speakonia."});
U(DEV,"ms_mary",{src:[WMV,TVR],ha:"Mary is Microsoft's optional female voice for Windows 2000 and XP. Its SAPI 5 version was distributed as a Merge Module and installed by apps such as Microsoft Reader; the SAPI 4 version differs in pronunciation. Michael and Michelle, licensed from Lernout & Hauspie, came with Office XP, Office 2003 and Microsoft Reader as other optional voices."});
U(DEV,"ms_anna",{s:{syn:"Concatenative: selects and splices segments from hours of recorded speech (Microsoft, 2006)"},src:[VISTA,WMV]});
U(DEV,"ms_mark",{s:{def:"Not a default; mobile voice added to the Windows 10 US English language pack (Windows Phone 8 and 10 Mobile voice)"},src:[WMV],ha:"Mark and Zira are the Windows Phone 8, 8.1 and Windows 10 Mobile voices, made available on desktop Windows 10. Windows 11 reclassified them as 'legacy voices' after the Narrator natural voices arrived."});
U(DEV,"ms_george",{src:[WMV],ha:"Windows 10 made the mobile voice packs universal: each downloaded language pack adds one male and one female voice. Windows 11 calls these legacy voices."});
const MW="https://www.macworld.com/article/216121/how-to-change-the-mac-s-system-voice.html",NDEF="Not the system default (Alex is the default from Mac OS X 10.5)";
["mac_fred","mac_kathy","mac_ralph","mac_junior","mac_princess","mac_zarvox","mac_whisper","mac_bells","mac_boing","mac_bubbles","mac_cellos","mac_albert","mac_badnews","mac_goodnews","mac_trinoids","mac_hysterical","mac_pipeorgan","mac_deranged","mac_bahh","mac_agnes","mac_bruce","mac_victoria","mac_vicki","mac_samantha","mac_karen","mac_moira","mac_fiona","mac_tessa","mac_serena"].forEach(id=>U(DEV,id,{s:{def:NDEF},src:[MW,"https://www.engadget.com/2007-10-26-24-hours-of-leopard-alex-the-new-voice-of-mac-os-x.html"]}));
