U(DEV,"mac_vicki",{src:["https://alvinalexander.com/mac-os-x/mac-osx-text-to-speech-default-system-voice/"],ha:"A user's guide to Mac OS X speech listed Vicki among the standard system voices alongside Alex, Fred and Bruce."});
