U(DEV,"siri2011",{s:{syn:"Unit selection (Apple says it moved Siri to deep-learning-based voices starting in iOS 10)"},src:["https://machinelearning.apple.com/research/siri-voices"]});
U(DEV,"siri2017",{src:["https://machinelearning.apple.com/research/siri-voices","https://www.isca-archive.org/interspeech_2017/capes17_interspeech.pdf"],ha:"Apple's Machine Learning Journal (August 6, 2017) says Siri voices have been based on deep learning since iOS 10. iOS 11 used on-device deep mixture density networks to guide hybrid unit selection, from a new US English voice talent recorded for over 20 hours. The system was presented at Interspeech 2017."});
U(DEV,"siriquinn",{src:["https://techcrunch.com/2022/02/24/siri-gains-a-new-gender-neutral-voice-option-in-latest-ios-update/","https://www.theverge.com/2022/2/23/22947150/ios-15-4-quinn-siri-voice-5-american"],ha:"It appeared as 'Voice 5' in the iOS 15.4 beta in February 2022. Apple said it was recorded by a member of the LGBTQ+ community. iOS 15.4 shipped March 14, 2022."});
U(DEV,"siri2021",{src:["https://www.apple.com/newsroom/2021/04/ios-14-5-offers-unlock-iphone-with-apple-watch-diverse-siri-voices-and-more/"],ha:"Apple's April 2021 announcement said Siri would no longer default to a female voice; users pick a voice when setting up the device."});
U(DEV,"pico",{s:{syn:"HMM-based statistical parametric synthesis (SVOX)"},src:["https://www.speechtechmag.com/Articles/ReadArticle.aspx?ArticleID=51509","https://www.dre.vanderbilt.edu/~schmidt/android/android-4.0/external/svox/pico_resources/docs/SVOX_Pico_Manual.pdf"],ha:"SVOX announced Pico as a small-footprint engine first released for Symbian, in British English and German. It needs under 400 KB of ROM per engine (plus 400 KB per language and 500 KB per voice) and under 250 KB of RAM on an ARM9-class processor."});
U(DEV,"gtts",{src:["https://www.androidpolice.com/2013/11/06/new-app-google-text-to-speech-arrives-in-the-play-store-paves-way-for-future-updates-fixes-awful-default-voices-on-note-3-and-others/","https://www.theverge.com/2013/11/7/5077034/google-brings-android-text-to-speech-to-google-play","https://9to5google.com/2021/11/09/speech-services-by-google-reaches-10-billion-play-store-downloads/"],ha:"Android Police noted the Play Store app could replace the weak default voices on phones such as the Galaxy Note 3. The app was later renamed Speech Services by Google (Speech Recognition and Synthesis), which passed 10 billion Play Store downloads in November 2021."});
U(DEV,"acapela",{s:{syn:"Unit selection (concatenating studio recordings); later Acapela DNN neural voices"},src:["https://www.acapela-group.com/news/brainy-voices-innovative-voice-creation-based-on-deep-learning-by-acapela-group-research-lab/"]});
U(DEV,"nu_samantha",{s:{syn:"Nuance Vocalizer: concatenates recorded speech units, with a multiform mode that alternates unit selection and statistical parametric generation"},src:["https://docs.nuance.com/speech-suite/voc-dev/primer.html","https://speech.zone/courses/speech-synthesis/module-1-introduction/current-technology/"]});
["nu_tom","nu_daniel"].forEach(id=>U(DEV,id,{s:{syn:"Nuance Vocalizer: concatenates recorded speech units, with a multiform mode that alternates unit selection and statistical parametric generation"},src:["https://docs.nuance.com/speech-suite/voc-dev/primer.html","https://speech.zone/courses/speech-synthesis/module-1-introduction/current-technology/"]}));
U(DEV,"att_voices",{s:{def:"Not a default in any OS; a commercial SAPI 5.1 engine"},src:["https://resna.stanford.edu/SIG-11/archive/FreedomBox.htm","https://www.isca-archive.org/eurospeech_1999/beutnagel99_eurospeech.pdf","https://en.wikipedia.org/wiki/Comparison_of_speech_synthesizers"],ha:"AT&T Labs launched its Natural Voices Text-to-Speech Engine on July 31, 2001. It grew out of AT&T's unit-selection research (Beutnagel and colleagues, Eurospeech 1999), which picks and joins recorded units from a large speech corpus. It shipped about 20 voices across English variants, French, German, Italian and Spanish for Windows and Linux."});
U(DEV,"cepstral_voices",{s:{syn:"Concatenative (Cepstral Swift engine; founders came from Festival/Flite)",def:"Not a default; sold as add-on voices"},src:["https://en.wikipedia.org/wiki/cepstral_(company)","https://www.engadget.com/2005-03-22-hate-fred-and-veronica-try-david-and-linda.html","http://jonhoyle.com/maccompanion/mirror/archives/march2006/software/cepstral.htm"],ha:"Cepstral was founded in Pittsburgh in 2000 by Kevin Lenzo and Alan W Black, authors of Festival-lite. Engadget described David as a new Mac voice in March 2005, and Diane is in the Swift 4.0.1 voice list (2006)."});
U(DEV,"orpheus",{s:{def:"Bundled speech for Dolphin Hal and SuperNova"},src:["https://speech.meridian-one.co.uk/orpheus.html","https://speech.meridian-one.co.uk/newsold.html","https://www.webbie.org.uk/Veli-Pekka/reviews_of_speech_synths.html"],ha:"Later versions added sample-based (concatenative) voices alongside the formant voices. Dolphin transferred the Orpheus rights to Meridian One in August 2006, which added SAPI support, more languages and faster speech."});
U(DEV,"dectalk",{src:["https://www.inc.com/magazine/19840301/3858.html",DTW],ha:"DEC announced the DTC01 in December 1983 and delivered the first units in February 1984. It connected over RS-232C and could also handle telephone touch tones. Dennis Klatt began looking for an industrial partner for his MIT work in 1981."});
U(DEV,"dtpc",{src:["https://manualzilla.com/doc/5788162/doubletalk-pc-lt-user-s-manual","https://www.rcsys.com/dt.htm"],ha:"RC Systems' manual says the card fits an 8- or 16-bit ISA slot and needs no IRQ, DMA or system memory. Its sibling, the DoubleTalk LT, is the external serial version."});
U(DEV,"dtlt",{src:["https://www.rcsys.com/dt.htm","https://www.rcsys.com/Downloads/dtfacts.pdf","https://aphmuseum.org/record/doubletalk-lt-speech-synthesizer/"],ha:"The LT plugs into a serial port on almost any PC or laptop and runs on a 9-volt battery or an AC adapter."});
U(DEV,"echo2",{src:["https://www.duxburysystems.org/downloads/library/texas/apple/manuals/echo.htm","https://www.trs-80.org/echo-80-speech-synthesizer.html"],ha:"Street Electronics' Echo II is a slot card for the Apple II built on Texas Instruments' TMS5200/5220 LPC speech chip. Its Textalker software turned text into speech and its Speakeasy program worked with phonemes, with adjustable pitch and volume."});
U(DEV,"votraxtnt",{src:["https://archive.org/stream/VotraxTypeNTalkManual/Votrax%20Type%20%27N%20Talk%20Manual_djvu.txt","https://www.thehenryford.org/collections/explore/artifact/388923?AssetId=THF156826"],ha:"Its manual is copyrighted 1981, and The Henry Ford museum dates its unit (Model 100) to 1981."});
U(DEV,"votraxpss",{s:{price:"$449 (AbleData listing)"},src:["https://web.archive.org/web/20110606065104/www.abledata.com/abledata.cfm?pageid=113583&productid=94209&top=0&trail=0"],ha:"AbleData described it as a text-to-speech unit using phonetic rules and exception tables, able to play music, with RS-232 and parallel connections."});
U(DEV,"bns2000",{s:{price:"$1,395 one language; $1,595 dual language (Freedom Scientific list price)"},src:["https://www.eyeway.org.in/?q=braille-n-speak-2000","https://www.slideserve.com/kiral/braille-n-speak-2000","https://www.acb.org/high-tech-swap-shop-june-2000"],ha:"In June 2000 ACB's High Tech Swap Shop had a like-new Braille 'n Speak 2000 offered used for $850."});
U(DEV,"romeo",{s:{price:"$2,295 (Enabling Technologies price list, July 1, 2012)"},src:["https://www.yumpu.com/en/document/view/9450828/prices-and-ordering-information-enabling-technologies"]});
U(DEV,"romeo25",{s:{price:"$2,195 (RL & Associates dealer listing, early 2000s)"},src:["http://www.rla.com/embossers.html"]});
U(DEV,"versab",{src:["https://www.duxburysystems.org/downloads/library/history/holladay_tsi.htm","https://sites.aph.org/museum-virtual-exhibit/vex2/A8918B72-511E-44D5-841D-383803736892.htm"],ha:"An early-1980s proposal by a VersaBraille owner quotes its '$5250 price tag', with the state vocational rehabilitation agency paying $2,500. APH calls it the first refreshable braille device designed in the US (December 1979), inspired by Oleg Tretiakoff's Elinfa Digicassette."});
U(DEV,"es4",{s:{dim:"Not published by eSight (its spec sheet lists weight only, 596 g)"},src:["https://esighteyewear.com/wp-content/uploads/2021/08/eSight-4-Technical-Specifications.pdf"]});
// Batch 9
D6("bnsscholar",["The Braille 'n Speak Scholar is a student version of Blazie's Braille 'n Speak pocket notetaker, sold through the American Printing House for the Blind (APH) in partnership with Freedom Scientific. APH recommended it for ages 8 and up and described it as an entry-level notetaker, with a simpler interface for first-time users.","Like the Braille 'n Speak it is based on, the Scholar has no braille display. You type on a seven-key braille-style keyboard: six dot keys plus a space bar, laid out like a Perkins braillewriter. Everything is spoken back through a built-in speaker or an earphone. After the 2004 upgrade the voice was DoubleTalk speech.","Built-in tools include a word processor with file organizing, a braille-to-print back translator for printing in braille or print, and a talking clock. There is also a countdown timer, a stopwatch, a phone directory, a calendar, an appointment book and a scientific graphing calculator.","It connects to a PC through a serial cable. The cable has a 9-pin female plug at the PC end and an 8-pin mini-DIN plug at the Scholar end, so the port on the unit is a small round mini-DIN socket. APH sold parallel-printer and ImageWriter cables separately.","In the box were a soft leather carrying case, a battery charger/AC adapter, an earphone, the serial cable, braille and print reference manuals, a cassette tutorial with demos, a longer manual on CD-ROM, WinDisc and WinPrint software and a one-year warranty. APH product photos show students seated at a table, with their hands on the seven-key keyboard or listening through earphones."],
{price:"$1,140 for the upgraded model (APH 1-07320-01, 2004); listed at $1,249 in 2006, then discounted to $800 for the next 400 units",io:"Serial port (8-pin mini-DIN; PC cable 9-pin female to mini-DIN 8 male)"},
["https://sites.aph.org/news/september-2004/","https://sites.aph.org/news/october-2006/","https://sites.aph.org/news/june-2007/","https://sites.aph.org/news/february-2007/"],
"In September 2004 APH sent its entire stock back to Freedom Scientific to upgrade it with higher-quality DoubleTalk speech, better PC formatting and printing and a better appointment book. The upgraded model got the new catalog number 1-07320-01 and a $1,140 price, and existing owners were offered an upgrade for about $425. In October 2006 APH cut the price from $1,249 to $800 for the next 400 units ordered.");
U(DEV,"speechplus",{s:{wt:"500 g (calculator.org); the Computer History Museum records its S1C example at 1 lb"},src:["https://www.calculator.org/calculators/TSI_SPEECH_PLUS.html","https://www.computerhistory.org/collections/catalog/102662875"]});
U(DEV,"bslx",{src:["https://selvasblv.com/product-history-grid/"],ha:"HIMS (now Selvas BLV) lists the BrailleSense LX as a 2008 notetaker in its official product history, after the original BrailleSense (2004) and before the BrailleSense OnHand (2010). No spec sheet, manual or review of the LX turned up in this research, so its specifications stay undocumented."});
