U(DEV,"versab",{s:{cpu:"Processor model not found in TSI or APH sources. The VersaBraille stored braille on C-60 audio cassettes and showed it on a 20-cell display.",ram:"No RAM figure is published. Storage was by cassette: pages of 1,000 braille cells, about 400 pages per C-60 cassette."}});
U(DEV,"romeo25",{s:{cpu:"Not stated by Enabling Technologies; the published specs give an 18,000-character text buffer and 25 characters per second"}});
U(DEV,"tripletalk",{s:{cpu:"Not stated. The TripleTalk USB Mini has an onboard 8 KB flashable EPROM for field firmware updates.",ram:"Not stated. The USB Mini lists 8 KB of flash EPROM, 11 voices, 10 speeds and 100 pitches, and measures 2.4 × 1.6 × 0.8 in (1.5 oz).",price:"No launch price found for the PCI, USB or serial models. The TripleTalk USB Mini is still listed by Blind Mice Mega Mall."},src:["https://www.blindmicemegamall.com/bmm/shop/Item_Detail?itemid=5323293"]});
