AC({id:"rnib",n:"RNIB (Royal National Institute of Blind People)",f:"1868",h:"The UK's leading sight-loss charity. It sells daily-living products, including the PENfriend audio labeller, which RNIB says is exclusively available from it in the UK.",src:["https://www.rnib.org.uk/living-with-sight-loss/independent-living/labelling/","https://shop.rnib.org.uk/products/rnib-penfriend-3-audio-labeller"]});
const M="Miscellaneous";
AD({id:"ibill",n:"iBill Talking Banknote Identifier",co:"orbit",cat:M,yr:0,y:"Current product; given free by the US Bureau of Engraving and Printing (BEP) through its U.S. Currency Reader Program",o:"A key-fob-sized reader that names US banknotes by voice, tones or vibration.",
 h:"Orbit Research sells the iBill for $99. The BEP gives one free to any blind or visually impaired US citizen or legal resident through its U.S. Currency Reader Program. Large-print, braille and CD instructions are included.",
 s:{price:"$99 (Orbit Research product brief); free through the BEP program",bat:"One AAA battery, typically lasting about a year",dim:"3.0 × 1.6 × 0.7 in",disp:"None; speech, tone or vibration output",used:"Rarely resold, since eligible US users get one free from the BEP"},
 f:["Identifies $1, $2, $5, $10, $20, $50 and $100 bills","Voice, tone or vibration modes","Reads bills in any orientation","Flags bills it cannot identify instead of guessing","Two buttons"],
 src:["https://www.orbitresearch.com/wp-content/uploads/2017/04/Ibill-Txt.txt","https://www.bep.gov/services/currency-accessibility/us-currency-reader-program/us-currency-reader-program-faqs/"],
 desc:["The iBill is a small currency reader from Orbit Research. Orbit describes it as an ultra-slim key-fob design, 3.0 × 1.6 × 0.7 inches, that clips to a key ring or lanyard.","To use it, you slide a bill into the slot and press the button on the side. It announces the denomination in a clear female voice, or for privacy as a pattern of tones or vibrations. The vibration mode also serves people who are deaf-blind.","It has just two buttons and a case of engineering-grade polycarbonate. Orbit says most bills are identified in under a second, with better than 99.9% accuracy, in any orientation. Torn or badly defaced bills are reported as unidentifiable rather than guessed.","It runs on a single user-replaceable AAA battery, which Orbit says lasts over a year with typical use. It can be updated to recognize new banknote designs. Orbit sells it with large-print and audio manuals.","Under the BEP's U.S. Currency Reader Program, eligible blind or visually impaired US citizens and legal residents get one iBill free, with lost or broken units replaced through a toll-free line."]});
AD({id:"colorino",n:"Colorino",co:"caretec",cat:M,yr:0,y:"Current product (Caretec SKU 14000)",o:"A talking color identifier and light detector that recognizes over 150 color shades.",
 h:"Caretec markets the Colorino as already in daily use by many people around the world. It sits below Caretec's Color Star and Color Star Pro, which name more than 1,700 shades.",
 s:{bat:"2 × 1.5 V AAA batteries",wt:"84 g including batteries",dim:"110 × 52 × 25 mm",io:"3.5 mm headphone jack",disp:"None; speech output in natural language, 3 volume levels"},
 src:["https://www.caretec.at/product/colorino-color-and-light-detector/","https://shop.rnib.org.uk/products/colorino-talking-colour-identifier-and-light-detector"],
 desc:["The Colorino is a handheld talking color identifier from the Austrian company Caretec. You hold its tip against clothing, a wall or any surface and it speaks the color in plain language. It recognizes over 150 shades.","It is a small bar about 110 mm long, 52 mm wide and 25 mm thick, and weighs 84 grams with its batteries. The body is black, red and yellow.","It works with just two keys. A built-in loudspeaker has three volume levels, and a 3.5 mm headphone jack lets you hear results privately.","It also detects light, sounding an audio signal (0 to 2.5 kHz, per Caretec's spec table) that shows how bright a light source is, so you can tell whether a lamp is on or find a window. Caretec says it can tell natural from artificial light and measure contrast and brightness.","It runs on two 1.5 V AAA batteries. In the box are the device, batteries, a textile case and printed instructions."]});
AD({id:"prodigyvoice",n:"Prodigy Voice",co:"prodigy",cat:M,yr:2007,y:"2007 (since updated)",o:"A fully talking blood glucose meter, rated the most accessible of four talking meters by AFB Tech.",
 h:"AccessWorld says it first came on the market in 2007. AFB's 2012 update found 13 talking meters but only four that spoke every feature, and rated the Prodigy Voice best overall.",
 s:{price:"$40 (AccessWorld, 2012)",wt:"2.4 oz",dim:"2.2 × 4.0 × 0.8 in",io:"3.5 mm headphone jack, mini-USB for downloading results",disp:"1.2 × 1.5 in monochrome display, 0.63 in characters, 83.6% contrast"},
 src:["https://afb.org/aw/13/2/15850","https://prodigymeter.com/prodigy-voice/"],
 desc:["The Prodigy Voice is a blood glucose meter that speaks every step: setup, testing, results, memory, settings, warnings and errors. AccessWorld measured it at 2.2 by 4.0 by 0.8 inches and 2.4 ounces.","On the front is a 1.2 by 1.5 inch black-on-gray display. Three control buttons sit below it and two direction buttons to its right. The largest is the round power button on the right, with a raised M; it also opens Memory Recall. The middle button is a triangle with a raised S for Settings. The left one has a raised left arrow and repeats the last spoken message. The up and down buttons have raised arrows.","The speaker is below the control buttons. A 3.5 mm headphone jack near the bottom of the right side gives private listening, and below it a mini-USB port sends results to Prodigy's software. A lanyard slot is on the bottom left.","Strips need no coding and use capillary action, so a 0.6 microliter sample is drawn in. A tactile notch shows where to insert the strip. The meter speaks results in 6 or 7 seconds and warns 'Not enough blood' to help avoid false lows.","It stores 450 readings with spoken 7-, 14-, 21-, 28-, 60- and 90-day averages, and in 2012 it cost about $40. AFB Tech found its buttons among the easiest to tell apart by touch and its display the highest-contrast of the meters tested."]});
AD({id:"forav20",n:"Fora V20",co:"fora",cat:M,yr:0,y:"On the US market by 2012 (AccessWorld review)",o:"A talking blood glucose meter with a strip-eject slider and full speech output.",
 s:{price:"$70 (AccessWorld, 2012)",wt:"2.08 oz",dim:"3.69 × 2.25 × 0.78 in",io:"3.5 mm headphone jack, data port"},src:["https://afb.org/aw/13/2/15850"],
 desc:["The Fora V20 is a talking blood glucose meter from Fora Care. AccessWorld measured it at 3.69 by 2.25 by 0.78 inches and 2.08 ounces.","A 1.2 by 1.5 inch black-on-gray display sits above three buttons. The right-most is Power and Memory Recall, with a raised circle around an M. The middle is Settings, with a raised square around an S. The left repeats the last spoken message and has a raised left-pointing arrow. Up and down buttons with raised arrows are to the right of the display.","A strip-eject slider on the top right side pushes used strips out, so you never touch them. The speaker is below the Repeat and Settings buttons.","A 3.5 mm headphone jack is on the bottom left side, with a rubber-covered data port marked PC in raised letters below it. A lanyard slot is on the bottom right.","It stores 450 readings and speaks 7- to 90-day averages, with a language setting. AccessWorld found its buttons among the easiest to tell apart, but its PC software and electronic manual were not screen-reader accessible."]});
AD({id:"forav22",n:"Fora V22",co:"fora",cat:M,yr:0,y:"On the US market by 2012 (AccessWorld review)",o:"A slim talking glucose meter with a round screen and built-in rechargeable battery.",
 s:{price:"$80 (AccessWorld, 2012)",wt:"1.76 oz",dim:"3.75 × 2.00 × 0.44 in",bat:"Built-in rechargeable (charges over mini-USB)",io:"3.5 mm headphone jack, mini-USB"},src:["https://afb.org/aw/13/2/15850"],
 desc:["The Fora V22 is the slimmest of the talking meters AccessWorld tested in 2012: 3.75 by 2.00 by 0.44 inches and 1.76 ounces.","Its 1.2 by 1.6 inch screen is circular. The buttons sit below it in a ring. The slightly recessed power button is in the center, Repeat and Settings are to its right, and the up and down buttons are to its left. The labels are printed, not raised.","A strip-eject slider with raised bumps is to the left of the display. The speaker is directly below the power button.","It has a built-in rechargeable battery. A recessed LED on the right of the front glows red while charging and green when full. On the bottom panel are a 3.5 mm headphone jack on the right and a mini-USB port under a rubber flap with raised lightning-bolt and USB symbols. A lanyard slot is in the corner.","AccessWorld found most buttons nearly flush and hard to feel, though usable with practice. It stores 450 readings with spoken averages."]});
AD({id:"solov2",n:"Solo V2",co:"biosense",cat:M,yr:0,y:"On the US market by 2012 (AccessWorld review)",o:"A low-cost talking blood glucose meter with very large display characters.",
 s:{price:"$17 (AccessWorld, 2012)",wt:"2.2 oz",dim:"3.92 × 2.16 × 0.71 in",io:"Mini-USB data port; no headphone jack",disp:"1.5 × 1.9 in display with 1-inch characters"},src:["https://afb.org/aw/13/2/15850"],
 desc:["The Solo V2 from BioSense Medical Devices was the cheapest fully talking meter in AccessWorld's 2012 review, at $17. It measures 3.92 by 2.16 by 0.71 inches and weighs 2.2 ounces.","Below its 1.5 by 1.9 inch display are two joined buttons: Power and Memory on the left, Repeat on the right. Their icons are not tactile, and AccessWorld found them hard to tell apart. The speaker is beneath them.","On the top of the right side are up and down buttons with raised arrows and, below them, a small round Settings button. These need considerable force to press. A mini-USB data port is at the bottom of the right side. There is no headphone jack.","It holds 500 readings, more than the other meters tested, and has an alarm setting. It does not speak the time of past readings, though the screen shows it.","For people with low vision, its 1-inch characters were the largest of any meter tested, with a 73.9% contrast ratio."]});
AD({id:"bradley",n:"Bradley tactile watch",co:"eone",cat:M,yr:2013,y:"Kickstarter mid-2013; first batch planned for November 2013",o:"A titanium watch read by touch, with ball bearings for the hours and minutes.",
 h:"Named for Paralympic swimmer Bradley Snyder, who lost his sight to an IED in Afghanistan. Founder Hyungsoo Kim designed it so blind wearers would not wear something that called attention to their disability. By 2014 SJX reported that only 1 to 2% of buyers were blind.",
 s:{dim:"40 mm diameter",price:"No verified launch price; the 2013 Kickstarter is cited in the Boston Globe and SJX",disp:"Tactile dial; no crystal",bat:"Quartz (Ronda movement)"},
 src:["https://www.bostonglobe.com/business/2013/07/11/watch-for-blind-kickstarter/0dt8VUnqc0hZ3z3gxUXROP/story.html","https://watchesbysjx.com/2014/04/introducing-the-eone-bradley-a-tactile-way-to-tell-the-time.html"],
 desc:["The Bradley is a wristwatch you read by touch. It looks like an ordinary modern watch: a 40 mm titanium case with a Ronda quartz movement inside.","There is no crystal over the dial, so your fingers can reach it. Raised markers around the face show the hours. The 12 o'clock marker is a triangle, and the 3, 6 and 9 markers are elongated so you can find the quarters.","Time is shown by two small ball bearings instead of hands. One rolls in a track on the face for the minutes, and the other runs around the outside edge of the case for the hours. The movement drives them with magnets.","If the bearings are knocked out of place you can nudge them freely, and a few shakes snap them back to the correct time. You set the time with the crown.","Eone designed it with blind testers, who did not want a watch that drew attention to their disability. It is named after Navy veteran and Paralympic gold medalist Bradley Snyder, and SJX reported that most buyers are sighted people who like checking the time discreetly."]});
AD({id:"penfriend3",n:"PENfriend 3 audio labeller",co:"rnib",cat:M,yr:0,y:"Current product (RNIB DL128)",o:"A pen-shaped recorder that plays your own voice labels when touched to a coded sticker.",
 h:"RNIB sells it exclusively in the UK. It is made with TouchSpot Audio Limited and also plays MP3 music and talking books.",
 s:{price:"£114 inc. VAT (RNIB shop)",sto:"16 GB internal (about 250 hours), SD card up to 32 GB",wt:"54 g without lanyard",dim:"15 × 2.5 × 2 cm, 1 cm tip"},
 src:["https://shop.rnib.org.uk/products/rnib-penfriend-3-audio-labeller","https://www.rnib.org.uk/living-with-sight-loss/independent-living/labelling/"],
 desc:["The PENfriend 3 is a talking pen for labelling things around the home. You stick a coded label on an item, touch the pen tip to it and record a message. Touch the label again later and the pen plays your recording back.","It is a slim black pen, 15 cm long, 2.5 cm wide and 2 cm deep, with a 1 cm tip. It weighs 54 grams without its lanyard and has four tactile yellow buttons.","Each label holds up to an hour of audio, and labels can be re-recorded. The 16 GB internal memory holds about 250 hours of recordings, and an SD card adds up to 32 GB. Recordings can be backed up and restored with a computer.","In the box are 21 rectangular tactile labels, 84 small round orange and yellow labels, a key fob with four recording spots and a lanyard. RNIB suggests uses such as freezer food with use-by dates and cooking instructions, clothing colors and washing care, medicines, paperwork and seed packets.","It doubles as an MP3 music player and talking-book player. RNIB lists it at £114 including VAT, and eligible buyers can get VAT relief."]});
// Batch 13 (restored after box restore): sourced notes replacing remaining not-documented phrases; version-table cells; company founding notes
Object.assign(DEV.find(x=>x.id==="bslx"),{"o":"A 2008 BrailleSense variant. HIMS lists it as its 2007 to 2008 notetaker, between the original BrailleSense (2004) and the BrailleSense OnHand (2010). Neither HIMS nor Selvas BLV publishes a spec sheet for it."});
Object.assign(DEV.find(x=>x.id==="abt3"),{"y":"No release year was found in the NFB's 2026 Braille technology timeline or in ALVA material. For context, ALVA's cursor-routing patent was filed in the Netherlands in 1987 and granted in the US in 1991 (NFB timeline)."});
Object.assign(DEV.find(x=>x.id==="accent"),{"y":"A serial-port synthesizer of the DOS era. No release year was found in the NFB timeline or in the archived Aicom material searched."});
Object.assign(DEV.find(x=>x.id==="apollo"),{"y":"A hardware speech synthesizer from Dolphin's DOS-era range, alongside Hal for DOS. No release year was found in Wikipedia's list of screen readers or on Dolphin's site."});
Object.assign(DEV.find(x=>x.id==="mac_vicki"),{"y":"2003: added in Mac OS X 10.3 Panther (released October 24, 2003) and made the default voice. Vicki is an enhanced Victoria built from much larger diphone samples, almost 20 times its size (AppleInsider; Wikipedia, PlainTalk).","src":["https://www.wap.org/journal/lionspeak/","https://www.macworld.com/article/216121/how-to-change-the-mac-s-system-voice.html","https://www.engadget.com/2007-10-26-24-hours-of-leopard-alex-the-new-voice-of-mac-os-x.html","https://alvinalexander.com/mac-os-x/mac-osx-text-to-speech-default-system-voice/","https://appleinsider.com/articles/11/03/02/inside_mac_os_x_10_7_lion_dozens_of_high_quality_new_multilingual_speech_voices","https://en.wikipedia.org/wiki/MacInTalk","https://forums.appleinsider.com/discussion/31630/panther-and-vicki"]});
Object.assign(DEV.find(x=>x.id==="vocalizer"),{"y":"Mid-2000s to present. Nuance built its TTS line through acquisitions, including Rhetorical (2004) and SVOX (2011), and Vocalizer was the TTS in the first-generation Victor Reader Stream (2007). The first release date of the Vocalizer brand itself was not found."});
Object.assign(DEV.find(x=>x.id==="nu_tom"),{"h":"A US English male Nuance Vocalizer voice. Freedom Scientific's JAWS 18 notes describe Samantha, Tom, Daniel and Karen as familiar voices updated for Vocalizer Expressive 2.2, and Nuance's Vocalizer documentation lists Tom. Freedom Scientific's JAWS 18 notes (2016) describe it as a familiar voice updated for Vocalizer Expressive 2.2. Apple also shipped Tom and Samantha as new voices in Mac OS X 10.7 Lion in 2011 (AppleInsider). No first-release date was found in Nuance's documentation.","src":["https://docs.nuance.com/nuance-vocalizer-for-enterprise/voc-dev/lang.html","https://saomaicenter.org/en/blog/whats-new-jaws-180","https://docs.nuance.com/speech-suite/voc-dev/primer.html","https://speech.zone/courses/speech-synthesis/module-1-introduction/current-technology/","https://appleinsider.com/articles/11/03/02/inside_mac_os_x_10_7_lion_dozens_of_high_quality_new_multilingual_speech_voices"]});
Object.assign(DEV.find(x=>x.id==="nu_samantha"),{"h":"A US English female Nuance Vocalizer voice. Freedom Scientific's JAWS 18 notes describe Samantha, Tom, Daniel and Karen as familiar voices updated for Vocalizer Expressive 2.2, and Nuance's Vocalizer documentation lists Samantha. Freedom Scientific's JAWS 18 notes (2016) describe it as a familiar voice updated for Vocalizer Expressive 2.2. Apple also shipped Tom and Samantha as new voices in Mac OS X 10.7 Lion in 2011 (AppleInsider). No first-release date was found in Nuance's documentation.","src":["https://docs.nuance.com/nuance-vocalizer-for-enterprise/voc-dev/lang.html","https://saomaicenter.org/en/blog/whats-new-jaws-180","https://docs.nuance.com/speech-suite/voc-dev/primer.html","https://speech.zone/courses/speech-synthesis/module-1-introduction/current-technology/","https://appleinsider.com/articles/11/03/02/inside_mac_os_x_10_7_lion_dozens_of_high_quality_new_multilingual_speech_voices"]});
Object.assign(DEV.find(x=>x.id==="nu_daniel"),{"h":"A British English male Nuance Vocalizer voice. Freedom Scientific's JAWS 18 notes describe Samantha, Tom, Daniel and Karen as familiar voices updated for Vocalizer Expressive 2.2, and Nuance's Vocalizer documentation lists Daniel. Freedom Scientific's JAWS 18 notes (2016) describe it as a familiar voice updated for Vocalizer Expressive 2.2. Apple also shipped Tom and Samantha as new voices in Mac OS X 10.7 Lion in 2011 (AppleInsider). No first-release date was found in Nuance's documentation.","src":["https://docs.nuance.com/nuance-vocalizer-for-enterprise/voc-dev/lang.html","https://saomaicenter.org/en/blog/whats-new-jaws-180","https://docs.nuance.com/speech-suite/voc-dev/primer.html","https://speech.zone/courses/speech-synthesis/module-1-introduction/current-technology/","https://appleinsider.com/articles/11/03/02/inside_mac_os_x_10_7_lion_dozens_of_high_quality_new_multilingual_speech_voices"]});
Object.assign(DEV.find(x=>x.id==="acapela"),{"y":"Current. Acapela voices remain in products in 2026: Stream 3 firmware 1.7 (September 2026) supports up to two Acapela voices. The founding year of the Acapela Group could not be confirmed, because its about page and Wikipedia did not load in this research."});
Object.assign(DEV.find(x=>x.id==="neo_voices"),{"y":"2001 to 2002: Kate was released in September 2001 and Paul in May 2002 (Wikipedia, NeoSpeech). Julie's release date was not found."});
Object.assign(DEV.find(x=>x.id==="att_voices"),{"y":"2001: AT&T Labs launched the Natural Voices TTS Engine on July 31, 2001."});
Object.assign(DEV.find(x=>x.id==="softvert"),{"y":"DOS era: Wikipedia's list of screen readers gives it as a commercial DOS screen reader from TeleSensory Systems. No release year was found."});
Object.assign(DEV.find(x=>x.id==="haldos"),{"y":"DOS era. Wikipedia lists Hal for both DOS and Windows; the Windows version was later superseded by SuperNova and Dolphin ScreenReader. The DOS release year was not found."});
Object.assign(DEV.find(x=>x.id==="msscreenreader"),{"y":"2000: Microsoft's built-in screen reader, Narrator, debuted in Windows 2000 on February 17, 2000 (AbilityNet, 'Microsoft Narrator turns 21')."});
Object.assign(DEV.find(x=>x.id==="prudence"),{"y":"Current Android app. Neither its Google Play listing nor AudibleGame's page shows a first-release date."});
Object.assign(DEV.find(x=>x.id==="jenux"),{"y":"Active by January 2023 (the Jenux-2023.01.17 dual ISO on the Blinux list); ISO, Docker and Crostini builds were updated in October 2026."});
Object.assign(DEV.find(x=>x.id==="merlin"),{"y":"An Enhanced Vision desktop video magnifier, now sold under Vispero. Vispero's site gives no introduction year."});
Object.assign(DEV.find(x=>x.id==="svgrad"),{"y":"A HumanWare desktop video magnifier. HumanWare's store page gives no introduction year."});
Object.assign(DEV.find(x=>x.id==="nuepro4"),{"y":"By October 2024, when the Pro 4 LV brochure was published. Its predecessor, the Pro 3, was announced on December 15, 2020.","h":"NuEyes announced the Pro 3 on December 15, 2020 (see its entry). The Pro 4 is sold through eye-care professionals; a Pro 4 LV brochure was published in October 2024. The earliest dated Pro 4 material found is the October 2024 brochure."});
Object.assign(DEV.find(x=>x.id==="braillo440sf"),{"y":"Predates the S2 line, which Braillo introduced after American Thermoform bought the company in 2016 (braillo.com). The original introduction year was not found."});
Object.assign(DEV.find(x=>x.id==="openbook"),{"y":"An Arkenstone product. Arkenstone merged with Henter-Joyce and Blazie Engineering in 2000 to form Freedom Scientific, which continued OpenBook (Wikipedia). The first release year was not found."});
Object.assign(DEV.find(x=>x.id==="sonar"),{"y":"Active by 2015. An August 2015 opensource.com article by one of its co-developers describes Sonar as based on Manjaro Linux, in three editions (two desktops and a command-line edition)."});
Object.assign(DEV.find(x=>x.id==="talkingarch"),{"y":"Active by 2015 (opensource.com describes it as a speech- and braille-enabled Arch Linux); the last release was reported in 2017."});
Object.assign(DEV.find(x=>x.id==="blazeez"),{"o":"A HIMS book player in the Blaze line. HIMS lists the Blaze EZ (2014) under 'DAISY Player and OCR Multi Player' in its product history, between the BookSense XT (2009) and the Blaze ET (2015)."});
Object.assign(DEV.find(x=>x.id==="blazeet"),{"o":"A HIMS book player in the Blaze line. HIMS lists the Blaze ET (2015) under 'DAISY Player and OCR Multi Player' in its product history, after the Blaze EZ (2014) and before the SensePlayer OCR (2023)."});
Object.assign(DEV.find(x=>x.id==="senseplayer"),{"o":"A HIMS player with OCR. HIMS lists the SensePlayer OCR (2023) as its latest 'DAISY Player and OCR Multi Player', following the Blaze ET (2015)."});
Object.assign(DEV.find(x=>x.id==="govision"),{"o":"A HIMS video magnifier. HIMS lists GoVision (2016) under 'Low Vision Digital Magnifier' in its product history."});
Object.assign(DEV.find(x=>x.id==="govisionpro"),{"o":"A later GoVision model. HIMS lists GoVision Pro (2018) under 'Low Vision Digital Magnifier', after GoVision (2016) and before GoVision Move (2026)."});
Object.assign(DEV.find(x=>x.id==="romeo25"),{"y":"In use by 2006, per an Enabling Technologies brochure. The introduction year was not found."});
Object.assign(DEV.find(x=>x.id==="romeopro50"),{"y":"Sold alongside the Romeo 25 in Enabling Technologies' brochure. The introduction year was not found in that brochure or at atkratter.com."});
Object.assign(DEV.find(x=>x.id==="lh_tts3000"),{"h":"Other languages included British English (Carol, Peter), Dutch (Linda, Alexander), French (Véronique, Pierre), German (Anna, Stefan), Italian (Barbara, Stefano), Japanese (Naoko, Kenji), Mexican Spanish (Pedro and others), Korean and Russian (Boris). It must predate 2001, when Lernout & Hauspie (founded in 1987) went bankrupt after a fraud scandal (Wikipedia). The exact release year was not found.","src":["https://help.genesys.com/pureconnect/mergedprojects/wh_id/desktop/hid_tts_speech_modes.htm","https://learn.microsoft.com/en-us/windows/win32/lwef/accessing-a-speech-engine-in-your-code","https://patents.google.com/patent/US6665641B1/en","https://www.isca-archive.org/icslp_2000/coorman00_icslp.pdf","https://en.wikipedia.org/wiki/Lernout_%26_Hauspie"]});
Object.assign(CO.find(x=>x.id==="aicom"),{"id":"aicom","n":"Aicom Corporation","f":"Founding year not found (searched NFB timeline and archived Accent material)","h":"Maker of the Accent SA serial speech synthesizer.","src":["https://www.freelists.org/post/jfw/jaws-61,13","http://cd.textfiles.com/nfbfiles/newsletters/VN0892.TXT"]});
Object.assign(CO.find(x=>x.id==="thiel"),{"id":"thiel","n":"Thiel","f":"Founding year not found; active in the US through VTEK by about 1986","h":"A German maker of high-speed embossers such as the Beta-X3, distributed in the US by VTEK around 1986.","src":["https://nfb.org/sites/default/files/images/nfb/publications/fr/fr28/fr280109.htm"]});
Object.assign(CO.find(x=>x.id==="att"),{"id":"att","n":"AT&T Labs (Natural Voices)","f":"AT&T Labs was formed in 1996; Natural Voices launched in 2001","h":"AT&T Natural Voices were concatenative voices, including Crystal and Mike.","src":["https://jctnpedia.fandom.com/wiki/Text-to-Speech_Downloadables_List"]});
Object.assign(CO.find(x=>x.id==="linuxcommunity"),{"id":"linuxcommunity","n":"Linux accessibility community","f":"Not a company; projects date from 1995 (BRLTTY) and 1998 (Speakup)","h":"Independent open-source projects: Speakup (Kirk Reiser, 1998), BRLTTY (Nikhil Nair and James Bowden, 1995), Emacspeak (T. V. Raman, 1994), Fenrir (2016–2017) and the Jenux distribution (Daniel Nash).","src":["https://lkml.iu.edu/9810.3/0735.html","https://brltty.app/pipermail/brltty/2015-December/013007.html"]});
Object.assign(CO.find(x=>x.id==="jieshuodev"),{"id":"jieshuodev","n":"Weiliang Li (Jieshuo developer)","f":"Individual developer; start date not found","h":"A Chinese developer who makes the Jieshuo (Commentary, also called TalkMan) Android screen reader.","src":["https://accessibleandroid.com/glossary/jieshuo-2/"]});
Object.assign(CO.find(x=>x.id==="prudence"),{"id":"prudence","n":"Prudence Interactive","f":"Founding year not found on Google Play or AudibleGame","h":"Maker of Prudence Screen Reader for Android, which supports more than 40 languages and adds OCR and translation.","src":["https://www.audiblegame.com/prudence-screen-reader"]});
