Object.assign(OSL.find(x=>x.id==="keysoft"),{"id":"keysoft","n":"KeySoft","co":"hw","h":"The BrailleNote software suite (word processor, book reader, email, web, planner) from Pulse Data and HumanWare. It ran on Windows CE from 2000, moved to Android on the BrailleNote Touch (2016), and to Windows 11 on the BrailleNote Evolve (2026). KeySoft applications also run on the Monarch.","v":[["6.2","2005","Shipping version on the BrailleNote mPower at launch."],["7.5","By 2008","Last release for BrailleNote and VoiceNote Classic. Build 29 (May 2008) added 802.11g Wi-Fi card support (Ambicom WL54G, USR5421), fixed appointment scheduling, fixed USB and CD-ROM devices being identified as printers, and fixed spell-check word retention."],["8.0","Announced January 2009; released July 2009","For mPower and PK only, not Classic. Added real-time communication features, a richer book-reading experience and a 90-day Sendero GPS trial. Required one SMA count; free for units bought after January 1, 2009. mPower releases stopped at 8.1."],["9.1","Date not given in the sources cited for this history","For the Apex. Enhanced tables and formatting support."],["9.3","Previewed March 31, 2012","For the Apex. Bluetooth file transfer, opening Word 2007/2010 and OpenOffice documents, saving to online services such as Google Docs, and third-party development tools with a BrailleNote simulator."],["9.4.1","2014","For the Apex. Added KeyMaps, a free virtual navigation and map-exploration tool."],["KeySoft for Android","2016","On BrailleNote Touch (Android 4.4)."],["Touch Plus (Android 8.1)","February 2019","BrailleNote Touch Plus ships with Android 8.1."],["KeySoft Lite","February 2021","On the Brailliant BI 20X and BI 40X displays."],["Touch Plus update","September 2025","KeyMath renamed KeyGraph; KeyRecorder added (user reports). Still Android 8.1."],["KeySoft on Windows 11","2026","On BrailleNote Evolve, alongside a customized NVDA."]],"d":["bnclassic","bnpk","bnmp","bnmpqt","vnclassic","vnmp","vnapex","bnapex","bnapex18","bntouch","bntp","evolve","dbc","monarch","bi40x"],"src":["http://therangerstation.blogspot.com/2008/05/press-release-humanware-releases.html","http://www.nfbnet.org/pipermail/nfbwatlk_nfbnet.org/2009-January/000811.html","http://www.nfbnet.org/pipermail/nfbcs_nfbnet.org/2009-July/001125.html","https://www.mail-archive.com/braillenote@list.humanware.com/msg78489.html","http://nfbnet.org/pipermail/nabs-l_nfbnet.org/2014-March/033135.html","https://www.perkins.org/resource/braillenote-touch-plus-update/","http://kentucky-acb.org/pipermail/scholarship-comm_kentucky-acb.org/attachments/20210506/d8ae4b7e/attachment-0003.pdf","https://www.applevis.com/forum/assistive-technology/braille-note-touch-plus-finally-get-update-after-three-whole-years-what"]});
Object.assign(OSL.find(x=>x.id==="himsos"),{"id":"himsos","n":"HIMS BrailleSense software","co":"hims","h":"HIMS's notetaker software. It ran on Windows CE through the U2 generation and on Android from the Polaris (2017).","v":[["Braille Hansone","2002","HIMS's first notetaker."],["BrailleSense (Windows CE.NET)","2004","Up to seven open applications; HBL braille documents; no spell checker at review time (January 2005)."],["U2 firmware 9.0","Final U2 release","Device status checking, improved file management, PDF conversion, email, DAISY and YouTube tools, VNC viewing and a startup wizard."],["Polaris (Android 5.1.1)","2017","First Android BrailleSense."],["Polaris firmware 3.4","April 2020","Google Drive access from the File Manager."],["BrailleSense 6 firmware 2.0","December 2023","Upgraded Android 10 to Android 12."],["BrailleSense 6 firmware 2.1 and 2.5","Date not given in the sources cited for this history","Release notes not documented in the sources found."],["BrailleSense 6 firmware 3.0","Date not given in the sources cited for this history","Redesigned menu, new browser, Braille Practice, Word Processor formatting and stability improvements."],["BrailleSense 7 (Android 15)","2026","Adds Gemini AI."]],"d":["u2","u2qt","u2mini","polaris","polmini","bs6","bs6mini","bs7","hansone","bsense"],"src":["https://sastltd.zohodesk.eu/portal/en/kb/articles/firmware-version-9-0-release-notes","https://sastltd.zohodesk.eu/portal/en/kb/articles/braillesense-6-upgrade-android-from-10-0-to-12-0","https://sastltd.zohodesk.eu/portal/en/kb/articles/braillesense-6-firmware-3-0-releas-information","https://afb.org/aw/6/1/14662","https://www.perkins.org/resource/braillesense-polaris-april-2020-firmware-upgrade/"]});
Object.assign(OSL.find(x=>x.id==="android"),{"id":"android","n":"Android (on blindness devices)","co":"google","h":"Google's mobile OS, used by braille notetakers and magnifiers from 2016.","v":[["Android 4.4","2016","BrailleNote Touch."],["Android 5.1.1","2017","BrailleSense Polaris."],["Android 8.1","2019","BrailleNote Touch Plus."],["Android 10 (later 12)","2021","BrailleSense 6."],["Android 12","2024","Braille eMotion; current Connect 12 tablet."],["Android (version not stated in the sources cited)","2024","Monarch."],["Android 15","2026","BrailleSense 7."]],"d":["bntouch","polaris","polmini","bntp","bs6","bs6mini","emotion","connect12","monarch","bs7","bplus18"],"src":["https://www.humanware.com/microsite/bntouch/specs.php","https://www.himsintl.com/en/company/prd_history.php"]});
Object.assign(OSL.find(x=>x.id==="jawsv"),{"id":"jawsv","n":"JAWS versions","co":"fs","h":"JAWS release history and Windows support by version. Freedom Scientific releases a new major version around the end of October each year.","v":[["JAWS for DOS","1989","First JAWS, from Henter-Joyce (founded 1985)."],["JFW 1.0","January 1995","First Windows version; Windows 3.1 and Windows for Workgroups 3.11."],["2.0","About 1996","Windows 95 support."],["4.0","September 14, 2001","Many user interface changes; an optional tutor and access-key help."],["4.5","August 30, 2002","Quick navigation keys for web pages."],["JAWS for Pocket PC","2002 to 2003","On PAC Mate."],["5.0","October 9, 2003","Big improvements to Internet support; Speech and Sounds Manager to indicate fonts, controls and web elements by voice or sound."],["6.0","March 3, 2005","Internet licensing; separate user settings; a demo of FSReader, Freedom Scientific's DAISY reader, for training material."],["7.0","October 14, 2005","Runs from a thumb drive; Firefox support; dropped Windows 95."],["7.1","June 21, 2006","Automatic updates; DOM-based web engine."],["8.0","November 17, 2006","RealSpeak Solo voices; Windows Vista; dropped Windows 98 and ME."],["9.0","November 19, 2007","HTML composition support (for example, writing HTML email); new Adjust JAWS Options dialog."],["10.0","November 3, 2008","JAWS Tandem for remote access to another computer running JAWS; support for iTunes 8 and the iTunes Store."],["11.0","October 23, 2009","Research It (definitions, weather, sports scores); shipped on DVD with the full FSReader 2.0."],["12.0","October 21, 2010","Settings Center, virtual ribbon, ARIA improvements."],["13.0","October 24, 2011","Built-in OCR for on-screen graphics; Quick Settings replaced Adjust JAWS Options."],["14.0","October 22, 2012","Windows 8 support; Flexible Web."],["JAWS 15","November 2014 (per AT Observatory; Freedom Scientific's own date list was not checked)","Touch cursor navigation and Windows 8 touch support, FSReader 3, Speech History and braille improvements. Last version for Windows XP."],["JAWS 17","Date not given in the sources cited for this history","Last version for Windows Vista."],["JAWS 18","2017","Free migration target for Window-Eyes 9 owners; Vocalizer Expressive 2.2 voices."],["JAWS 2018","October 2017","Year-based naming begins."],["Picture Smart","2019","Image description feature introduced."],["JAWS 2021","2020","Last version for Windows 7."],["JAWS 2022","2021","Minimum version for Windows 11 at its release."],["JAWS 2023","2022","Dropped 32-bit systems; first with ARM64 (Windows 11) support."],["JAWS 2024 March update","March 2024","Picture Smart AI."],["JAWS 2025","October 2024","FSCompanion AI assistant; minimum for Windows 11 25H2."],["JAWS 2026 (2026.2609.84)","September 2026 update","AI page explorer, AI graphic labeling on by default, Java Swing improvements, braille text-attribute indicators, EPUB improvements. Eloquence and Vocalizer Expressive included."]],"d":["jawsdos","jaws","pacmate","pacomni"],"req":["Current: Windows 11, 10 or Server 2025, 2022, 2019 or 2016; x64, plus ARM64 on Windows 11","2.0 GHz i5 dual-core; 16 GB RAM recommended; 2 GB disk, SSD recommended; DirectX 9 graphics (WDDM 1.0), 1024x768; sound card","Windows 7: JAWS 2021 or earlier","Windows Vista: JAWS 17 or earlier","Windows XP: JAWS 15 or earlier","JFW 1.0: Windows 3.1 or Windows for Workgroups 3.11"],"src":["https://support.freedomscientific.com/Downloads/JAWS/jaws-system-requirements","https://sastltd.zohodesk.eu/portal/en/kb/articles/jaws-zoomtext-fusion-and-windows-11-0","https://www.avh.asso.fr/implantations/certam/evaluations-de-produits/jaws-version-2026","https://support.freedomscientific.com/Downloads/jaws","https://www.liquisearch.com/jaws_screen_reader/release_history","https://en.wikipedia.org/wiki/JAWS_(screen_reader)","https://blog.freedomscientific.com/2024-year-end-review/","https://support.freedomscientific.com/Downloads/JAWS/JAWS-System-Requirements","http://www.liquisearch.com/jaws_screen_reader/release_history","https://www.tecnoaccesible.net/en/content/jaws-15"]});
Object.assign(OSL.find(x=>x.id==="talkbackv"),{"id":"talkbackv","n":"TalkBack and Android screen-reader milestones","co":"google","h":"TalkBack and Android screen-reader milestones, from Google's 2009 announcement and Wikipedia's release table.","v":[["TalkBack, SoundBack and KickBack","October 20, 2009","Released for Android 1.6 Donut's new accessibility API; trackball navigation; might need an Android Market install."],["Android 4.0","October 2011","TalkBack added to the system."],["Android 4.1","2012","Single-finger gestures."],["BrailleBack","2012","Braille display support."],["5.2","April 2017","Verbosity settings; Select to Speak."],["6.1","Early 2018","Language switching."],["6.2","June 2018","Renamed Android Accessibility Suite."],["7.2","November 2018","Changes not listed in the sources cited for this history"],["7.3","March 2019","Screen search."],["8.2","April 2020","Braille keyboard."],["Android 11 / One UI 3.0","2020","Multi-finger gestures on Pixel and Samsung; Samsung Voice Assistant discontinued in favor of Samsung TalkBack."],["9.1","February 2021","Multi-finger gestures and a new menu."],["12.1","September 2021","Image text captions."],["Android 12","2021","Multi-finger gestures on more devices."],["Android 13","2022","Built-in braille display support in TalkBack."],["17.1","September 17, 2026","Requires Android 9 or later."]],"d":["talkback","samsungva"],"src":["https://accessibleandroid.com/a-decade-with-android-highlighting-observations-and-shifts/","https://accessibleandroid.com/opinion-why-samsung-google-talkback-separation-is-nothing-but-a-headache/","https://opensource.googleblog.com/2009/10/talkback-open-source-screenreader-for.html","https://en.wikipedia.org/wiki/TalkBack"],"req":["TalkBack 17.1: Android 9 or later","2009: Android 1.6"]});
Object.assign(OSL.find(x=>x.id==="wev"),{"id":"wev","n":"Window-Eyes versions","co":"gw","h":"Window-Eyes release history from GW Micro's archived version history.","v":[["1.0","October 16, 1995","First release."],["2.0","July 5, 1997","Listed at $75 in GW Micro's history."],["3.0","January 11, 1999","Changes not listed in the sources cited for this history"],["4.0","October 16, 2000","Listed at $100."],["4.5","September 16, 2003","Major web navigation improvements: moving by heading, list, paragraph and form control; Smart Paragraph and Smart Table modes; keyboard verbosity controls; and more stable browser support."],["5.0","January 19, 2005","Full Microsoft Word support (tables, columns, fields, spelling and grammar checking, comments and tracked changes), a named color dictionary, and better Mozilla support. Announced through public betas."],["6.0","December 4, 2006","Listed at $150."],["7.0","September 15, 2008","Standard scripting added; listed at $175."],["7.5","March 2011","Officially released March 2011. The 7.5.1 update added Firefox and Internet Explorer 9 support, Office fixes, interface improvements, and Outlook and Thunderbird enhancements."],["8.0","December 5, 2012","Listed at $175."],["Window-Eyes for Office","2014","Free for Microsoft Office users, after GW Micro merged with Ai Squared in 2014."],["9.0","January 12, 2015","Owners of 9.0 or later were later offered a free JAWS 18 migration."],["9.4","March 8, 2016","Supports Windows Vista, Server 2008, 7, 8 and 10."],["9.5.3","September 14, 2016","Last version in GW Micro's history."],["End of sales","By July 2017","No longer sold or updated; still worked on Windows 7, 8.1 and 10."]],"d":["weyes"],"req":["9.4: Windows Vista, Server 2008, 7, 8 or 10","Last documented: Windows 7, 8.1 or 10"],"src":["https://afb.org/aw/3/1/14962","https://afb.org/aw/18/6/15200","https://web.archive.org/web/2016/http://www.gwmicro.com/Window-Eyes/Version_History/","https://en.wikipedia.org/wiki/Window-Eyes","https://afb.org/aw/5/3/14752","https://www.freelists.org/post/slikom/Fw-WindowEyes-50-Beta-1-Has-Been-Released","https://afb.org/aw/6/2/14635","https://window-eyes.informer.com/versions/"]});
Object.assign(OSL.find(x=>x.id==="sysaccv"),{"id":"sysaccv","n":"System Access milestones","co":"serotek","h":"Serotek's and Pneuma Solutions' System Access screen reader. Per-version release notes were not found.","v":[["FreedomBox","Date not given in the sources cited for this history","Serotek's FreedomBox was a simplified, speech-driven portal for the web, email and other services; AccessWorld reviewed it as a system for 'the liberty to use a computer'. It evolved into System Access in 2005."],["System Access","2005","Full screen reader access to Word, Excel, Outlook Express, Internet Explorer and PowerPoint text."],["System Access to Go","2007 (free from February 2008)","Launched in 2007 as a web-based screen reader that needs no install. From 2008 it was free through the AIR Foundation (Accessibility Is a Right). It ran from a website on any compatible PC: web, email, forms, PDF and operating-system tasks."],["Pneuma Solutions","2020","Mike Calvo and Matt Campbell co-founded Pneuma Solutions."]],"d":["sysaccess"],"req":["System Access to Go (2008): Windows XP or Vista, an Internet connection, a sound card and a recent Internet Explorer.","Other versions: not listed in the sources cited (System Access release notes were not found)."],"src":["https://pneumasolutions.com/about/","https://afb.org/aw/7/3/14499","https://afb.org/aw/7/3/14499","https://www.bbc.co.uk/blogs/access20/2007/06/sa_to_go_on_the_go.shtml","https://pneumasolutions.com/serotek-releases-the-worlds-first-web-based-access-technology-tool-for-the-blind/","https://blindaccessjournal.com/2008/02/why-not-enjoy-a-little-fresh-air/","https://www.vomitcomet.org/2008/02/07/system-access-to-go/"]});
Object.assign(OSL.find(x=>x.id==="siriv"),{"id":"siriv","n":"Siri voices","co":"apple","h":"Siri voice changes since 2011.","v":[["Original voices","October 14, 2011","Susan Bennett (US), Jon Briggs (UK), Karen Jacobsen (Australia)."],["Male voice option","June 2013","Changes not listed in the sources cited for this history"],["iOS 11","2017","Deep-learning voices."],["iOS 14.5","April 2021","Two new American English voices; no default voice."],["iOS 15.4 beta","February 2022","Gender-neutral voice (Quinn)."]],"d":["siri2011","siri2017","siri2021","siriquinn"],"src":["https://en.wikipedia.org/wiki/Siri","https://arstechnica.com/gadgets/2021/04/apple-releases-ios-14-5-the-biggest-update-since-ios-14-first-launched/"]});
Object.assign(OSL.find(x=>x.id==="vomacv"),{"id":"vomacv","n":"VoiceOver for macOS versions","co":"apple","h":"VoiceOver on the Mac. Apple announced a 'Spoken Interface' in 2004, and VoiceOver shipped in Mac OS X 10.4 Tiger on April 29, 2005. AppleVis calls this the first fully functional screen reader built into an operating system, with no separate installation. Before it, the Mac depended on Berkeley Systems' outSPOKEN (1989), which never came to Mac OS X. System requirements are those of each macOS release; VoiceOver has no separate requirements or price.","req":["Any Mac that runs Mac OS X 10.4 Tiger or later; included free with the OS."],"v":[["Spoken Interface preview","2004","Apple announced it was working on a Spoken Interface."],["VoiceOver 1 (Mac OS X 10.4 Tiger)","April 29, 2005","First built-in Mac screen reader. Unlike Narrator, it offered a full command set to explore the interface, not just echo keyboard focus. Mac OS X 10.2 Jaguar's Universal Access had come first."],["VoiceOver 2 (Mac OS X 10.5 Leopard)","October 2007","A major upgrade: the Alex voice, braille display support, positional audio, Keyboard and NumPad Commanders, and object navigation."],["Mac OS X 10.6 Snow Leopard","August 2009","Trackpad gestures, the rotor, quick navigation, Auto Web Spots, better web and table navigation, the ability to label items, and customization."],["Mac OS X 10.7 Lion","July 2011","23 built-in languages, downloadable higher-quality voices, and VoiceOver Activities (per-app or per-task settings)."],["macOS Catalina","2019","Voice Control (a general accessibility feature) arrived on the Mac alongside iOS 13."],["macOS Ventura","2022","More than 20 additional VoiceOver languages and locales, and Text Checker for formatting errors."],["Later versions","Date not given in the sources cited for this history","Version-by-version macOS VoiceOver changes after Ventura are not documented in the sources used."]],"d":["vomac"],"src":["https://www.applevis.com/blog/voiceover-turns-10","https://web.archive.org/web/20061116183631/http:/www.apple.com/macosx/leopard/accessibility.html","https://web.archive.org/web/20091027153017/http:/www.apple.com/macosx/accessibility/","https://maccessibility.net/2009/08/28/mac-os-x-10-6-snow-leopard-with-voiceover","https://www.macstories.net/stories/a-timeline-of-ios-accessibility-it-started-with-36-seconds/","https://www.apple.com/newsroom/2022/05/apple-previews-innovative-accessibility-features/"]});
Object.assign(OSL.find(x=>x.id==="fenrirv"),{"id":"fenrirv","n":"Fenrir versions","co":"linuxcommunity","h":"A Python 3 user-space screen reader for the Linux console (TTY), by Chrys with Storm Dragon and others. Because it runs in user space, it does not need to be compiled into the kernel like Speakup. The GitHub repository was created on July 4, 2016. Development later moved to the Stormux git server.","req":["Linux (vcsa, evdev and pty drivers); macOS, BSD and Windows through the pty driver. Python 3.3 or later, python-evdev, pyudev, the uinput kernel module, access to /dev/vcsa and /dev/input, and eSpeak or Speech Dispatcher; sox for sound icons."],"v":[["0.1a0","October 5, 2016","Early alpha uploaded with its history. It needed python-espeak, python-evdev and uinput; braille was not implemented yet."],["1.0","February 7, 2017","First stable release, announced by Storm Dragon."],["1.9","Date not given in the sources cited for this history","Recommended for production. Speech and sound icons, clipboard history (10 entries), desktop, laptop and PTY layouts, learn mode, spell check and definable windows."],["1.9.2","July 16 (year not given in the release notes)","Import from the X clipboard, barrier mode for dialog-style windows, better highlight tracking and attribute sound icons."],["1.9.6","February 15 (year not given in the release notes)","Menu-style macros and a settings menu; reworked Speech Dispatcher driver (voice and language swapped)."],["1.9.7","May 17 (year not given in the release notes)","Device-detection fix, gstreamer driver no longer experimental, Russian translation, real Unicode in VCSA and faster pty backends."]],"d":["fenrir"],"src":["https://git.stormux.org/storm/fenrir/commit/ee7eb3a9c6688081e55b20b42fa087b2cab8ac38","https://lists.gnome.org/archives/orca-list/2017-February/msg00079.html","https://github.com/chrys87/fenrir","https://github.com/chrys87/fenrir/releases"]});
Object.assign(OSL.find(x=>x.id==="samsungvav"),{"id":"samsungvav","n":"Samsung Voice Assistant versions","co":"samsung","h":"Samsung's own Android screen reader for Galaxy phones. Reports say it was first called Galaxy TalkBack (Samsung's build of Google's reader) before being renamed Voice Assistant; the exact rename date was not found in the sources checked. Samsung co-developed the 'all-new TalkBack' with Google, and from One UI 3 (Android 11) TalkBack replaced Voice Assistant as the default on all Galaxy devices, keeping its multi-finger gestures and menu ideas.","req":["Samsung Galaxy phones and tablets running TouchWiz or One UI up to One UI 2.x (Android 10)."],"v":[["Galaxy TalkBack / Voice Assistant","About 2015 (Galaxy S6 era, per device entry)","Samsung-specific screen reader with multi-finger gestures and a quick menu."],["One UI 3.0 (Android 11)","Late 2020","Voice Assistant removed and replaced by Google TalkBack."],["TalkBack 9.1 (co-developed)","February 23, 2021","Google and Samsung released the all-new TalkBack: a dozen multi-finger gestures, reading controls, more than 25 voice commands, a customizable menu, and Arabic and Spanish braille keyboards."]],"d":["samsungva","talkback"],"src":["https://blog.google/products-and-platforms/platforms/android/all-new-talkback/","https://www.androidpolice.com/2020/09/14/heres-the-changelog-for-samsungs-first-one-ui-3-0-beta-based-on-android-11/","https://www.samsung.com/us/sustainability/accessibility/mobile/voice-assistant/"]});
