[["dt_paul","Paul","p","default male voice","Pablo","Paul","Oliver",122,100,0,100],
 ["dt_harry","Harry","h","full male voice","Humberto","Hans","Michel",89,115,0,80],
 ["dt_frank","Frank","f","aged male voice","Francisco","Frank","François",155,90,50,90],
 ["dt_dennis","Dennis","d","male voice","Domingo","Dieter","Joël",110,105,38,135],
 ["dt_betty","Betty","b","full female voice","Berta","Beate","Marjolaine",208,100,0,240],
 ["dt_ursula","Ursula","u","aged female voice","Úrsula","Ursula","Angèle",240,95,0,135],
 ["dt_wendy","Wendy","w","whispering female voice","Wendy","Wendy","Nadia",200,100,55,175],
 ["dt_rita","Rita","r","female voice","Rita","Rita","Jacqueline",106,95,46,80],
 ["dt_kit","Kit","k","child's voice","Juanito","Karsten","Sébastien",306,80,47,210]].forEach(([id,nm,l,d,es,de,fr,ap,hs,br,pr])=>{
 if(!DEV.find(x=>x.id===id))return;
 U(DEV,id,{src:[DTN,DTD,DTV],ha:`In the DECtalk Software reference (2001, Force Computers), ${nm} is described as the '${d}' and is chosen with the in-line command [:name ${nm.toUpperCase()}] or [:n${l}]. The Speak applet gives it local names: ${es} in Spanish, ${de} in German and ${fr} in French. Its stock settings include an average pitch of ${ap} Hz, a head size of ${hs}%, breathiness of ${br} dB and a pitch range of ${pr}%. Any voice can be reshaped with the Design Voice [:dv] command, and changes can be saved as a tenth voice, Val.`});
});
// Batch 29: Eloquence and Apple voice histories (verified Oct 31, 2026)
const AVUS="https://www.applevis.com/podcasts/sneak-peek-additional-us-voices-coming-voiceover-ios-16",AVUK="https://www.applevis.com/podcasts/sneak-peek-additional-non-us-english-voices-coming-voiceover-ios-16",AV16="https://www.applevis.com/blog/whats-new-ios-16-accessibility-blind-deafblind-users",AV17="https://www.applevis.com/blog/whats-new-ios-17-accessibility-blind-deaf-blind-users",PT="https://en.wikipedia.org/wiki/PlainTalk";
for(const v of["reed","shelley","sandy","rocko","grandma","grandpa"])if(DEV.find(d=>d.id==="el_"+v))U(DEV,"el_"+v,{src:[AVUS,AVUK,AV16,AV17],ha:"Eloquence, the default speech in JAWS, came to Apple devices with iOS 16 (public release September 12, 2022), in both U.S. and U.K. English, as one of eight voices: Eddy, Flo, Grandma, Grandpa, Reed, Rocko, Sandy and Shelley. AppleVis noted that many users like Eloquence for its fast response and predictable, comparatively robotic sound, which can be easier to follow at high rates. iOS 17 added per-voice settings for Eloquence: rate multiplier, head size, pitch, pitch range, breathiness and roughness, plus a higher sampling rate, phrase prediction, an abbreviation dictionary and a community pronunciation dictionary."});
if(DEV.find(d=>d.id==="el_bobby"))U(DEV,"el_bobby",{src:[AVUS],ha:"Bobby was not among the eight Eloquence voices Apple added in iOS 16 (Eddy, Flo, Grandma, Grandpa, Reed, Rocko, Sandy and Shelley)."});
if(DEV.find(d=>d.id==="el_glen"))U(DEV,"el_glen",{src:[AVUS],ha:"Glen was not among the eight Eloquence voices Apple added in iOS 16 (Eddy, Flo, Grandma, Grandpa, Reed, Rocko, Sandy and Shelley). AppleVis listeners hoped it would come later."});
const MT3="MacinTalk 3 (with MacinTalk Pro, which needed a 68040 and at least 1 MB of RAM; MacinTalk 3 needed a 33 MHz 68030) brought a large set of voices: the adults Ralph, Fred and Kathy, the children Princess and Junior, and novelty voices such as Whisper, Zarvox, Trinoids, the singing Cellos (to Grieg's 'In the Hall of the Mountain King'), Good News, Bad News, Pipe Organ, the hoarse Albert, Bells, Boing and Bubbles. Each voice spoke its own test phrase in the Speech control panel. The voices remain in macOS. macOS Ventura renamed some of them, Princess becoming Superstar. macOS Sonoma changed every test phrase to 'Hello, my name is…', and macOS Tahoe brought back the original phrases.";
const IOSN=" iOS 16 (2022) brought the novelty voices to iPhone and iPad: Albert, Bad News, Bahh, Bells, Boing, Bubbles, Cellos, Good News, Jester, Organ, Superstar, Trinoids, Whisper, Wobble and Zarvox.";
const IOSU=" iOS 16 (2022) also added Junior, Kathy and Ralph to VoiceOver in U.S. English, alongside Agnes, Bruce and Vicki.";
const nov=["zarvox","whisper","bells","boing","bubbles","cellos","albert","badnews","goodnews","trinoids","pipeorgan","bahh","princess"],std=["ralph","junior","kathy","fred"];
for(const v of nov)if(DEV.find(d=>d.id==="mac_"+v))U(DEV,"mac_"+v,{src:[PT,AVUK],ha:MT3+IOSN});
for(const v of["hysterical","deranged"])if(DEV.find(d=>d.id==="mac_"+v))U(DEV,"mac_"+v,{src:[PT,AVUK],ha:"A macOS novelty voice. It was not on AppleVis's list of novelty voices added to iOS 16, which were Albert, Bad News, Bahh, Bells, Boing, Bubbles, Cellos, Good News, Jester, Organ, Superstar, Trinoids, Whisper, Wobble and Zarvox."});
for(const v of std)if(DEV.find(d=>d.id==="mac_"+v))U(DEV,"mac_"+v,{src:[PT,AVUS],ha:MT3+(v==="fred"?"":IOSU)});
for(const v of["agnes","bruce"])if(DEV.find(d=>d.id==="mac_"+v))U(DEV,"mac_"+v,{src:[AVUS],ha:"A Mac voice that reached iPhone and iPad with iOS 16 (2022), when it was added to VoiceOver's U.S. English voices."});
U(DEV,"mac_vicki",{src:[PT,AVUS],ha:"Vicki came from Mac OS X 10.3 (Panther, 2003): Apple greatly improved the Victoria voice and shipped the result as Vicki, keeping Victoria. Its higher-quality diphone samples made it almost 20 times larger. iOS 16 (2022) added Vicki to VoiceOver in U.S. English.",yr:2003,y:"Mac OS X 10.3 Panther (2003)"});
U(DEV,"mac_alex",{src:[PT],ha:"Alex arrived with Mac OS X 10.5 Leopard (2007) as a much more natural-sounding voice than earlier Mac voices. With Mac OS X 10.7 Lion, voices became available in more English accents and 21 other languages."});
// Batch 30: Acapela, IVONA, Flite, Festival histories (verified Oct 31, 2026)
U(DEV,"acapela",{yr:2004,y:"Merger announced January 2004; name unveiled April 2004",src:["https://www.speechtechmag.com/Articles/ReadArticle.aspx?ArticleID=32697","https://www.acapela-group.com/voiceai-people-behind-technology-at-acapela-group/company-timeline/","https://connaitrelawallonie.wallonie.be/wallons-marquants/dictionnaire-des-wallons/fontaine-vincent","https://www.01net.com/actualites/les-technologies-vocales-europeennes-parlent-dune-meme-voix-230735.html"],
 ha:"Acapela's roots go back to Babel Technologies, founded in 1997 under Vincent Fontaine as the University of Mons's first spin-off. Babel took over Infovox, a subsidiary of the Swedish operator Telia, in 2001. Babel and the Toulouse text-to-speech company Elan Speech announced their merger on January 7, 2004. Their combined revenue had been €4.7 million in 2003. In April 2004 the group, with Babel Infovox, took the name Acapela Group, with offices in Mons, Toulouse and Stockholm and about 70 staff. Its own timeline lists Infovox Desktop and Virtual Speaker in 2004, Infovox iVox in 2006, an iPhone SDK for Acapela TTS and its first HMM-based TTS project in 2008, and in 2010 Infovox3, a portable talking companion for visually impaired users. Lars-Erik Larsson took over as chief executive from Fontaine in December 2007."});
U(DEV,"ivona",{src:["https://press.aboutamazon.com/2013/1/amazon-com-announces-acquisition-of-ivona-software","https://www.isca-archive.org/blizzard_2006/osowski06_blizzard.pdf","https://www.isca-archive.org/blizzard_2009/kaszczuk09_blizzard.pdf"],
 ha:"IVONA was built by IVO Software in Gdańsk, Poland. Its U.S. English entry in the 2006 Blizzard Challenge got the highest naturalness (mean opinion score) ratings from the expert listeners. It entered again in 2007 and 2009; at the time of the 2009 challenge it offered voices in U.S. English, Polish and Romanian, with two British English voices to follow. Amazon announced on January 24, 2013 that it had bought IVONA Software, whose voices then powered Text-to-Speech, Voice Guide and Explore by Touch on Kindle Fire tablets. At that point IVONA had 44 voices in 17 languages and worked with the RNIB and the DAISY Consortium."});
U(DEV,"flite",{yr:2001,y:"Version 1.0 beta, August 27, 2001",src:["http://www.cs.cmu.edu/~awb/papers/ISCA01/flite/flite.html","http://cmuflite.org/packed/flite-1.0/"],
 ha:"Flite ('festival-lite') was written at Carnegie Mellon University by Alan W. Black and Kevin A. Lenzo as a small, fast run-time engine for voices built with the Festival and FestVox tools, for embedded systems, handhelds and busy servers. They presented it at the 4th ISCA Workshop on Speech Synthesis in 2001, and version 1.0 beta was posted on August 27, 2001, including an ARM Linux binary."});
U(DEV,"festival",{src:["https://en.wikipedia.org/wiki/Festival_Speech_Synthesis_System"],
 ha:"Festival was originally developed by Alan W. Black, Paul Taylor and Richard Caley at the University of Edinburgh's Centre for Speech Technology Research, with substantial contributions from Carnegie Mellon University. It is written in C++ with a Scheme-like command interpreter and released under a free, BSD-style license. It supports British and American English, Welsh and Spanish, and voice packages exist for other languages. Version 2.5 came out in December 2017."});
{const a=CO.find(c=>c.id==="acapela");if(a){a.f="2004 (merger of Babel Technologies, Elan Speech and Babel Infovox)";a.src=[...(a.src||[]),"https://www.speechtechmag.com/Articles/ReadArticle.aspx?ArticleID=32697"];}
const i=CO.find(c=>c.id==="ivona");if(i){i.f="Gdańsk, Poland (as IVO Software); acquired by Amazon in 2013";i.src=[...(i.src||[]),"https://www.isca-archive.org/blizzard_2009/kaszczuk09_blizzard.pdf"];}}
// Batch 31: Microsoft voice histories (verified Oct 31, 2026)
const MSV="https://en.wikipedia.org/wiki/Microsoft_text-to-speech_voices";
U(DEV,"ms_anna",{src:[MSV],ha:"Anna became the default English voice in Windows Vista and Windows 7. She is a SAPI 5-only voice designed to sound more natural than Microsoft Sam, and Microsoft Streets & Trips 2006 and later installed her on Windows XP for spoken directions. No male voice shipped with Vista or 7. Windows 8 brought David, Zira and Hazel as more natural-sounding successors."});
U(DEV,"ms_david",{src:[MSV],ha:"David (U.S. male) was one of three new desktop voices in Windows 8, with Zira and Hazel, meant to sound more natural than Anna. Server versions were available through the Microsoft Speech Platform for older Windows. In Windows 11 the Windows 10 voices were reclassed as 'legacy voices', but David remained the default voice for the desktop."});
U(DEV,"ms_zira",{src:[MSV],ha:"Zira (U.S. female) arrived with David and Hazel in Windows 8. In Windows 10, Microsoft's mobile voices Mark and Zira, the same as on Windows Phone 8, 8.1 and Windows 10 Mobile, became available on the desktop. Windows 11 reclassed the Windows 10 voices as 'legacy voices' and added Azure 'natural voices' (Aria, Jenny and Guy) for Narrator starting with version 22H2."});
U(DEV,"ms_hazel",{src:[MSV],ha:"Hazel (U.K. female) came with David and Zira in Windows 8 as a more natural-sounding voice than Anna. In Windows 10 she was removed from the U.S. English language pack."});
// Batch 32: Index Braille histories (verified Oct 31, 2026)
const IXB="https://www.braillecast.com/podcast/e020/",IXA="https://indexbraille.com/about-us/",IXS="https://sastltd.zohodesk.eu/portal/en/kb/articles/index-embosser-version-identification",IXM="https://www.medicalexpo.com/prod/index-braille/product-108385-1043623.html",IXP="http://www.itacconsulting.com/img/products/braille%20embrossers/pdfs/Index%20BrailleBox-presentation.pdf";
U(DEV,"idx37",{src:[IXA],ha:"Index began in 1979 as a university project to build a braille typewriter with a copy function. Björn Löfstedt was inspired by his mother, who went blind at 32. With support from a Swedish disability organization, he and Torvald Lundqvist founded Polar Print Production (later Index Braille AB) in 1982. A small batch of Index Computer Braille Printers was built in Löfstedt's garage in 1984; they became known as the 'Index 3.7' after the firmware version. Index moved into its current premises in 1985, paid for by distributing assistive technology around Sweden."});
U(DEV,"idxbluebar",{yr:1988,y:"1988",src:[IXM,IXS],ha:"Index's history of the Basic-D says the Basic Blue Bar was developed in 1988 as part of its first generation of modern braille embossers. It took tractor-fed paper. A UK service note describes the V1 Basic by the blue or red bar on its steel case; V1 production ran until 1995, and no spare parts remain."});
U(DEV,"everestd",{src:[IXA,IXS],ha:"Released in 1992, the Everest-D V1 took cut-sheet paper and, Index says, was the first small double-sided braille printer. V1 machines are end-of-life with no parts available."});
U(DEV,"idxv2",{y:"February 1995 to 2002",src:[IXS,IXM],ha:"A UK service note dates V2 production from February 1995 to 2002. The Basic had a red lid on a black case, and the only interface was parallel; the serial port was for service only. Index says the Basic V2 already looked much like today's Basic. Support for V2 ended on January 1, 2011."});
U(DEV,"idxv3",{y:"2002 to 2011",src:[IXS,IXM],ha:"Basic-D V3 came out in 2002. A UK service note describes V3 machines as having a black case, red lid and yellow buttons, with USB, Ethernet and parallel ports (the serial port is for service only), and serial numbers from 30000 to 49999. Production ran until 2011. V3 is now end-of-life with no parts available."});
U(DEV,"idxv4",{src:[IXS,IXM,IXP],ha:"Basic-D V4 (2011) was Index's first black-and-white Basic: a white case with a black lid. The control panel changed to a Menu button with up and down arrows. Production ran from 2011 to 2016. The BrailleBox, a sheet-fed production embosser with three embossing heads and a 300-page sheet feeder, came out in 2011 as part of V4. Index calls it the most advanced development work it had ever done."});
U(DEV,"idxv5",{src:[IXS,IXM,IXP],ha:"Index released the V5 line in 2016. The Basic-D V5 has a white case and black lid, embosses 140 characters per second double-sided with a dot height of 0.58 mm, and has a control panel labeled in braille and print. V5 added Index-direct-Braille (printing doc, docx, PDF and EPUB 3 files without a braille editor), printing from phones and tablets, Wi-Fi, wired network or USB connections, printing from a USB stick with speech guidance, and the BrailleApp web interface. The BrailleBox V5 cut the number of circuit boards from 4 to 2, replaced the mechanical door with a DOOR key and moved all controls to its panel. The BrailleBox has won design awards including Red Dot, Good Design and the German Design Award."});
U(DEV,"idx4x4",{src:[IXB],ha:"Introduced in 1998, the 4X4 Pro was Index's booklet-printing embosser. It came between the V2 platform (1995) and the V3 platform (2002 to 2004)."});
U(DEV,"idx4waves",{src:[IXB],ha:"Introduced in 2005, the 4Waves Pro was Index's high-speed production embosser. It came between the V3 platform (2002 to 2004) and the V4 platform (2011)."});
// Batch 33: OrCam descriptions (verified Oct 31, 2026)
const OC1="https://afb.org/aw/18/2/15244",OC2="https://afb.org/aw/19/8/15066",OCG="https://device.report/m/b0a794314e8928ae68d7e03019e300fdd0654aaf7f7bf054c6a0d2fe3a840004.pdf";
U(DEV,"orcam1",{src:[OC1],s:{disp:"8 MP camera"},desc:[
"The first OrCam has two parts joined by a cable: a small camera and speaker that clips onto your glasses, and a processor unit you carry in a pocket or on a belt. When something is in front of the camera, it reads the text aloud or names the item.",
"The head unit snaps onto the right arm of nearly any standard-size pair of glasses or sunglasses; wire frames would not work. Once attached, the 8-megapixel camera sits at the very front of the frame and the speaker toward the back, aimed at your right ear. It weighs just over an ounce.",
"Some prerelease units used bone-conduction earphones, but the released version has a single speaker. Users with hearing loss in the right ear can plug headphones, an external speaker or a hearing aid into the processor unit instead.",
"The processor unit has an audio jack and a charging port. On one edge are the Power button and a Volume Up/Down rocker; on the opposite edge is the Trigger button.",
"Press the Trigger to scan, or hold it for two seconds with either Volume button to open Settings. Most essential features can be used without pressing the Trigger at all."]});
U(DEV,"orcam2",{src:[OC2,OCG],desc:[
"The OrCam MyEye 2 is a single small bar, about 3 inches long, 0.83 inch high and 0.59 inch thick, that clips magnetically to the arm of a pair of glasses. There's no cable and no separate box: the camera, speaker, battery and controls are all in the bar.",
"The camera is at the front end, facing forward, with small lights beside it for dim places. The back end, near your ear, has the speaker, the charging port and a small loop for the lanyard. Wear the lanyard: the unit can be knocked off the glasses.",
"The outer side, facing away from your head, is rounded and has a raised touch bar running along it that clicks when pressed, plus an indicator light. Tap it to read or recognize what's in front of you; swipe forward or back to change the volume or skip through text; double-tap to pause or resume.",
"The inner side, against the glasses, is flat. It has the magnets that hold it to the mount, the power button near the speaker end, and a second indicator light. A short press of power suspends it; a second press before it suspends turns it off.",
"The box includes glasses with a mount already fitted, a mount kit with small scissors to fit other frames (on either arm), a charger, a leather case and the lanyard. AccessWorld noted that the small size and touch bar may be hard for anyone with limited dexterity."]});
// Batch 34: RUBY description (verified Oct 31, 2026)
const RBG="https://support.freedomscientific.com/content/Documents/Manuals/RUBY/RUBY-Users-Guide.pdf",RBA="https://www.avh.asso.fr/implantations/certam/evaluations-de-produits/ruby-une-loupe-electronique-portable-de-freedom",RBF="https://www.freedomscientific.com/products/lowvision/ruby/";
U(DEV,"ruby",{src:[RBG,RBA,RBF],s:{bat:"AAA batteries, rechargeable or disposable; about 2 hours",mag:"5x to 10x flat; 2x to 14x with handle extended"},desc:[
"RUBY is a pocket video magnifier from Freedom Scientific: a compact, brightly colored plastic case weighing 7.7 ounces, with a 4.3-inch widescreen color display on the front and a camera on the back. Freedom Scientific sells it in red with colored buttons, and a RUBY+ version in gray with high-contrast black and white buttons.",
"Four large buttons sit beside the screen, two on each side, each a different color with a raised dot on the spot you press. On the left are Power (green and yellow) and Color Select (blue), which cycles through full color, black on white, white on black, yellow on blue and yellow on black. On the right are Magnification (yellow), which steps through three levels, and Freeze Frame (red).",
"On the back is a fold-out handle with an opening in the middle so the camera can see through it when the handle is folded. The camera window is in the center, with an LED light at each end of the case. Unfold the handle to hold RUBY like a magnifying glass; fold it under to rest RUBY flat on a page.",
"The handle locks when open and doubles as the battery compartment. Unfolded flat, it is about 10 cm long and 4.5 cm wide, with a hatch for the AAA batteries, which can be rechargeable or disposable. Near the handle's hinge, in the lower right corner, is a post for the wrist strap.",
"On the top edge, toward the left, is the socket for the charger, with a small light beside it that shows charging or a low battery. Lying flat on a page, RUBY magnifies 5x and goes to 7.5x and 10x with the yellow button. With the handle out, it ranges from 2x to 14x depending on distance. A set of batteries lasts about two hours."]});
// Batch 35: open-source and Windows screen reader / synth histories (verified Oct 31, 2026)
const WESP="https://en.wikipedia.org/wiki/ESpeak",WORC="https://en.wikipedia.org/wiki/Orca_(assistive_technology)",WEMS="https://en.wikipedia.org/wiki/Emacspeak",WVIN="https://en.wikipedia.org/wiki/Vinux",WWE="https://en.wikipedia.org/wiki/Window-Eyes";
U(DEV,"espeak",{src:[WESP],ha:"Jonathan Duddington released Speak for RISC OS computers in 1995, supporting British English. Speak 1.05 came out under the GPLv2 on February 17, 2006, first for Linux, with a Windows SAPI 5 version in January 2007. After version 1.14 it was renamed eSpeak, and from 1.27 it used the GPLv3. It is a compact formant synthesizer covering many languages; many of the people who improved its languages were blind users. Google Translate used it for 27 languages in 2010. The last development release was 1.48.15, on April 16, 2015."});
U(DEV,"espeakng",{src:[WESP],ha:"Reece Dunn forked eSpeak on GitHub on June 25, 2010 (from release 1.43.46), at first to make it easier to build on Linux and other POSIX systems. After Jonathan Duddington had been inactive for eight months, the espeak-ng fork was started on December 11, 2015, and its first release, 1.49.0, came out on September 10, 2016. Because it is small and covers many languages, eSpeak NG ships with the NVDA screen reader and with Android, Ubuntu and other Linux distributions."});
U(DEV,"orca",{src:[WORC],ha:"Orca began in May 2004 as a prototype by Marc Mulcahy, a blind programmer at Sun Microsystems. Sun's Accessibility Program Office carried on the work and released the first official version on September 3, 2006. From GNOME 2.16 it replaced Gnopernicus as GNOME's default screen reader, and it ships with Solaris, Fedora, openSUSE and Ubuntu. After Oracle bought Sun in 2010 and cut the full-time GNOME accessibility jobs, including maintainer Willie Walker's, volunteers led by Joanmarie Diggs kept it going. Igalia hired Diggs on September 7, 2011 to continue the work. The name continues a tradition of naming screen readers after sea creatures, like JAWS, Flipper and Dolphin."});
U(DEV,"emacspeak",{src:[WEMS],ha:"Emacspeak was developed mainly by T. V. Raman, blind since childhood, and first released in April 1995. Rather than reading the screen, it is a speech-enabled 'audio desktop' built into Emacs, written largely in Emacs Lisp, with some Tcl. It speaks content directly and uses short sounds for actions such as opening a menu or closing a file. As of 2002 its default synthesizer was IBM ViaVoice TTS, which can be swapped for other software synthesizers. In 2014 Raman wrote about how its design had changed over 20 years."});
U(DEV,"vinux",{src:[WVIN],ha:"Tony Sales of technical support at the Royal National College for the Blind in Hereford, UK, began Vinux in 2008. It was a remastered Ubuntu with the Orca and Speakup screen readers, Compiz magnification, global font size and color changes, and automatic support for USB braille displays in grade 1 and 2. It could run live from a CD or USB stick or be installed. DistroWatch first listed it on June 1, 2010, as Vinux 3.0."});
U(DEV,"weyes",{src:[WWE],ha:"GW Micro of Fort Wayne, Indiana released Window-Eyes in 1995. Version 7 added standard scripting, and it came in 14 languages. GW Micro merged with AI Squared in 2014, and that year a partnership with Microsoft made Window-Eyes free for users of certain versions of Microsoft Office. By July 2017 it was no longer sold in the U.S. and Canada; only support continued, and new customers were pointed to JAWS. Version 9.4 supported Windows Vista through Windows 10."});
// Batch 36: Narrator and Dolphin histories (verified Oct 31, 2026)
const WNAR="https://en.wikipedia.org/wiki/Narrator_(Windows)",DPR36="https://www.prweb.com/releases/dolphin_computer_access_celebrate_their_30th_anniversary_launching_an_accessible_ios_reading_app_for_blind_low_vision_dyslexic_readers/prweb14405612.htm",DAB="https://yourdolphin.com/About-Dolphin",DPH="https://www.freelists.org/post/access-uk/Fw-UKVISE-FW-Dolphin-News-October-2005,1",D40="https://yourdolphin.com/news?id=563";
U(DEV,"narrator",{src:[WNAR],ha:"Narrator was developed by Professor Paul Blenkhorn in 2000. It made Windows 2000 the first Microsoft operating system with some access for blind people built in, so a blind person could use any such computer right away. The Windows 2000 version used SAPI 4 and could use other SAPI 4 voices. The Windows XP version used SAPI 5 but only the default voice, Microsoft Sam. Vista and 7 moved it to SAPI 5.3 and the Anna voice. Windows 10 offered it in many languages with voices including David, Zira and Mark. Windows 11 redesigned it and added natural voices. Windows Phone had a simpler version."});
U(DEV,"haldos",{src:[DPR36,DAB,D40],ha:"Hal for DOS was one of the first products of Dolphin Computer Access, founded in 1986 in Worcester, UK and led by Noel Duffy. It was a software screen reader that spoke through a hardware synthesizer, Dolphin's Apollo. Dolphin says the pairing was sold in more than 30 languages and became an industry leader worldwide."});
U(DEV,"apollo",{src:[DPR36],ha:"Dolphin built the Apollo hardware speech synthesizer as the voice for its Hal for DOS screen reader. Dolphin says the combination was available in more than 30 languages."});
U(DEV,"supernova",{yr:1998,y:"Launched 1998",src:[DPR36,DPH,D40],ha:"Dolphin launched SuperNova in 1998 as, in its words, the first fully integrated magnifier and screen reader, developed at its Worcester headquarters. SuperNova USB followed in 2005 as the first assistive technology to run portably from a USB thumb drive. The Dolphin Pen could carry SuperNova, Hal or Lunar from PC to PC, and was nominated for a British Chamber of Commerce innovation award in 2005. SuperNova remains one of Dolphin's flagship products."});
U(DEV,"pockethal",{yr:2005,y:"Late 2005 (final beta October 2005)",src:[DPH,"https://www.freelists.org/post/access-uk/Fw-Showcasing-Pocket-Hal"],ha:"Pocket Hal was a full screen reader for Windows Mobile PDAs, based on the desktop Hal. Dolphin showed it at Sight Village in July 2005. In October 2005 it was in final beta, with release planned for the next month. It gave speech and braille access to Pocket Word, Pocket Excel, Pocket Outlook and Pocket Internet Explorer, plus MSN and phone features. Dolphin said it would be the first screen reader for off-the-shelf PDAs to support Bluetooth or plug-in braille devices and keyboards."});
// Batch 37: ADRIANE and Oralux histories (verified Oct 31, 2026)
const ADK="https://knopper.net/knoppix-adriane/index-en.html",ADW="https://winfuture.de/news,30673.html",ADR="https://ress.at/linux-fuer-blinde-aber-nicht-nur-news04062007151257.html",ORL1="https://lwn.net/Articles/45329/",ORL2="https://lwn.net/Articles/52826/";
U(DEV,"adriane",{yr:2007,y:"2007 (presented June 2007; part of KNOPPIX since 5.3)",src:[ADK,ADW,ADR],ha:"ADRIANE (Audio Desktop Reference Implementation and Networking Environment) is a talking desktop by Knoppix creator Klaus Knopper, named after his wife Adriane, who lost her sight at 15 and helped develop it. Knopper announced it at CeBIT in March 2007 for release that April, aimed at beginners as well as blind users, and it was presented at the end of Linuxwochen Vienna in June 2007. Simple menus are driven with the arrow keys and Enter, with Caps Lock used for speech functions, giving easy access to email, the web, SMS and scanning printed documents, with optional braille. It uses the SBL screen reader by Marco Skambraks and Halim Sahin with speech-dispatcher and eSpeak, and works with Orca in graphical mode. It has been part of KNOPPIX since version 5.3: the boot option 'adriane' starts it with speech."});
U(DEV,"oralux",{src:[ORL1,ORL2],ha:"Oralux was announced in mid-2003 as a Knoppix-based live CD for blind and visually impaired users, so it ran straight from CD with no installation. LWN described it in August 2003: a crowing rooster at startup let you set the volume, then you chose a language (English only in version 0.04, using Flite), a keyboard and, optionally, DECtalk. Version 0.05 (October 2003) moved to Knoppix 3.3 and added Emacspeak with Festival and MBROLA for English or French, optional Spanish and German DECtalk files, and a startup menu in four languages."});
// Batch 38: histories from NFB Braille Technology Timeline 2026 (verified Oct 31, 2026)
const NFT="https://nfb.org/images/nfb/publications/fr/fr45/2/fr450210.htm";
U(DEV,"bd3",{src:[NFT],ha:"The NFB's Braille Technology Timeline (2026 edition) says Triformation Systems, later Enabling Technologies, released its first embosser, the BD 3, in 1971. Triformation made the first embossers able to print eight-dot computer braille in the early 1970s, partly building on the Braille Mboss developed at MIT."});
U(DEV,"led120",{src:[NFT],ha:"The NFB's Braille Technology Timeline (2026) calls the LED 120 Triformation's popular embosser of the late 1970s, which differs from this entry's earlier 1974 date. It followed the BD 3 (1971), and Triformation later became Enabling Technologies."});
U(DEV,"navigator",{src:[NFT],ha:"The NFB timeline dates the Navigator to 1989 as TSI's first dedicated refreshable braille display for PC access. It came in 20-cell (six-dot desktop), 40-cell (eight-dot) and 80-cell versions, sat below the PC keyboard and had cursor routing keys. The PowerBraille line replaced it in the mid-1990s."});
U(DEV,"elba",{src:[NFT],ha:"The NFB timeline records Papenmeier's Elba (2001) as the first Linux-based notetaker, with both braille and QWERTY keyboards and a refreshable braille display."});
U(DEV,"pronto",{src:[NFT],ha:"At the 2004 NFB convention HumanWare released the BrailleNote PK, then the smallest notetaker sold in the U.S., with an 18-cell display and speech. According to the NFB timeline its hardware was BAUM's Pronto."});
U(DEV,"focus44",{src:[NFT],ha:"Freedom Scientific's first Focus line came out in 2004 in 44-, 70- and 84-cell sizes. A second generation offered 40 and 80 cells, and Focus Blue added Bluetooth. The NFB timeline calls Focus one of the most widely used displays among JAWS users."});
U(DEV,"tigeradv",{src:[NFT],ha:"The NFB timeline dates ViewPlus's announcement of the Tiger Advantage, its first braille-capable tactile graphics printer, to 2001."});
U(DEV,"braillex",{src:[NFT],ha:"Papenmeier Reha worked with Dr. Werner Boldt of Dortmund University and in 1975 produced the BRAILLEX, an electronic device with a refreshable braille display. The same year Klaus Peter Schönherr of Horb-Nordstetten invented the first piezoelectric braille module, the basis of refreshable braille cells for the next forty years."});
U(DEV,"nlsereader",{src:[NFT],ha:"The National Library Service began piloting free 20-cell braille displays for patrons in 2020, funded by a five-million-dollar Congressional appropriation. Two models were chosen: one by HumanWare, based on the Brailliant BI 20X, and one by Zoomax."});
// Batch 39: Blindows and COBRA histories (verified Oct 31, 2026)
const WCOB="https://de.wikipedia.org/wiki/Cobra_(Screenreader)",WBLW="https://www.welt.de/print-welt/article566363/Mit-Blindows-durch-das-Internet.html";
U(DEV,"blindows",{y:"In use by February 1999; development ended 2006",src:[WCOB,WBLW],ha:"Blindows was the Windows screen reader of the German company Frank Audiodata, later Audiodata GmbH. Die Welt covered it in February 1999 as a way for blind users to browse the web. After BAUM bought Frank Audiodata in 2004, BAUM had two quite different screen readers, Blindows and its own VIRGO, and the two teams began a joint successor. Development of both ended in 2006, and COBRA replaced them."});
U(DEV,"cobra",{yr:2008,y:"November 2008 (COBRA 8) onward",src:[WCOB],ha:"COBRA, made by BAUM Retec AG of Wiesenbach, Germany, is the joint successor to Blindows and BAUM's VIRGO. COBRA 8 came out in November 2008 and 8.1 in April 2009, with braille and speech only, still using BAUM's WebFormator add-on for Internet Explorer to read web pages. COBRA 9 (January 2010) added magnification and replaced WebFormator with a built-in COBRA Explorer. Version 9.1 came in December 2010, 10 in November 2012 (Windows XP to 7) and 11 in May 2016 (Windows 8 and 10). Features include OCR of images, text snippets, splitting braille displays and running more than one at once, and VBScript scripting. A 2011 Aktion Mensch article named it as JAWS's runner-up in Germany. After BAUM went insolvent, VisioBraille took over its assets and still offers COBRA downloads and license activation."});
// Batch 40: Gnopernicus, Siri voices, Cepstral, IBM Screen Reader, ChromeVox, BRLTTY (verified Oct 31, 2026)
const WGNO="https://en.wikipedia.org/wiki/Gnopernicus",WSIRI="https://en.wikipedia.org/wiki/Siri",WCEP="https://en.wikipedia.org/wiki/Cepstral_(company)",AFBIBM="https://afb.org/aw/5/2/14760",SR2="https://doi.org/10.1007/3-540-58476-5_108",CVBLOG="https://developers.googleblog.com/en/chromevox-built-in-spoken-feedback-for-chrome-os/",CVNEXT="https://www.youtube.com/watch?v=NyuuK7tB9fM",CVDOC="https://chromium.googlesource.com/chromium/src/+/refs/heads/main/docs/accessibility/os/chromevox.md";
U(DEV,"gnopernicus",{yr:2001,y:"December 7, 2001 (first release) to 2006 (1.1.2, August 21, 2006)",src:[WGNO],ha:"Development began in 2001, and the first release is dated December 7, 2001. Gnopernicus was a free, LGPL-licensed, one-size-fits-all program written in C that gave speech, braille and magnification through GNOME's AT-SPI accessibility layer. Users could customize voices, keyboard commands, braille display keys and magnification, and even edit the XML files that defined speech and braille output. It became the default screen reader in GNOME 2.4 on September 10, 2003. The last release, 1.1.2, came on August 21, 2006, and Orca then replaced it in GNOME."});
U(DEV,"siri2011",{src:[WSIRI],ha:"Siri itself began as a spin-out of SRI International's Artificial Intelligence Center and the DARPA-funded CALO project, co-founded by Dag Kittlaus, Tom Gruber and Adam Cheyer. Nuance supplied its speech recognition. The voice actors recorded around 2005 without knowing how the recordings would be used; Briggs told The Guardian the original system was recorded for a US company called ScanSoft, \"who were then bought by Nuance.\" Bennett revealed her role in October 2013, and audio forensics expert Ed Primeau confirmed it. Most countries started with a female voice only (the UK, France and the Netherlands started male). In June 2013 Apple announced a gender option adding a counterpart voice, and with iOS 11 (2017) it replaced the voices with new deep-learning ones built from hours of recordings of newly auditioned talent."});
U(DEV,"siri2021",{src:[WSIRI],ha:"Apple announced the change on March 31, 2021, saying Siri would no longer default to a female or male voice. Wikipedia notes earlier criticism of the default, such as The Conversation's argument that a soft female default voice reinforced women's roles as secondary. In February 2022 Apple added a fifth US option, Quinn, its first gender-neutral voice."});
U(DEV,"cepstral_voices",{src:[WCEP],ha:"Cepstral LLC was founded in June 2000 by Carnegie Mellon University scientists, including Kevin Lenzo and Alan W. Black, and is based in Pittsburgh, Pennsylvania. The company makes synthetic voices for telephony systems, mobile apps and desktop programs, and voices that work with the open-source Festival system. David and Diane are among its US English voices sold to individual users."});
U(DEV,"ibmsr",{src:[AFBIBM,SR2,"https://knowbility.org/blog/2021/a-brief-history-of-screen-readers"],ha:"Jim Thatcher, an IBM mathematician and one of the first computer science PhDs (1963), built it with his former thesis adviser Jesse Wright, who was blind. They began work on audio access for the IBM PC in 1984, developing an IBM Raleigh prototype talking terminal called SAID (Synthetic Audio Interface Driver), and the research project was called PC SAID. IBM announced Screen Reader in 1986, and Thatcher's 1994 paper says the DOS product was released in January 1988 and upgraded twice. It was at first mainly for IBM's own blind staff, dozens of whom beta tested it. Its distinguishing features were a separate 18-key keypad and full programmability. Screen Reader/2 for OS/2, a complete redesign that Thatcher led, was the first screen reader for a PC graphical interface; it was programmed in the Profile Access Language (PAL) and also gave access to Windows and DOS programs running under OS/2."});
U(DEV,"chromevox",{src:[CVBLOG,CVNEXT,CVDOC],ha:"T.V. Raman announced the developer beta, which used Chrome's experimental tts and accessibility extension APIs and offered web developers a simple screen reader API. Over time it moved from a separate extension into the operating system, and its code now lives in the Chromium tree. Google rebuilt it from the ground up as ChromeVox Next, which became the default on all Chromebooks with Chrome 56 at the end of January 2017. Next changed the modifier from Shift+Search to Search alone and added a ChromeVox panel with menus, braille captions and navigation from USB braille display keyboards."});
U(DEV,"brltty",{src:["https://brltty.app/"],ha:"BRLTTY runs as a background daemon that drives a refreshable braille display for the Linux and Unix text console. It can start at boot, so it reads login prompts and console messages, and it is suitable for system administration. Features include full screen review, cursor routing, cut and paste between virtual terminals, table-driven contracted braille (English, French and German provided), several braille codes, screen freezing, a preferences menu, basic speech and an API for other programs."});
// Batch 41: outSPOKEN, Mobile Speak, TALKS (verified Oct 31, 2026)
const WOUT="https://en.wikipedia.org/wiki/OutSPOKEN",ALVA03="https://www.macworld.com/article/166605/alva.html",CFHIST="https://codefactoryglobal.com/company/",AFBMS="https://afb.org/aw/5/6/14676",IRMS="https://www.innovations-report.de/wissenschaft-technik/innovative-produkte/bericht-28529/";
U(DEV,"outmac",{src:[WOUT,ALVA03,"https://lists.w3.org/Archives/Public/w3c-wai-ig/2003AprJun/0718.html"],ha:"It was the only Mac screen reader before VoiceOver. Berkeley Systems sold outSPOKEN and all its other accessibility assets to ALVA Access Group of the Netherlands in 1996. On June 10, 2003, ALVA announced it would stop developing outSPOKEN and the inLARGE magnifier for the Mac, to focus on stand-alone products such as the ALVA MPO. outSPOKEN 9.2 stayed on sale for the rest of 2003, with warranties and service agreements honored. Optelec acquired ALVA's assets in September 2005."});
U(DEV,"outwin",{src:[WOUT],ha:"It ran on Windows 3.1, and the interface was designed by Marc Sutton and Joshua Miele. Like the Mac version, it used an off-screen model and could use the mouse pointer as a review cursor. Berkeley Systems sold it with its other accessibility products to ALVA Access Group in 1996, and Optelec acquired ALVA's assets in September 2005."});
U(DEV,"mobilespeak",{src:[CFHIST,AFBMS,IRMS],ha:"Code Factory, founded in 1998 near Barcelona, Spain, by Eduard Sánchez, first made games for the blind and in 2003 released Mobile Accessibility, a simpler talking phone interface. Mobile Speak was announced in April 2004 with Acapela's PocketBabil synthesizer for Nokia Series 60 phones and the Siemens SX1. AccessWorld's 2004 review of version 1.0 found it used Eloquence and cost $295 in the US through Optelec. Code Factory says it launched in 20 countries. Pocket PC support came in 2005 and Windows Mobile Smartphone support in 2006, when Vodafone began offering it. Nokia partnered with Code Factory in 2007, it won an AFB Access Award in 2008, and in 2011 Code Factory supplied Nokia with a branded version called Nokia Screen Reader, while moving to Android with Mobile Accessibility."});
U(DEV,"talks",{src:[AFBMS],ha:"AccessWorld's 2004 review lists TALKS as produced by Brand & Gröber Communications and tested version 1.30.6 for Series 60 on a Nokia 6620 against Code Factory's Mobile Speak 1.0. Both used Eloquence. TALKS ran on the Nokia 3600, 3620, 3650, 3660, 6600, 6620, 7650, N-Gage and the Siemens SX1."});
U(DEV,"ztdos",{src:["https://en.wikipedia.org/wiki/ZoomText","https://afb.org/aw/2/6/15003","https://afb.org/aw/1/1/16188","https://web.archive.org/web/20100407084612/http:/www.aisquared.com/about_us"],ha:"Ai Squared, of Manchester Center, Vermont, began making screen and text access products in 1987 and grew from a one-man operation. AccessWorld called ZoomText the first screen magnification program on the market, in 1988. The first Windows version followed in 1991. DOS support lived on as a bundle: in AccessWorld's reviews of around 2000 and 2001 the 'Plus' levels of ZoomText Xtra included ZoomText for DOS, at $595 (magnifier) or $795 (with speech), $200 more than the Windows-only levels. Ai Squared later merged with GW Micro, and Freedom Scientific acquired it in 2016."});
U(DEV,"talkingarch",{yr:0,y:"Last release October 3, 2017",src:["https://archiveos.org/talkingarch/"],ha:"TalkingArch began as Chris Brannon's personal project to make installing Arch Linux with speech easier. With community help and the Archiso tooling, it grew into an unofficial modified Arch install and live image with speech and braille support, also used for rescue and recovery. It aimed to stay as consistent as possible with the official Arch image. ArchiveOS lists New Zealand as its origin, a text-only (CLI) environment, x86_64, and a last release dated October 3, 2017."});
U(DEV,"sonar",{yr:2013,y:"April 2013 (Sonar 13.04) to 2017",src:["https://www.pcworld.com/article/456724/new-linux-distro-will-target-disabled-users.html","https://lists.gnome.org/archives/orca-list/2013-April/msg00214.html","https://mail.gnome.org/archives/orca-list/2014-July/msg00182.html","https://lists.ubuntu.com/archives/ubuntu-accessibility/2017-March/007282.html"],ha:"Developer Jonathan Nadeau, blind since a 1992 car accident, launched the Sonar Project on Indiegogo in early 2013, seeking $20,000 to build a free, Ubuntu-based Linux distribution for blind, low-vision, dyslexic and motor-impaired users. PCWorld noted on February 4, 2013 that it had raised $2,385. Sonar 13.04 was announced on the Orca list in April 2013, and Sonar 2014 in July 2014. In March 2017 Sonar GNU/Linux merged with Vinux."});
U(DEV,"coconut",{yr:2014,src:["https://zendalona.com/about-us/"],ha:"Accessible-Coconut comes from the Zendalona community in Kerala, India. Its roots go back to K. Sathyaseelan, who lost his sight at age 10 in 1970 and moved to Ubuntu and the Orca screen reader in 2007. Nalin Sathyan, Zendalona's founder and a three-time Google Summer of Code winner, built tools such as Easy-OCR (2009), Lios OCR (2011), Sharada Braille Writer (2012) and IBus-Braille (accepted into Debian in 2015). The first Accessible-Coconut release came in 2014. The group took the name Zendalona in 2020, registered as a non-profit in 2022, and became a Google Summer of Code mentoring organization in 2024."});
// Batch 42: Type 'N Talk, NeoSpeech, Orpheus (verified Oct 31, 2026)
const ANTIC12="https://www.atarimagazines.com/v1n2/taritalkers.php",WNEO="https://en.wikipedia.org/wiki/NeoSpeech",VPREV="https://www.webbie.org.uk/Veli-Pekka/reviews_of_speech_synths.html";
U(DEV,"votraxtnt",{src:[ANTIC12],ha:"Antic magazine's review (volume 1, number 2) tested it on the Atari 400 and 800, which needed the Atari 850 interface and a cable (about $30 from the maker). It listed for $375 plus a speaker, since the unit needed an external 8-ohm speaker, from Votrax at 500 Stephenson Highway, Troy, Michigan. It spoke an unlimited vocabulary from plain English text at 300 baud and could output the phoneme codes it generated, so users could hand-tune pronunciation. The reviewer had used it for six months, but at a science fair most first-time listeners found Street Electronics' ECHO-GP ($369.95) clearly easier to understand. He also complained that the on/off switch was on the back and there was no power light."});
U(DEV,"neo_voices",{yr:2001,y:"September 2001 (Kate, as Voiceware VoiceText)",src:[WNEO,VPREV],ha:"Kate was released in September 2001 as the first American English voice in VoiceText, from the Korean company Voiceware (founded 2000). In February 2002 Voiceware set up its US subsidiary NeoSpeech, founded by speech engineers Lin Chase and Yoon Kim, later based in Santa Clara, California. VoiceText uses unit selection synthesis, built from large databases of recorded speech. Stephen Hawking briefly used NeoSpeech in 2004 before returning to his DECtalk voice, and Adobe chose it for Captivate. ZoomText 9 offered NeoSpeech voices (Paul and one female US voice) as natural-sounding alternatives to its ViaVoice speech; reviewer Veli-Pekka Tätilä praised Paul's intonation but noted a lag before speech. Pentax bought Voiceware in January 2006, HOYA bought Pentax in 2007 to 2008, and after HOYA bought ReadSpeaker in 2017 it put NeoSpeech, Voiceware and VoiceText under the ReadSpeaker brand."});
U(DEV,"orpheus",{src:[VPREV],o:"Dolphin's software speech synthesizer, bundled for years with its SuperNova, HAL and Lunar Plus programs.",ha:"Orpheus 1 was a fully synthetic, formant-style engine with robotic-sounding but very clear speech and strong pronunciation; the default voice was Dave. Outside Dolphin's own products it worked only with programs supporting Dolphin's SAM interface. Orpheus 2 added SAPI 4 and 5 support, many more languages including Chinese, an exception dictionary, a Windows CE port, and recorded (sampled) voices alongside the synthetic ones, with one male and one female sampled voice per language plus synthetic Dave and Andy. Reviewer Veli-Pekka Tätilä found the synthetic voices understandable even near the top rate of 700. Orpheus development later passed to Meridian, which hosted its home page."});
// Batch 43: OrCam MyEye 3 Pro and Ray-Ban Meta (Gen 1) descriptions (verified Oct 31, 2026)
const OC3G="https://img1.wsimg.com/blobby/go/b705e79c-b611-4aa3-af3a-dddf36dee121/downloads/590732a7-209c-4f42-82d3-7483b0858719/MyEye%203%20Instruction%20Brochure.pdf?ver=1762352115649",OC3VA="https://www.visionaid.co.uk/orcam-myeye-3-pro",RBFAQ="https://www.ray-ban.com/usa/c/frequently-asked-questions-ray-ban-meta-smart-glasses",RBSPEC="https://www.specifications.global/us/glasses-xr/Meta-RayBan-Wayfarer-Gen1-Standard-Large-RW4006-RW4008/";
U(DEV,"orcam3",{src:[OC3G,OC3VA],ph:"76 x 21 x 14.9 mm (3 x 0.8 x 0.6 in); 22.5 g (0.79 oz); 13 MP camera; 320 mAh battery.",desc:[
"The OrCam MyEye 3 Pro is a single slim bar about the size of a finger: 3 inches long, about 0.8 inch high and 0.6 inch thick, weighing 22.5 grams (under an ounce). It clips magnetically to the side of a pair of glasses, with no cable or separate box. The camera, speaker, battery and controls are all inside the bar.",
"The 13-megapixel camera is at the front end, facing forward, with built-in lights to illuminate text. A small built-in speaker reads aloud near your ear; OrCam Bluetooth earphones are an option for privacy.",
"The outer long side carries a raised touch bar. Tap it to start or stop reading, double-tap to pause or resume (or, when idle, to open the setup menu), and swipe forward or back to change the volume or skip through text. Holding a finger on the bar while facing a person about 3 feet away teaches it a face; it can store up to 100. You can also point a finger at text, or say \"Hey OrCam\" followed by a command.",
"The inner long side, against the glasses, has two magnets you can feel with a fingertip, and the power button next to them. Hold power for 2 seconds to turn it on; press it until you hear \"Suspended, press again to shut down\" to turn it off. It charges from a standard 5-volt phone charger through USB-C.",
"In the box (from UK dealer VisionAid): the MyEye 3 Pro, a stand, a speaker, a neck lanyard, unisex glasses, three magnetic mounts, a USB power adapter and cable, and a case. Placed on the stand and connected by USB-C or Wi-Fi to a computer browser at cast.orcam.com, it works as a desktop magnifier with an AI assistant that answers questions about a scanned page."]});
U(DEV,"raybanmeta",{src:[RBFAQ,RBSPEC],desc:[
"The first-generation Ray-Ban Meta glasses look and feel like ordinary Ray-Ban frames, such as the square Wayfarer. The Wayfarer comes in Standard (48 grams, 131 mm hinge to hinge) and Large (50 grams, 137 mm) sizes. There's no screen; everything is heard through two small open-ear speakers in the arms, aimed at your ears, so you still hear the world around you. Five microphones are spread across the frame: two in each arm and one near the nose pad.",
"At the front corners of the frame are two small round openings. One is the 12-megapixel ultra-wide camera; the other (on the left, per Ray-Ban) is a capture light that glows to tell people nearby when you take a photo or video. Inside, near the right arm's hinge, is a notification light that only you see.",
"The right arm has two controls. Along its outer side is a touchpad: tap once to pause or play, double-tap to skip forward or answer a call, triple-tap to skip back, swipe forward or back for volume, and press and hold to talk to Meta AI or reject a call. On top of the frame is the capture button: press once for a photo, press and hold for video.",
"The power switch is a small slider on the inner side of the left arm, near the hinge; slide it toward the lens to turn on and back to turn off. The product name is printed inside the right arm, and the serial number inside the left arm. The glasses are IPX4 splash resistant, so light rain is fine but they shouldn't be submerged.",
"The glasses charge only in their hard case, through metal contacts at the nose bridge. The case has a USB-C port for charging, a light on the front (orange while charging, green when full) and a pairing button on the back. Glasses last up to about 4 hours of moderate use and charge fully in about 75 minutes; the case holds up to 32 hours more. The box includes the glasses, the case and a cleaning cloth."]});
// Batch 44: eSight 3 description (verified Oct 31, 2026)
const ES3G="https://esighteyewear.com/wp-content/uploads/2020/03/eSight-3-User-Guide-4000338-Rev-G-EN.pdf",ES3S="https://esighteyewear.com/wp-content/uploads/2020/03/Customer-Facing-eSight-3-Specifications-Sheet-4.pdf",ES3P="https://www.manualslib.com/manual/1643221/Esight-3.html";
U(DEV,"es3",{src:[ES3G,ES3S,ES3P],desc:[
"eSight 3 has two parts: a headset worn like glasses and a hand-sized controller. The headset weighs 104 grams. It has a lensless frame with a nosepad (prescription lenses can be fitted), a padded forehead band, and a headstrap that wraps around the back of the head and snaps on magnetically. Fitted properly, the band and strap form a snug halo and the headset doesn't move when you shake your head.",
"The front of the headset holds a 21.5-megapixel autofocus camera and a small light. Inside are two OLED screens, one for each eye. The whole display unit tilts on a hinge, from 45 degrees up to 10 degrees down: fully down for reading or TV, half up so you look under it with your own vision when moving around, or fully up out of the way for conversation. eSight warns never to walk with it fully down.",
"The controller has dials on both sides. On the right side are two dials you roll up or down and also press: the top one is contrast (press to change contrast modes) and the other is focus (press to switch between near manual, far manual and auto focus). On the left side are the zoom dial (roll for up to 24x; press and hold for a quick unmagnified view), the power button, a photo button, and a power and battery light.",
"The face of the controller has a trackpad surrounded by four buttons at the compass points: north is Home (resets to start-up settings), south is Menu Back and Control Lock, west freezes and resumes the picture, and the fourth button turns on panning mode. Pressing the trackpad opens the menu, and sliding a finger up or down moves through it. Hold the power button for on, standby or off. A door on the controller covers its USB-C charging port.",
"The headset has speakers for spoken menus, and a micro HDMI input lets you watch a computer, TV box or game console directly in the screens. In the box: the headset and controller, the frame, a USB cable and wall adapter, a belt clip, wrist and neck lanyards, a digital video cable, an SD card, a spare forehead band, a microfiber bag and a carry case. eSight says not to use it in rain or snow."]});
// Batch 45: SARA description (verified Oct 31, 2026)
const SARAG="https://support.freedomscientific.com/Content/Documents/Manuals/SARA/SARA_User_Guide.pdf",SARAAW="https://afb.org/aw/6/6/14568";
U(DEV,"sara",{src:[SARAG,SARAAW],desc:[
"SARA (Scanning and Reading Appliance) is a self-contained desktop reading machine about 20 by 12 inches and 3.5 inches high, weighing about 18 pounds. No computer is needed: it combines a flatbed scanner, text recognition, a RealSpeak speech synthesizer, and front-mounted stereo speakers in one box. It runs from a separate black power adapter, which plugs into the far right socket on the back.",
"The top holds the scanner lid and a large, colorful keypad with raised symbols. The lid's back edge lifts so it rests level on an open book. Freedom Scientific warns never to press down on the lid, because the glass can break. Put the page face down, close the lid, and press SCAN: a red oval key with a raised circle at the upper left of the keypad. SARA says \"Scanning,\" beeps while it works, and starts reading on its own.",
"The keypad also has a green READ key to start and pause reading, four blue arrow keys in the center (up and down move by line, left and right by word), a SELECT key, rewind and fast-forward keys, MENU, and a yellow HELP key. Press HELP and then any key to hear what that key does.",
"The sloping front panel holds more controls. At the far left is a small round green POWER button; press once for on, and press again for a choice between power off (POWER again) and sleep (DOWN ARROW). To its right is an orange VOLUME rocker with a raised loudspeaker shape: press the left end for softer and the right end for louder. Next come four small round function keys you can assign, then a rocker for voice speed. A headset jack sits at the lower right of the front, and there's a CD slot on the front.",
"USB ports on the back accept thumb drives and external drives. SARA reads OBX, ARK, RTF, TXT, DOC, PDF, HTML and XML files, plays DAISY and audio CDs, and can save scanned books to CD or USB. It can also connect to a computer monitor for large print, or to a braille display. In the box: the unit, a power cord and adapter, a headset, a large-print guide, an audio training recording and a test page."]});
// Batch 46: DECtalk history extension (verified Oct 31, 2026)
U(DEV,"dectalk",{src:["https://en.wikipedia.org/wiki/DECtalk"],ha:"Larger quantities shipped in March 1984. The units had two telephone jacks, one for the phone line and one for a handset, so DECtalk could answer and place calls, read email aloud, and run touch-tone alert systems. Uses ranged from public information services to giving a voice to people with speech disabilities. Later versions came on ISA cards for PCs and as software: DECtalk Software for Digital UNIX and for Windows NT, and DECtalk Access32."});
// Batch 47: Artic SynPhonix, TransPort and Aicom Accent histories (verified Oct 31, 2026)
const ARTH="https://web.archive.org/web/20060327064418/http://www.artictech.com/history.htm",ARTX="https://web.archive.org/web/20110728031437/http://www.articannex.ws/artictec.htm",ARTSC="https://speechchips.com/devices/synphonix200.html",ARTVN="http://cd.textfiles.com/nfbfiles/newsletters/VN0892.TXT",ARTAW="https://afb.org/aw/1/5/16151",ACJFW="https://www.freelists.org/post/jfw/jaws-61,13",ACRVI="https://www.freelists.org/post/raspberry-vi/Still-no-go-for-more-voices,32";
U(DEV,"synph200",{src:[ARTH,ARTX,ARTSC],ha:"Artic Technologies was founded in 1984 by Art Velthoven, Dale McDaniel, Kathy Gargagliano and Tim Gargagliano. All four came from the research and development group at Votrax, the speech synthesis subsidiary of Federal Screw Works. In Artic's own history, the SynPhonix 200 card, released in 1985, was the company's first commercial product; SpeechChips.com notes that the SynPhonix family was already being advertised for IBM and Apple computers in 1984. The card fit inside an IBM PC and spoke through the 263 phoneme chip (the SSI 263, originally Votrax's SC-02), which built words from individual speech sounds. Artic recalls building synthesizers in the founders' basements and moving offices several times in those early years. The 200 became an important partner for screen-reading software, and in 1987 it was replaced by the SynPhonix 215."});
U(DEV,"synph215",{src:[ARTH,ARTX,ARTAW,ACRVI],ha:"Artic released the SynPhonix 215 in 1987, the year it moved into its own building in Troy, Michigan. It replaced the 200, and Artic later described it as still known for its fast speech rate, accurate text-to-speech, responsiveness, and instant silencing. It was usually paired with Artic's Business Vision screen reader (1987). AccessWorld noted that SynPhonix and Artic's screen readers were significant, lower-cost competitors to DECtalk and JAWS. Related ISA cards included the 210 and 216, and there was also a laptop version, the SynPhonix 225, and a PCMCIA card, the P27. All are now out of production. Users still remembered the 215 decades later; in 2021 a former Smith-Kettlewell staff member listed it on a mailing list among the synthesizers he used there after the early Votrax."});
U(DEV,"transport",{yr:1992,y:"Fall 1992",src:[ARTVN,ARTX,ARTH],ha:"Artic announced TransPort in its Visions newsletter in fall 1992, after years of users asking for a portable, battery-powered synthesizer as responsive as its internal cards. TransPort was 0.75 inch high, 4.125 inches wide and 7.5 inches long, and weighed about 15 ounces. It had an aluminum case, used the Artic 263 speech chip, had thumbwheels for volume and tone, and could use its built-in speaker, headphones or an external speaker. It ran about 16 hours on rechargeable batteries, warned when the battery was low, and could be used while charging. The flagship model 615 included Artic's Business Vision screen reader, which could be copied from its ROM disk to any PC; the VEST speech rules; a clock with 16 alarms; battery-backed file storage; and a port for Artic's Gizmo pad or Turbo Pedals. The model 611 was the same without Business Vision. Both could emulate Artic's own PortTalk codes or the external Accent synthesizer, so other screen readers could drive them. Later came the palm-sized Mini TransPort 621 and 622; all are now out of production."});
U(DEV,"accent",{yr:1992,y:"On the market by 1992",src:[ARTVN,ACJFW,ACRVI,"https://www.cs.vassar.edu/~priestdo/emacspeak/list.archive.2005/msg00179.html"],ha:"Aicom Corporation made the Accent line: the external Accent SA, which connects over a serial port, and the full-length ISA Accent PC card. The Accent was established by fall 1992, when Artic made its new TransPort synthesizer able to emulate the external Accent so that screen readers already supporting it could use the TransPort. Users remember the Accent PC as the fastest of the ISA speech boards, though they found its speech less accurate and understandable than DoubleTalk's. In April 2005 a user on the JAWS mailing list wrote that Aicom had closed and that he had bought its last 12 Accent SAs and 30 Accent PC cards. Users at the time reported that JAWS 5 and later no longer drove the SA properly. Some blind Linux users kept the SA in service, though in 2005 an Emacspeak user found it unsupported there."});
// Batch 48: Keynote Gold, Soft Vert, System Access, Prudence, "Microsoft Screen Reader" histories (verified Oct 31, 2026)
const SVNBP="https://www.duxburysystems.org/downloads/library/history/nbp_2nd_begin.pdf",SAAW="https://afb.org/aw/7/3/14499",SABLOG="http://blog.serotek.com/2012/02/our-story-at-ten.html",SA23="http://blog.serotek.com/2007/07/changes-in-system-access-23087.html",PNEUMA="https://pneumasolutions.com/about/",KGBS="https://github.com/cullen-gallagher/BestSpeechForMac",KGQC="http://qcsalon.net/en/forum32/topic107910",KGDT="https://bluegrasspals.com/pipermail/dectalk/2022-September/005776.html",NARAB="https://abilitynet.org.uk/news-blogs/microsoft-narrator-turns-21-we-celebrate-coming-age";
U(DEV,"kngold",{src:[KGBS,KGQC,KGDT],ha:"Keynote Gold was the speech built into Pulse Data International's products in New Zealand, including early BrailleNotes running KeySoft. Users and developers identify its voice as BestSpeech, a formant text-to-speech engine from Berkeley Speech Technologies. A Spanish-language user forum says Dr. Michael O'Malley created BestSpeech in 1987 and that Pulse Data licensed it and renamed it Keynote Gold, with the 2009 BrailleNote Apex as the last product to use it; those details come from the forum, not from HumanWare. The software form of the engine survives as b32_tts.dll, a 32-bit Windows file dated 1995, and a hobby project on GitHub runs that file unchanged in an emulator so Keynote Gold's voice can serve as a macOS system voice with VoiceOver. A 2022 post on the DECtalk mailing list recalls that KeySoft could also use DECtalk as an alternative to Keynote Gold."});
U(DEV,"softvert",{yr:1987,y:"On the market by 1987",src:[SVNBP,"https://allinaccess.com/happ/","http://oman.org/blinux/list-archive/blinux-list/2002/msg00823.html"],ha:"Soft Vert was Telesensory Systems' talking screen-access program for the IBM PC and compatibles. Joe Lazzaro and Curtis Chong reviewed it in National Braille Press's Second Beginner's Guide to Personal Computers for the Blind and Visually Impaired (1987). It cost $395, came on an MS-DOS floppy with print, cassette and disk manuals and a braille reference card, and was said to work with WordStar, dBASE, PFS programs and most text-mode software. It supported many synthesizers, including the Artic SynPhonix 200, Votalker IB, Type 'N Talk, Votrax PSS, Echo GP and PC, and DECtalk, but not Speech Plus CallText. Internal speech cards needed Artic's or Votrax's PORTTALK program. Control-0 entered its review mode, which read by character, word, line or screen, and in review mode F3 to F6 changed rate and pitch. The reviewers called it one of the most feature-rich screen review systems then available. In 2002 a Linux user was still running Soft Vert in DOSEMU with an Accent SA. Today the Historical Access Preservation Project lists it as missing software, with no known surviving copy."});
U(DEV,"sysaccess",{src:[SAAW,SABLOG,SA23,PNEUMA],ha:"System Access grew out of FreedomBox, an internet appliance Mike Calvo developed first with Russian programmers. Calvo founded Serotek in 2001; Matt Campbell later took over FreedomBox development. Serotek's own ten-year history dates System Access to 2004. AccessWorld reports that the FreedomBox System Access feature arrived in December 2005, giving speech access to Word, Excel, Outlook Express, PowerPoint text and Internet Explorer without another screen reader. The reviewer noted occasional hangs but strong promise, and said it was hard to call it anything but a screen reader. Serotek pushed for low prices and portability, moving FreedomBox from a box nearly the size of a microwave oven onto a thumb drive (System Access To Go). In July 2007, with version 2.3.0.87, FreedomBox and its network were renamed the System Access Mobile Network. Calvo later founded Pneuma Solutions."});
U(DEV,"prudence",{src:["https://www.audiblegame.com/prudence-screen-reader"],ha:"Prudence is an Android screen reader from Prudence Interactive. Its current product page describes iFlytek voices, including premium voices and several Chinese dialects, built-in speech recognition and voice typing, and two ways to operate: touch gestures or voice commands. With the Xiao Zhi voice assistant turned on, every action can be done by two-way voice conversation, hands free. The app has a rewards scheme that uses regular points and Guangming Points, and an interface designed to visual-accessibility standards for blind and low-vision users, older people, and sighted people in no-look situations. The page gives no launch date."});
U(DEV,"msscreenreader",{src:[NARAB],ha:"No source found documents a separate Microsoft product called Microsoft Screen Reader. Microsoft's first built-in screen reader is Narrator, which debuted in Windows 2000 on February 17, 2000. AbilityNet's Robin Christopherson recalls that blind users long mocked it as the screen reader you used only to download and install a proper one, such as JAWS (first released for Windows in early 1995). By early 2021, though, he judged Narrator a viable competitor to JAWS and NVDA, with richer hotkeys and better handling of Office. Narrator starts with Ctrl+Windows+Enter. This entry is kept so the requested name points readers to Narrator."});
// Batch 49: Lion downloadable voices (verified Oct 31, 2026)
const AI11="https://appleinsider.com/articles/11/03/02/inside_mac_os_x_10_7_lion_dozens_of_high_quality_new_multilingual_speech_voices",TM12="https://9to5mac.com/2012/04/20/tip-bring-siris-voice-to-your-mac-with-samantha-downloadable-voice-for-lion/";
const LION="In March 2011, before Lion shipped, AppleInsider reported that Apple would offer 53 new high-quality voices in more than 40 languages and dialects. Each was about a third to more than half a gigabyte, so they came as optional downloads instead of being preinstalled. They joined Alex (Leopard, 2007) and Vicki (Panther, 2003). The new English voices were Tom, Samantha and Jill (US); Karen and Lee (Australia); Daniel, Emily and Serena (UK); Fiona (Scotland); Sangeeta (India); Moira (Ireland); and Tessa (South Africa). 9to5Mac later identified the voices as Nuance speech technology, the same company that powered Siri. To install one: System Preferences, Speech, Text to Speech, System Voice, Customize.";
const SN={syn:"Nuance (licensed by Apple)"};
U(DEV,"mac_karen",{s:SN,src:[AI11,TM12],ha:LION+" Karen was one of two Australian English voices, with Lee."});
U(DEV,"mac_moira",{s:SN,src:[AI11,TM12],ha:LION+" Moira was the only Irish English voice."});
U(DEV,"mac_fiona",{s:SN,src:[AI11,TM12],ha:LION+" Fiona was the only Scottish English voice."});
U(DEV,"mac_tessa",{s:SN,src:[AI11,TM12],ha:LION+" Tessa was the only South African English voice."});
U(DEV,"mac_serena",{s:SN,src:[AI11,TM12],ha:LION+" Serena was one of three British English voices, with Daniel and Emily."});
U(DEV,"mac_samantha",{s:SN,src:[AI11,TM12],ha:"AppleInsider listed Samantha in March 2011 as one of three new high-quality US English voices for Lion, with Tom and Jill. In April 2012 9to5Mac, following a Reddit user, reported that the downloadable Samantha was the same voice as Siri's in the United States; Lion asked to confirm a 469 MB download when it was selected."});
// Batch 50: BT Speak Pro description (verified Oct 31, 2026)
const BTSP="https://www.blazietech.com/btspeak-product-page",BTSH="https://www.blazietech.com/btspeak-hardware";
U(DEV,"btspeak",{src:[BTSP,BTSH],desc:[
"BT Speak Pro is a flat, pocket-sized slab about 6.1 inches wide, 2.8 inches deep and 0.75 inch thick (15.5 x 7.1 x 1.9 cm), weighing 8.5 ounces (241 grams). It has no screen and no QWERTY keys. Everything is done from a braille keyboard and heard through speech.",
"The top surface is mostly a nine-key Perkins-style braille keyboard, set on a slight curve for comfortable typing. There are six dot keys (three for each hand), a space bar between them, and the dot 7 and dot 8 keys on either side of the space bar, which work as modifiers. Commands are chords: for example, h-chord (h with space) brings up help for wherever you are, and v-chord opens voice commands.",
"Two internal speakers sit at the left and right sides of the top. A built-in vibration motor gives haptic feedback. When it's turned on, BT Speak opens straight into the editor, back in the last document you were working on.",
"For connections, there's one USB-C port, used to charge and also to connect headphones, a USB drive, a braille display or a wireless QWERTY keyboard receiver; a mini HDMI port for a monitor; and a microSD card slot. Inside are Wi-Fi, Bluetooth 5.0, a Raspberry Pi Compute Module 4 with 8 GB of RAM and 32 GB of flash storage, and an 8,200 mAh battery that lasts about 10 hours. It can be used while charging.",
"It has two modes, switched with one keystroke. Traditional mode is a menu system modeled on the Braille 'n Speak, with an editor, calendar, phonebook, calculator, radio tuner, media player and AI chat. Desktop mode runs the Linux MATE desktop with the Orca screen reader, LibreOffice, Thunderbird, Firefox and Chromium. Voices include Vocalizer, RHVoice, Pico, Festival Lite, eSpeak and DECtalk."]});
// Batch 52: short histories, part 1 (verified Oct 31, 2026)
const WVX="https://en.wikipedia.org/wiki/Votrax",WMS="https://en.wikipedia.org/wiki/Microsoft_text-to-speech_voices",WZT="https://en.wikipedia.org/wiki/ZoomText",WVO="https://en.wikipedia.org/wiki/VoiceOver",WPT="https://en.wikipedia.org/wiki/PlainTalk";
U(DEV,"votraxpss",{src:[WVX],ha:"Votrax released the Personal Speech System in 1982. It used the SC-01-A chip, controlled by a Zilog Z80 processor with two 8K EPROMs, four TTL chips and 2K of RAM, all sealed in epoxy so the design couldn't be copied. Its text-to-speech was based on the text-to-phoneme rules Votrax developed with the U.S. Naval Research Laboratory in 1973, the same rules used in the Type 'N Talk. Votrax restructured in 1984 and stopped making new consumer products, but kept selling the PSS, on and off, until at least October 1990."});
U(DEV,"votraxvoice",{src:[WVX],ha:"Votrax began in 1971 as a division of Federal Screw Works in the Detroit area. It took its name in 1974 from its first commercial product, the VS4 'Votrax', and became the independent Votrax International in 1980. The SC-01 chip (1980) put a whole phoneme synthesizer on a single integrated circuit. The SC-01-A (1981) was used in the Type 'N Talk and the Personal Speech System, as well as arcade games such as Wizard of Wor and Gottlieb pinball machines. It was succeeded by the SC-02, made by Silicon Systems as the SSI-263P, which became the voice of Artic's SynPhonix cards. A Votrax synthesizer was also part of the first Kurzweil Reading Machine."});
U(DEV,"ms_hazel",{src:[WMS],ha:"In Windows 8, David, Hazel and Zira were designed to sound more natural than Anna, the voice of Vista and Windows 7. Server versions of the same voices were available through the Microsoft Speech Platform for older versions of Windows."});
U(DEV,"ms_mark",{src:[WMS],ha:"With Windows 10, Microsoft tried to use the same speech voices across all its platforms. Mark is not the voice of Cortana; Cortana's organic responses used a hidden voice called Eva. Microsoft has updated the mobile voices through Windows updates to sound more natural than the originals."});
U(DEV,"ms_george",{src:[WMS],ha:"These mobile voices came from Windows Phone 8 and 8.1 and Windows 10 Mobile. Most desktop language packs had only female voices, but every mobile pack came as a male and female pair, so downloading a language added both. Microsoft has updated the mobile voices through Windows updates to sound more natural than the originals."});
U(DEV,"ztwin",{src:[WZT],ha:"Ai Squared first released ZoomText for MS-DOS in 1988. Freedom Scientific bought Ai Squared in 2016. ZoomText comes in two editions, Magnifier and Magnifier/Reader (with a built-in screen reader); it magnifies up to 60 times and supports two monitors. After version 11 (2017), it switched to year-based version numbers, and updates now arrive every four to six weeks. Version 2026.2605.28 came out in May 2026."});
U(DEV,"vomac",{src:[WVO,WPT],ha:"Before Alex, Mac voices descended directly from the early-1990s Speech Manager; Alex added natural-sounding breaths. VoiceOver's Screen Curtain, which blanks the display, is available on the Mac as well as iOS. Apple brought VoiceOver to the iPod shuffle (with spoken playlists from the 2010 model) and, in September 2010, to the iPod nano. In macOS Big Sur 11.3, Apple removed the gender labels from all its voices."});
U(DEV,"voios",{src:[WVO],ha:"VoiceOver on iOS works by gestures: sliding a finger around the screen speaks whatever is under it, so blind users can explore the real layout of an app, and a double-tap activates the selected item. Screen Curtain turns the display off but leaves touch active, saving battery. VoiceOver is turned on in Settings, Accessibility; it can also be set to toggle with a triple-click of the Home or side button, or turned on and off by asking Siri."});
U(DEV,"macosxspeech",{src:[WPT],ha:"Text-to-speech has been part of every version of Mac OS X and macOS. In 10.3 Panther the Victoria voice was rebuilt as Vicki, nearly 20 times larger because of higher-quality diphone samples (Victoria was kept). Alex arrived in 10.5 Leopard. Lion added more English accents and 21 other languages. In macOS Big Sur 11.3, Apple removed gender references from every voice, at the same time as the Siri voice changes in iOS 14.5."});
// Batch 53: short histories, part 2: classic Mac voices (verified Oct 31, 2026)
const CMU="https://www.cs.cmu.edu/Groups/AI/util/pubs/faqs/speech/mac.txt",TEGG="https://discmaster.textfiles.com/view/21387/Macformat17.cdr/Shareware%20City/Sound/Talking%20Eggs%201.0/Talking%20Eggs%20ReadMe";
const EGG="René Ros's Talking Eggs utility (version 1.0, June 18, 1994) revealed that each MacinTalk III voice had an age and a joke phrase stored as its comment instead of a description.";
U(DEV,"mac_hysterical",{src:[TEGG],ha:EGG+" Hysterical's listed age was 30, and its phrase was \"Please stop tickling me!\" The readme warned that the voices could sound chopped up and that a Quadra seemed to be needed for them to work properly."});
U(DEV,"mac_deranged",{src:[TEGG],ha:EGG+" Deranged's listed age was 30, and its phrase was \"I need to go on a really long vacation.\" Other voices in the set included Albert, Bad News, Bahh, Bells, Boing, Bubbles, Cellos, Fred, Good News, Junior, Kathy, Pipe Organ, Princess, Ralph, Trinoids, Whisper and Zarvox."});
const MTP="In September 1994 Joe Campbell's comp.speech guide explained how to get Apple's Speech Manager free from ftp.apple.com, or with At Ease 2.x and the System 7.5 CD-ROM. MacinTalk Pro (1.2) needed a 68020 or better and System 7, and came with Agnes, Bruce and Victoria, each in a large high-quality version and a small lower-quality one; the voices download was about 12.5 MB. Campbell rated the high-quality voices among the best synthesized speech he had heard.";
U(DEV,"mac_agnes",{src:[CMU],ha:MTP});
U(DEV,"mac_bruce",{src:[CMU],ha:MTP});
U(DEV,"mac_victoria",{src:[CMU],ha:MTP});
U(DEV,"mtpro",{src:[CMU],ha:"In 1994, MacinTalk Pro 1.2 was a free download from Apple, installed by putting the voices in a Voices folder inside the Extensions folder. Joe Campbell rated it among the best text-to-speech he had heard, though he thought Bellcore's Orator might handle proper nouns better."});
U(DEV,"mt2",{src:[CMU],ha:"In 1994 Apple offered it as the low-end option of its free Speech Manager download. MacinTalk 2 (1.2) gave moderate-quality speech for Macs with little memory or processing power, and ran on System 6 on a Mac Plus. Speech Manager 1.2.1 included the Fred voice, the MacinTalk 2 extension added Marvin, and an extra voices file added nine more."});
U(DEV,"mt3",{src:[TEGG],ha:EGG+" Fred's was \"I sure like being inside this fancy computer,\" Kathy's \"Isn't it nice to have a computer that will talk to you?\" and Zarvox's \"That looks like a peaceful planet.\""});
// Batch 54: short histories, part 3 (verified Oct 31, 2026)
U(DEV,"spiel",{src:[],ha:" Blind American developer Nolan Darilek started Spiel in 2009, soon after Android 1.6 Donut added screen reader and text-to-speech support, and released it on the Android Market in November 2010. He described it as a flexible, scriptable screen reader. Android at the time didn't allow touch-screen exploration, so Spiel worked best on phones with physical keyboards. It was English-only and supported Android up to 2.3 Gingerbread; volunteers later adapted it for Android 4.0 and 4.2."});
U(DEV,"echo2",{src:[],ha:" The 1982 manual, written by Mike and Fern Kory for Street Electronics of Carpinteria, California, includes a section on features specifically for blind users, and an appendix on using the Echo with an Apple-Cat modem to answer the telephone. Raised Dot Computing transcribed the manual into grade 2 braille with its Braille-Edit system."});
U(DEV,"dtlt",{src:[],ha:" RC Systems says it is built on the RC8650 chipset and is fully self-contained, with a built-in speaker, headphone jack, volume control and serial interface. It needs no drivers: you send it text the way you would send text to a printer. RC Systems called it the synthesizer of choice for thousands of blind PC users. It has since been retired and is no longer sold."});
U(DEV,"jieshuo",{src:[],ha:" Accessible Android notes that Jieshuo was formerly known in English as Commentary or TalkMan. Ömer Yeşiltaş translated Jieshuo into Turkish after switching to Android in 2019."});
// Batch 55: short histories, part 4 (verified Oct 31, 2026)
const WWN55="https://en.wikipedia.org/wiki/WaveNet",WSRS55="https://en.wikipedia.org/wiki/Speech_Recognition_%26_Synthesis",WSIRI55="https://en.wikipedia.org/wiki/Siri";
U(DEV,"wavenet",{src:[WWN55],ha:" DeepMind, the London AI lab, first described WaveNet in a research paper in September 2016. Instead of joining recorded fragments of speech, it builds the audio waveform one sample at a time with a neural network trained on real speech. The original model, trained on English and Mandarin, produced 16,000 samples a second and could even reproduce breaths and lip smacks."});
U(DEV,"gtts",{src:[WSRS55],ha:" Wikipedia gives the first release as October 10, 2013. The app is now called Speech Recognition & Synthesis. It provides voices for Google Play Books, Google Translate, TalkBack and third-party apps, and users install voice data separately for each language. Support for older Android versions has been dropped in stages: Ice Cream Sandwich and Jelly Bean in 2017, KitKat in 2020, Android 5 in 2021, and Android 6 and 7 in 2023."});
U(DEV,"siriquinn",{src:[WSIRI55],ha:" Siri launched with female voices in most countries; Apple added a male option in June 2013. For iOS 11, Apple recorded several hours of new speech to build deep-learning voices. Quinn, added in February 2022, was Apple's first gender-neutral Siri voice."});
// Batch 56: short histories, part 5 (verified Oct 31, 2026)
U(DEV,"rhvoice",{src:["https://github.com/RHVoice/RHVoice/blob/master/README.md"],ha:" RHVoice uses statistical parametric (HMM) synthesis built mainly on the open-source HTS toolkit, so it stores only small statistical models rather than recordings. Its README says it began as Russian-only and now also speaks American and Scottish English, Brazilian Portuguese, Esperanto, Georgian, Ukrainian, Kyrgyz, Tatar, Macedonian, Albanian and Polish. It runs on Windows (SAPI 5), Linux (Speech Dispatcher) and Android (F-Droid and Google Play), and ships its own NVDA driver."});
U(DEV,"fenrir",{src:["https://github.com/chrys87/fenrir/blob/master/README.md"],ha:" The README calls Fenrir a modern, modular, flexible and fast console screen reader, licensed under LGPL v3 and written in Python 3. It speaks through eSpeak or eSpeak NG, Speech Dispatcher or Emacspeak, supports braille through BRLTTY (a work in progress), and includes a spell checker. Development now continues at git.stormux.org/storm/fenrir."});
U(DEV,"jenux",{src:[],ha:" The jenux.dev build page offers installers and live environments for x86_64, i686 and aarch64 (including Raspberry Pi and virtual machines on phones), in Base GUI, GNOME, MATE, Plasma, Kodi and RetroArch variants. Builds come as ISOs, VMDK virtual-machine images, rootfs images and Chrome OS Crostini images, along with a Docker image. The page also has a sample configuration file for unattended setup and step-by-step key sequences for enrolling the Jenux key on Secure Boot machines."});
// Batch 57: Eloquence presets (verified Oct 31, 2026)
const ELQ57="https://github.com/Mudb0y/eloquence/blob/main/README.md";
const ELQT=" Eloquence's programming interface (ECI) defines eight voice presets, numbered 0 to 7: Reed, Shelley, Bobby, Rocko, Glen, Sandy, Grandma and Grandpa. Speed (0 to 250) and pitch (0 to 100) can be changed on any preset. A 2026 hobby project (described by its own author as untested) runs ETI Eloquence 6.1, taken from the firmware of the LevelStar Icon PDA, on 64-bit Linux through QEMU emulation, with a Speech Dispatcher module for Orca.";
U(DEV,"el_bobby",{src:[ELQ57],ha:ELQT+" Bobby is preset 2."});
U(DEV,"el_glen",{src:[ELQ57],ha:ELQT+" Glen is preset 4."});
// Batch 58: DoubleTalk PC and Hal histories (verified Oct 31, 2026)
U(DEV,"dtpc",{src:[],ha:" An early-1990s Raised Dot Computing newsletter sold the DoubleTalk PC for $280 and explained its roots. RC Systems' first product was the SlotBuster, a multi-function Apple II card with a speech synthesizer, but many programs required an Echo, so RC Systems built the DoubleTalk for the Apple, which combined the SlotBuster voice with an Echo-like synthesizer. The PC version added more speech capabilities, for four synthesizers on one board. The newsletter listed Flipper and ASAP among the screen readers that supported it."});
U(DEV,"halwin",{src:[],ha:" AccessWorld reviewed Hal 6.51 in 2006, alongside JAWS 7.0 and Window-Eyes 5.5. Installing it took three steps: the screen reader itself, Dolphin's Synthesizer Access Manager (SAM), and the Orpheus software synthesizer, with IBM ViaVoice on an optional CD. Hal could copy the keyboard commands of other screen readers such as JAWS, and it used downloadable map files to configure itself for specific programs. It was also sold as the Dolphin Pen edition, which ran from a USB flash drive."});
// Batch 59: last three short histories (verified Oct 31, 2026)
U(DEV,"apollo",{src:["https://archive.org/details/DolphinApollo2Manual","https://github.com/rommix0/dolphin-apollo-ii-reborn"],ha:" Dolphin's 1998 Series 2 user guide says its synthesizers were developed alongside the Hal screen reader. The family offered more than forty languages, with up to seven in one synthesizer. The Apollo 2 was a mains-powered desktop unit with a built-in loudspeaker that connected to a PC's serial port with a non-standard Dolphin cable, and held up to four languages in replaceable ROMs. It was one of the few synthesizers with a British English voice. Its siblings were the PC 2 internal card and the Juno, a pocket-sized battery unit with about 10 hours of battery life. In 2026 the Dolphin Apollo II Reborn project on GitHub decompiled the Apollo 2 firmware into C."});
U(DEV,"vocalizer",{src:["https://en.wikipedia.org/wiki/Nuance_Communications","https://en.wikipedia.org/wiki/Cerence"],ha:" The company behind it began as Visioneer (1992), which bought ScanSoft from Xerox in 1999 and took its name. ScanSoft entered speech technology by buying Lernout & Hauspie's assets in December 2001 and SpeechWorks in 2003, then merged with Nuance in late 2005 and adopted the Nuance name. Nuance's automotive division was spun off as Cerence in October 2019."});
U(DEV,"samsungva",{src:["https://accessibleandroid.com/a-decade-with-android-highlighting-observations-and-shifts/"],ha:" Accessible Android notes that Samsung's interface supported multi-finger screen reader gestures in Voice Assistant long before Android itself did. Android added official multi-finger gestures in Android 11, when Samsung's TalkBack replaced Voice Assistant; Google's own TalkBack didn't get them on Samsung phones until Android 12."});
// Batch 60: Keynote description, BrailleNote PK history (verified Oct 31, 2026)
const AWRS="https://afb.org/aw/6/6/14572",WHX="https://en.wikipedia.org/wiki/Epson_HX-20",AWPK="https://afb.org/aw/6/1/14662";
U(DEV,"keynote",{src:[AWRS,WHX],desc:["The Keynote was a talking portable computer built on the Epson HX-20, one of the first notebook-sized computers. AccessWorld's 2005 profile of Russell Smith says the complete Keynote weighed about six pounds.","The HX-20 itself had a footprint of roughly A4 paper, about 8.3 by 11.7 inches, and on its own weighed about 1.6 kilograms (3.5 pounds), light enough to hold in one hand. The difference in weight between the bare HX-20 and the six-pound Keynote suggests that extra hardware was added, but the sources found don't say what that hardware was or where it sat.","The HX-20 has a full-travel typewriter-style keyboard, so you type on the Keynote with ordinary QWERTY keys rather than braille keys. Behind the keyboard, the HX-20 has a small LCD screen that shows 4 lines of 20 characters, and a calculator-sized dot-matrix printer that uses rolls of paper.","The HX-20 ran on built-in rechargeable nickel-cadmium batteries, which made it fully portable. A 1987 review by Deborah Kendrick in Tactic praised the Keynote's speed, portability and good built-in speech, and said that about 7 seconds after you switched it on you were back in the file of your choice.","We haven't found any first-hand description of where the Keynote's speaker, headphone jack or ports are, or how it differs on the outside from a standard HX-20. Those details are not documented in any source we checked."]});
U(DEV,"bnpk",{src:[AWPK],ha:"Pulse Data International announced the BrailleNote PK in July 2004 as the newest and smallest member of the BrailleNote family. AccessWorld's January 2005 review called it the smallest Windows-based accessible PDA on the market: about a pound, roughly 7 by 4 by 2 inches, with an 18-cell braille display. It replaced the earlier models' infrared port with Bluetooth and dropped the parallel port and built-in modem; Wi-Fi was available through a Compact Flash card. It ran Pulse Data's Keysoft suite, including KeyWord, KeyPlan, KeyMail and KeyWeb."});
// Batch 61: replace removed NFB-timeline sources; K-NFB Reader description (verified Oct 31, 2026)
const HTH="https://www.helptech.eu/history",HTA="https://www.helptech.eu/about-us",AWKN="https://afb.org/aw/7/6/14430",AWKN2="https://afb.org/aw/7/5/14548",WKN="https://en.wikipedia.org/wiki/K-NFB_Reader",ECHOM="https://www.duxburysystems.org/downloads/library/texas/apple/manuals/echo.htm";
Object.assign(CO.find(x=>x.id==="ht"),{src:[HTH,HTA],h:"Siegfried (Sigi) Kipke restarted the company as Handy Tech Elektronik GmbH in Horb, Germany, in 1994 with 8 staff, continuing the braille-display work begun there by Klaus Peter Schönherr, who invented the first braille module in 1975. It was renamed Help Tech GmbH in 2017 and became Help Tech GmbH & Co. KG in 2024. Products include the Braille Wave (1999), Braille Star 40 and 80 (2002), Braillino (2003), Modular Evolution (2006), Active Braille (2011) and Active Star (2015)."});
Object.assign(CO.find(x=>x.id==="knfb"),{src:[AWKN2,WKN],h:"K-NFB Reading Technology was the partnership of inventor Ray Kurzweil and the National Federation of the Blind. Work began around 2002, and the handheld K-NFB Reader went on sale on July 1, 2006. The software was later ported to the Nokia N82 phone as KNFB Reader Mobile ($1,595). In 2014 an iOS app ($99), developed by the NFB and Sensotec NV, followed, and an Android version came shortly after."});
Object.assign(CO.find(x=>x.id==="street"),{src:[ECHOM],h:"Street Electronics Corporation of Carpinteria, California, made the Echo II speech card for the Apple II (manual copyright 1982), with its Textalker and Speakeasy software. Its trademarks also included Echo GP."});
U(DEV,"knfb",{y:"Released July 1, 2006",yr:2006,src:[AWKN,AWKN2,WKN],ha:"Ray Kurzweil and the NFB began the project about four years before it went on sale on July 1, 2006, the world's first handheld OCR reading system. It used a Fujitsu-Siemens LOOX N560 PDA and a Canon SD20 camera, with Eloquence speech (RealSpeak optional). AccessWorld noted it was about 1,000 times smaller than the original Kurzweil Reading Machine and about one-fifteenth the price.",desc:["The K-NFB Reader is a handheld reading machine about the size of a thick paperback: 6 inches long, 3 inches wide and 2.5 inches deep, weighing 15 ounces. It is really two off-the-shelf devices, a Fujitsu-Siemens LOOX N560 pocket PC and a Canon SD20 digital camera, joined in a leatherette case that also holds the electronics connecting them.","In the normal reading position, the screen and control panel face up toward the ceiling, with the controls closest to you. The control panel is a rectangle of nine buttons. In the middle is a five-way control like a phone's: an Enter button surrounded by up, down, left and right arrows. Function buttons F1 and F2 are to the left of it, and F3 and F4 are to the right. Behind the controls is a 3.5-inch screen under a thick plastic cover.","The front edge, facing you, has just one control: a large reset button on the right. The back edge has the memory card slot and the headphone jack. The left side has only the AC adapter jack, and the right side has nothing.","The camera is fixed under the back end of the PDA, with an autofocus lens pointing down at the page; a mechanical door over the lens opens and closes automatically when the camera turns on or off. The camera has two buttons on its left side: a large smooth button near the back that isn't used, and a smaller flush, rough-textured button that turns the camera on and off. To read, you hold the unit about 16 inches above the page.","It shipped with a small canvas carrying case, about the size of a small lunchbox, with pockets for the PDA charger, a camera battery charger and a spare battery, earbuds with a volume control, and memory cards. AccessWorld found the built-in speaker sometimes too quiet in noisy places such as airports and restaurants."]});
U(DEV,"knfbm",{src:[WKN],ha:"KNFB Reader Mobile ported the K-NFB Reader's software from the original PDA-and-camera unit to the Nokia N82 camera phone running Symbian, at a new price of $1,595. In 2014 the NFB and Sensotec NV released an iOS app for $99, followed shortly by an Android version, which can read documents in more than thirty languages."});
U(DEV,"bwave",{src:[HTH],ha:"Handy Tech presented the Braille Wave in 1999 as the first braille system with note-taking capability, the same year it opened a consulting center in Marburg. In 2004, the Braille Wave was one of the Handy Tech systems equipped with Bluetooth."});
U(DEV,"bstar",{src:[HTH],ha:"Handy Tech introduced the Braille Star 40 and Braille Star 80 in 2002. It described the Star 40 as ideal for use with a laptop, and the Star 80 as a system for professional workplaces, particularly blind telephone operators. The Braille Star 40 gained Bluetooth in 2004."});
U(DEV,"actb",{src:[HTH],ha:"Handy Tech introduced the Active Braille in 2011 with its ATC (Active Tactile Control) technology, first used in 2006 on the Modular Evolution. Help Tech released a more compact redesign with improved controls in 2020–21."});
U(DEV,"actstar",{src:[HTH],ha:"Handy Tech introduced the Active Star in 2015, calling it the universal access terminal for blind computer users. It came a year after the company marked 20 years of Handy Tech and 40 years of braille technology from its Horb team."});
// Batch 63: histories from the NFB 2026 timeline (verified Oct 31, 2026)
const NFT63="https://nfb.org/images/nfb/publications/fr/fr45/2/fr450210.htm";
U(DEV,"abt3",{src:[NFT63]});
U(DEV,"brl2040",{src:[NFT63],ha:"HumanWare launched the Brailliant 20 and 40 in 2004. The NFB's 2026 Braille Technology Timeline calls them the first refreshable braille displays with Bluetooth wireless connectivity. The timeline also notes that BAUM made OEM versions of HumanWare's Brailliant and BrailleConnect displays in the 2000s, a partnership that ended in 2011. HumanWare has kept the Brailliant name for later displays, and its latest model adds notetaker, book-reading and audio functions."});
U(DEV,"mpo",{src:[NFT63],ha:"ALVA released the Mobile Phone Organizer in 2003. The NFB's 2026 Braille Technology Timeline calls it the first and only hybrid of a cell phone and a notetaker. It had a 20-cell braille display, a braille keyboard and a speech synthesizer. ALVA, the Dutch display maker, also held the cursor-routing patent (filed in the Netherlands in 1987, granted in the US in 1991)."});
U(DEV,"bsplus",{src:[NFT63],ha:"HIMS released the original BrailleSense in 2004 and enhanced it as the BrailleSense Plus in 2008, adding the speech-only VoiceSense model the same year. The BrailleSense line offered refreshable braille, speech, a braille keyboard, an LCD, MP3 and DAISY playback, and external monitor support. GW Micro of Fort Wayne, Indiana, was the exclusive US distributor from about 2006 until late 2010, when HIMS opened its own US office in Austin, Texas."});
U(DEV,"bs7",{src:[NFT63],ha:"The NFB's 2026 Braille Technology Timeline calls BrailleSense 7 a significant generational leap for the line. Selvas BLV unveiled it in 2026 in 20-, 32- and 40-cell models running Android 15. Features include touch-sensitive braille cells, built-in Google Gemini AI, more braille-first apps, a user-replaceable battery, and an included QWERTY keyboard case with a second battery."});
U(DEV,"evolve",{src:[NFT63],ha:"HumanWare previewed the BrailleNote Evolve in 2025. It moves the BrailleNote from Android to Windows 11 Pro, with an Intel Core Ultra 5 processor, 32 GB of RAM, up to 512 GB of SSD storage, KeySoft integrated with NVDA, a six-month JAWS trial, Microsoft Office 365 with HumanWare add-ins, Thunderbolt and HDMI ports, and NFC. The first models are 20- and 32-cell units with Perkins-style keyboards; QWERTY and 40-cell models are to follow."});
U(DEV,"bntouch",{src:[NFT63],ha:"The BrailleNote line began in 2000 with Pulse Data's Windows CE-based Classic, followed by the mPower series (2005) and the Apex (2009). The BrailleNote Touch (2016) moved the line to Android, and the BrailleNote Touch Plus followed in 2019. In 2025 HumanWare previewed the Evolve, which moves the line again, to Windows 11."});
U(DEV,"btbraille",{src:[NFT63],ha:"Blazie Technologies launched the BT Speak in 2024 as a modern, Linux-based revival of the Braille 'n Speak. In March 2026 it demonstrated the BT Braille, which the NFB's 2026 timeline describes as a modern take on the Braille Lite, the 1993 Blazie Engineering notetaker that added a refreshable braille display to the Braille 'n Speak."});
// Batch 64: Maestro and Braille Blazer descriptions (AccessWorld; verified Oct 31, 2026)
const AWMA="https://afb.org/aw/6/4/14610",AWBZ="https://afb.org/aw/3/6/14896";
U(DEV,"maestro",{src:[AWMA],ha:"AccessWorld reviewed the Maestro in July 2005 on an HP iPAQ, noting that VisuAide was about to switch to the Dell Axim X50. It priced the Maestro at $1,195, or $1,895 as the Trekker Pro (Trekker GPS plus Maestro). Speech came from Eloquence, and text could be entered in computer braille or by phone-style multi-tap.",desc:["The Maestro is an ordinary pocket PC (an HP iPAQ in AccessWorld's 2005 review) fitted with a tactile keypad that covers its touch screen. It is a flat, silver rectangle about 4.5 by 2.7 by 0.5 inches, weighing about 4.7 ounces. The keypad overlay is also silver, with black and yellow buttons, and is held on by a cloth strap that wraps around the back of the PDA.","All the buttons are on the front. Hold it upright with the narrow ends at top and bottom. Near the top edge, in the center, the PDA's On button sits inside a raised U-shaped line; it is the only button at that end that is on the PDA itself. Just below is the upper part of the keypad: 12 round buttons laid out like a phone keypad for typing, plus 6 more keys including Backspace and two Validate keys, which confirm each character you type.","A finger-width gap separates the typing keys from the navigation section below. On the left is a vertical row of four function keys, F1 to F4. Next to them is a round four-way arrow control with an Enter button in its center. Home, Page Up, Page Down and End are to the right of the arrows, and Tab and Shift-Tab sit below the down arrow, between F4 and End.","At the bottom end, on the PDA's own surface, are five more keys. From left to right they are Escape, Control, Record, Shift, and System Bar/Off; Record sits inside a square navigation surround. On the bottom edge, directly below Record, is the USB connector for the charger and the cradle, with the infrared port to its left. The top-left edge has the headphone jack and the memory card slot, and on the upper left side is an unlabeled button that had no function.","A separate cradle, about 3.1 by 2.25 by 5 inches and 6.1 ounces, connects to a computer by USB for ActiveSync file transfer and charges the Maestro while it sits in it. The box included a Getting Started guide in print and braille and a tactile diagram of the keypad with braille labels."]});
U(DEV,"blazer",{src:[AWBZ],ha:"AccessWorld reviewed the Braille Blazer in November 2002 as one of two portable embossers under $3,000, alongside the Porta-Thiel. It found the Blazer slow and loud but easy to load. Its built-in speech synthesizer spoke the menus and could double as a speech synthesizer for the computer, and the menus could also be embossed for deafblind users.",desc:["The Braille Blazer is a small portable braille embosser. It weighs 12 pounds and measures 13.5 inches wide, 8 inches deep and 5 inches high. With its lid closed it is a plain rectangular box with a carrying handle on the back.","The lid is white, the ridged sides are dark gray, and the front and back are brushed aluminum. On top, three gray function keys sit on the right side of the lid, and a paper-advance rocker switch is on the left side. All the controls are labeled in braille. The three keys are close together and take firm pressure; pressing combinations of them runs the spoken setup menus.","The lid lifts all the way up and stays open, exposing the whole paper path. You open the hinged paper guides on each side, slide continuous fan-fold paper under the rod-shaped platen, set the sprocket holes over the pins, and cover the top-of-form detector opening, which is easy to find by touch. It takes tractor-feed paper or plastic labels up to 8.5 inches wide, and it wastes one sheet each time you load.","The back panel has a parallel port, a serial port, an earphone jack and a voltage selector. A built-in speech synthesizer speaks all of its menus. The Blazer came with an AC power cord and a parallel cable, and a black padded carrying case with a shoulder strap cost $60 extra.","AccessWorld found its printing loud and harsh. It embosses 6- or 8-dot braille and graphics, and can emboss sideways. Its setup prompts can also be embossed for deafblind users, but they end up partly tucked under the curve of the platen bar, which makes them awkward to read."]});
// Batch 65: Handy Tech descriptions from Help Tech user manuals (helptech.eu/downloads; verified Oct 31, 2026)
const HTMAB="https://d5b3656b-37f9-4ef5-85ec-34fbe5588f31.usrfiles.com/ugd/d5b365_7e511ce8f5444c849b27e76b49a2c2bf.pdf",HTMAS="https://d5b3656b-37f9-4ef5-85ec-34fbe5588f31.usrfiles.com/ugd/d5b365_a637e2db78584091b4a5df92d53e20fc.pdf",HTMBS="https://d5b3656b-37f9-4ef5-85ec-34fbe5588f31.usrfiles.com/ugd/d5b365_9ef268bc9ba94006a114248c71f87343.pdf",HTDL65="https://www.helptech.eu/downloads";
U(DEV,"actb",{src:[HTDL65,HTMAB],desc:["The Active Braille (as described in Help Tech's version 4.5 manual, 2018) is a slim 40-cell braille display with built-in note-taking. It measures about 12.6 inches wide, 4.9 inches deep and 1.1 inches high, and weighs about 2 pounds (930 grams).","Place it with the keys toward you. Along the front edge, in the center, are two space bars. Above them, in one row across the unit, are eight braille input keys arranged like a Perkins keyboard: from left to right, dots 7, 3, 2, 1, 4, 5, 6 and 8.","The middle of the top holds 40 concave piezoelectric braille cells. Each cell has its own built-in cursor routing key, so there is no separate row of routing buttons. At each end of the braille line, flush with the cells, is a Triple Action Key: a rocker that you press at its top to read backward, at its bottom to read forward, or in its center for extra commands.","On the right side, from front to back, are the main power button, a USB-A port for a keyboard, and the power socket. On the left side, from front to back, are a second USB-A keyboard port, the microSD card slot, and the USB-B port for connecting to a computer. On the back, at the left, is a 2.5 mm headphone or speaker jack, and a 3.5 mm adapter cable is included.","It has 4 GB of storage and Bluetooth. Help Tech rates the battery at about 20 hours, or about 14 hours when using Bluetooth, with a quick charge in under 3 hours. Its ATC (Active Tactile Control) technology senses where your fingers are reading on the display."]});
U(DEV,"actstar",{src:[HTDL65,HTMAS],desc:["The Active Star (as described in Help Tech's version 3.2 manual) is a 40-cell braille display built to sit in front of a laptop. It measures about 12.7 inches wide, 8.6 inches deep and 0.9 inches high, and weighs about 2.4 pounds, or about 3.15 pounds with its keyboard. It comes in a carrying case with a Velcro flap, and a compact PC keyboard with tactile markings rests on top. That keyboard is held on by magnets and connects through a short USB cable.","Along the front edge, in the center, are two space bars. To the left and right of them are four keys each, which form the braille keyboard: from left to right, dots 7, 3, 2, 1, 4, 5, 6 and 8. Behind those keys runs the line of 40 concave piezoelectric braille cells, each with a built-in cursor routing key. At each end of the line, flush with the cells, is a Triple Action Key that you press at its top, center or bottom.","Behind the braille cells, the top surface slides back to make a stable shelf for a laptop. To open it, take the keyboard off and the unit out of its case, hold the sides near the middle, and push back evenly with your thumbs, just behind the Triple Action Keys; you will feel slight clicks. Fully extended, it reveals a rectangular hollow for a smartphone or Bluetooth audio receiver. On the right wall of the hollow are a charging connector and a 3.5 mm audio jack that routes the sound of the inserted device to the Active Star's speakers.","On the right side, from front to back, are the main power button and a 3.5 mm headphone or speaker jack. On the back, from left to right, are a square USB-B port for a computer or charger, two USB-A keyboard ports, and the microSD card slot, which sits between the upper and lower halves of the case.","Underneath, the lithium-ion battery compartment is in the left rear corner, opened with a latch near the center of the unit. A small round hole about 3 cm from the right side holds a reset button you press with a paperclip. The manual lists a 5200 mAh battery lasting about 40 hours, a 16 GB microSD card, Bluetooth and a small built-in speaker."]});
U(DEV,"bstar",{src:[HTDL65,HTMBS],desc:["This description is of the Braille Star 80, the larger of the two models, as set out in Handy Tech's version 4.2 manual; the Braille Star 40 is a shorter 40-cell version. The Star 80 measures about 23.2 inches wide, 9.7 inches deep and 1.7 inches high, and weighs about 5.5 pounds (2.5 kg). Its battery uses regular AA-size rechargeable cells.","Place it with the controls toward you. Along the front edge, in the center, are two space keys, with four function keys on each side. Those eight keys are also the braille keyboard: from left to right, dots 7, 3, 2, 1, 4, 5, 6 and 8. Behind them runs a line of 80 concave piezoelectric braille cells, each with its own built-in cursor routing key. At each end of the line, flush with the cells, is a Triple Action Key that you press at its top, center or bottom.","Above and behind the cells on the right side is a 16-key number pad, four rows of four keys, laid out like a standard PC number pad. A screen reader can assign commands to these keys.","On the right side, from front to back, are two stereo headphone or microphone jacks, then the main power toggle switch (flip it toward you to turn it on), then the power socket. On the back, from left to right, are two stereo jacks that link to the front jacks and your sound card, a PS/2 keyboard port, the USB port to the computer, a second PS/2 port, a small toggle switch, a third PS/2 port, and the serial port.","The small toggle switch chooses whether the display talks to the computer by USB or serial, and it also switches the PS/2 keyboard pass-through. That lets one keyboard and display serve two PCs. The unit has 4 MB of note memory."]});
// Batch 66: APH Museum records (sites.aph.org/museum-virtual-exhibit; verified Oct 31, 2026)
const APHVTS="https://sites.aph.org/museum-virtual-exhibit/vex5/B05FEC63-3118-4C9D-814D-168516371748.htm",APHDS1="https://sites.aph.org/museum-virtual-exhibit/vex4/4FB23827-7D1E-497F-BC57-230056211832.htm",APHVB2="https://sites.aph.org/museum-virtual-exhibit/vex2/4C6CA28D-5B55-4717-BDF0-166038125352.htm",APHJUL="https://sites.aph.org/museum-virtual-exhibit/vex1/7D6044E7-F4E9-4189-A3F0-428547426285.htm";
U(DEV,"viewscants",{src:[APHVTS],ha:"Introduced in 1983, the Viewscan Text System (VTS-100) was, according to the APH Museum, the first large-print word processor. It was a modified Epson HX-20 portable computer with a large-print display and a small built-in printer. With the optional scanning camera, it could magnify a book page up to 40 times. It was invented by Russell Smith, a former graduate student of Leslie Kay, while he worked for the Sensory Aids Division of Wormald International in New Zealand. Smith later built the Keynote talking computer on the same HX-20.",desc:["The Viewscan Text System is a modified Epson HX-20 laptop-style computer about 14.75 inches wide, 8.5 inches deep and just under 2 inches high (APH Museum example, about 1983). Its case is cream-colored plastic, and an expansion unit is bolted onto the left end. It came in a fitted dark-brown plastic carrying case with a built-in handle and latches.","The front half of the top is a full QWERTY keyboard. The symbol keys are dark brown, the function keys gray-brown, and the Return and Break keys red.","Along the back of the top, from left to right, are a slot for the small built-in paper-tape printer, the LCD screen in the middle (20 characters by 4 lines), and a micro-cassette drive for storing files. A speaker grille sits just below the screen.","On the right side are an on/off slider, a dial for the screen's viewing angle, the cassette eject, a print button, and jacks for a microphone, earphone, remote control and barcode reader. The back has the power adapter jack, a 9-pin RS-232C port and a 6-pin serial port. On the left side, on the expansion unit, is a 25-pin socket for the optional hand-held scanning camera.","Printed labels read \"Viewscan Text System\" at the lower left and \"Wormald International Sensory Aids\" above the screen. A label underneath identifies it as keyboard model VTS 100."]});
U(DEV,"nlsds1",{src:[APHDS1],ha:"According to the APH Museum, NLS introduced its digital talking-book machine in 2009 to replace the cassette players used since the early 1970s. It tested 5,000 machines and then began free nationwide distribution late that year. There were two models: the basic standard player and the DA1 advanced player, which adds navigation controls. Both have a USB jack for playing downloaded books, and APH began making books on the digital cartridges in 2010.",desc:["The NLS digital talking-book player (the museum example is a 2010 standard model) is a boxy, dark charcoal-gray plastic machine with rounded edges. It is about 6 inches wide, 9 inches deep and 2 inches high, and stands on four rubber feet. The battery compartment is underneath.","The front edge has a white-lined slot where you push in the book cartridge. Just below the slot is a white plastic carrying handle that pulls out from the front.","On top is a round speaker grille. To its left is a pair of arrow buttons for Tone, and to its right a pair for Speed. Below the speaker is a raised line, and below that the main buttons, each a different color and shape for touch: a red Power button, a white crescent-moon Sleep button, a rectangular green Play/Stop button between white arrow-shaped Rewind and Fast Forward buttons, and two yellow arrow-shaped Volume buttons, one above the other.","The headphone jack and USB jack are on the right side. The power cord sits in a recess on the back.","The Library of Congress seal and the words \"Library of Congress National Library Service for the Blind and Physically Handicapped\" are embossed on top. The advanced DA1 model adds navigation controls that the standard player lacks."]});
U(DEV,"versab2",{src:[APHVB2],ha:"The APH Museum describes the VersaBraille II+ (about 1987) as an update of Telesensory's 1979 VersaBraille. The original stored data on cassette tape; the II+ added an internal 3.5-inch floppy drive and a joystick. Early testers Howard and David Goldstein liked its disk drive, parallel printing, Duxbury compatibility and menus, but found its proprietary operating system clumsy and its keyboard hard on the wrists."});
U(DEV,"juliet",{src:[APHJUL],ha:"Enabling Technologies, founded as Triformation Systems in the early 1970s, made the Juliet in Stuart, Florida. The APH Museum's 1992 example came from a programmer at Miles Laboratories (later Bayer). He said it gave much higher-quality braille than the LED-120 it replaced.",desc:["The Juliet is a desktop braille embosser (APH Museum example, 1992). It is a rectangular box of ivory-enameled steel with a hinged lid, and has dark gray plastic handles set into its sides for lifting. The maker's ETC logo and the words \"Enabling Technologies Company Juliet Brailler\" are printed in blue on top.","Lifting the lid exposes the embossing head and its moving carriage, the tractor-feed wheels that grip the sprocket holes of fan-fold paper, and a 16-key keypad for setting it up.","Paper feeds in through a slot on the front and comes out through a slot on the back.","Below the back output slot, set into the case, are the parallel and serial ports, the power cord socket, and an on/off rocker switch.","The donated set included a black three-prong power cord, a parallel cable, and a print-and-braille manual in a blue binder with a 3.5-inch floppy disk inside the front cover. It used continuous fan-fold braille paper with tractor holes along the edges."]});
// Batch 67: eSight, OrCam, Ray-Ban Meta histories (Wikipedia raw and Be My Eyes; verified Oct 31, 2026)
const WPES67="https://en.wikipedia.org/wiki/ESight",WPOC67="https://en.wikipedia.org/wiki/OrCam_device",WPMG67="https://en.wikipedia.org/wiki/Meta_smart_glasses",BMERB67="https://www.bemyeyes.com/news/be-my-eyes-is-rolling-out-on-ray-ban-meta-glasses-starting-today/";
U(DEV,"es1",{src:[WPES67],ha:"eSight was founded in 2006 by Conrad Lewis, a Canadian electrical engineer with two legally blind sisters. He wanted a device that would let them see, work and handle daily activities on their own. Wikipedia lists the first-generation headset among products introduced in 2013."});
U(DEV,"es2",{src:[WPES67],ha:"eSight 2 came out in May 2015. Wikipedia says it upgraded the hardware with HD OLED screens, better color and resolution, and longer battery life."});
U(DEV,"es3",{src:[WPES67],ha:"eSight 3 came out in February 2017. In May 2017, Time magazine put eSight on its list of \"The Best Tech of 2017 So Far.\""});
U(DEV,"es4",{src:[WPES67],ha:"eSight 4 came out in early 2020, the fourth generation of the headset from the company Conrad Lewis founded in 2006."});
U(DEV,"esgo",{src:[WPES67],ha:"In 2022, eSight partnered with Gentex Corporation of Zeeland, Michigan, to develop its next device, eSight Go. Gentex acquired eSight's assets in 2023, which was first announced in January 2024. eSight Go, the fifth generation, came out in 2024."});
U(DEV,"orcam1",{src:[WPOC67],ha:"OrCam was founded in Jerusalem in 2010 by Ziv Aviram and Amnon Shashua. In 2013, The New York Times described an employee with coloboma using a pre-release device. In 2016, a JAMA Ophthalmology study of 12 legally blind participants found the OrCam improved performance on reading tasks such as a newspaper article or a menu."});
U(DEV,"orcam2",{src:[WPOC67],ha:"OrCam introduced the MyEye 2.0 in December 2017. It was a battery-powered unit about the size of a finger, weighing 22.5 grams (0.8 ounce), that snaps magnetically onto any eyeglass frame. A basic version read text, and an advanced version added face recognition and barcode reading. Wikipedia gave its price in July 2023 as $4,000 to $6,000."});
U(DEV,"raybanmeta",{src:[WPMG67,BMERB67],ha:"Meta and Ray-Ban launched Ray-Ban Stories in September 2021 and announced the second-generation Ray-Ban Meta on September 27, 2023, with 12-megapixel cameras and Meta AI. In April 2024, Meta AI on the glasses gained camera-based visual input. On November 13, 2024, Be My Eyes became available on them, first in the US, Canada, UK, Ireland and Australia: saying \"Hey Meta, Be My Eyes\" connects you to a sighted volunteer who sees through the glasses' camera and talks to you through the open-ear speakers."});
// Batch 68: HIMS histories (AccessWorld reviews and HIMS product history; verified Oct 31, 2026)
const AWBK68="https://afb.org/aw/10/6/16088",AWCS68="https://afb.org/aw/11/4/16038",AWOH68="https://afb.org/aw/12/10/15988",AWU2M68="https://afb.org/aw/15/5/15576",AWPM68="https://afb.org/aw/20/3/16315",HIMSH68="https://www.himsintl.com/en/company/prd_history.php";
U(DEV,"bksense",{src:[AWBK68,HIMSH68],ha:"HIMS, maker of the BrailleSense, built the BookSense, and GW Micro (maker of Window-Eyes) sold it in the US. AccessWorld reviewed it alongside the Victor Reader Stream and PLEXTALK Pocket. The standard model cost $349 and was the smallest of the three, shaped like a candy-bar phone at 4.25 by 1.85 by 0.73 inches and 4 ounces. It used NeoSpeech Paul and Kate voices and played NLS, Bookshare, Audible and DAISY books."});
U(DEV,"bksxt",{src:[AWBK68,HIMSH68],ha:"The BookSense XT is physically identical to the standard BookSense but adds an FM radio, 4 GB of built-in memory and Bluetooth headset support. GW Micro sold it for $499, compared with $349 for the standard model, and AccessWorld tested the XT with software version 1.1."});
U(DEV,"bksds",{src:[AWCS68],ha:"GW Micro began taking orders for the Book Sense DS at $499, along with the Voice Sense QWERTY at $1,995, after announcing both at the CSUN conference in March 2010. AccessWorld's 2010 convention roundup reported that a US delivery date had not yet been announced."});
U(DEV,"onhand",{src:[AWOH68,AWCS68,HIMSH68],ha:"GW Micro showed the Braille Sense OnHand as an 18-cell prototype in 2010, only slightly larger than the voice-only Voice Sense. HIMS later launched it when it opened its first US office, in Austin, Texas. AccessWorld's review priced it at $4,995, with the Sendero-based Sense Navigation GPS software an extra $1,595. It came with a spare battery and a charger that beeps when a battery is ready."});
U(DEV,"u2mini",{src:[AWU2M68,HIMSH68],ha:"HIMS lists the Braille Sense U2 Mini as a 2013 product. AccessWorld's review praised it as versatile, responsive and robust at $3,995, while noting its display has only 18 cells. It shipped with a carrying case, two user-replaceable lithium batteries, a charger, and a braille command summary, and it had Wi-Fi and Bluetooth."});
U(DEV,"polmini",{src:[AWPM68,HIMSH68],ha:"HIMS announced the BrailleSense Polaris Mini a few months after the 32-cell Polaris, which AccessWorld reviewed in January 2018. It is a 20-cell version running Android 5.1.1 on a Samsung Exynos octa-core processor with 64 GB of storage. Unlike the Polaris, it charges over USB-C (about 3.5 hours) and keeps its microSD card in the battery compartment."});
// Batch 69: HumanWare / VisuAide histories (AccessWorld; verified Oct 31, 2026)
const AWMP69="https://afb.org/aw/7/1/14531",AWDP69="https://afb.org/aw/5/1/14793",AWVS69="https://afb.org/aw/14/4/15708",AWTK69="https://afb.org/aw/19/5/15095";
U(DEV,"bnmpqt",{src:[AWMP69],ha:"HumanWare introduced the BrailleNote mPower on June 28, 2005, and first showed it at that summer's NFB and ACB conventions. It was the same size as earlier BrailleNotes and came with either a braille or a QWERTY keyboard; the QT models have the QWERTY keyboard. The QT32 cost $6,195 and the QT18 $4,395. Owners of earlier units could have their braille display \"transplanted\" into a new mPower."});
U(DEV,"vnmp",{src:[AWMP69],ha:"The VoiceNote mPower was the speech-only version of the mPower, introduced on June 28, 2005, with either a braille keyboard (BT) or a QWERTY keyboard (QT). It cost $1,995 plus $45 shipping. Sendero's GPS software was an option for both the VoiceNote and BrailleNote mPower."});
U(DEV,"vrclassic",{src:[AWDP69],ha:"AccessWorld's review of four DAISY book players covered VisuAide's Victor Reader Classic Plus at $375. It measured 9.3 by 8.2 by 2.1 inches, weighed 2.42 pounds, and had a top that slopes up toward the back, a carrying handle, and 25 keys including a phone-style keypad. It took about 10 seconds to load a DAISY CD and could also play music CDs."});
U(DEV,"vrs2",{y:"February 2013",yr:2013,src:[AWVS69],ha:"AccessWorld says HumanWare released the updated Stream in February 2013, six years after the original. It is 4.5 by 2.4 by 0.7 inches and weighs 3.9 ounces. Compared with the original, it is smaller with more rounded corners, adds Wi-Fi and a Micro USB port, has a louder speaker, uses Acapela voices instead of Nuance Vocalizer, and includes the former Soft Pack features such as DOCX and EPUB support. The reviewer still preferred the classic Stream."});
U(DEV,"trek",{src:[AWTK69],ha:"HumanWare announced the Victor Reader Trek in summer 2017. It combines the second-generation Victor Reader Stream with the GPS wayfinding of the Trekker Breeze (about 2011). Customers who ordered that summer or fall reported getting their units only in January and February 2018. AccessWorld's review listed the price as $699 US or $895 Canadian."});
// Batch 70: RUBY HD and Compact+ (Freedom Scientific user guide; AccessWorld Sept 2007; verified Oct 31, 2026)
const FSRHD70="https://support.freedomscientific.com/content/Documents/Manuals/RUBY/RUBY-HD-Users-Guide.pdf",AWCP70="https://afb.org/aw/8/5/14311";
U(DEV,"rubyhd",{src:[FSRHD70],ha:"Freedom Scientific's RUBY HD user guide (part 440648-001) describes a handheld magnifier with an autofocus HD camera and a 4.3-inch color screen. It zooms from 2x to 13x with its handle open, or 4x to 10x with the handle closed and the unit resting flat on a page. It offers 5 default and 15 extra color modes, stores about 80 images, and runs on four AAA batteries.",desc:["The RUBY HD is a pocket-sized handheld video magnifier, about 4.9 inches high, 2.9 inches wide and 1.4 inches deep, and weighing 8 ounces (227 grams). Most of the front is a 4.3-inch color LCD screen.","Its controls are a few large buttons, each a different color so you can tell them apart. The green-and-yellow button turns it on and off. Two yellow buttons, plus and minus, zoom in and out; hold them for continuous zoom. Two blue buttons scroll up and down through the color modes, such as yellow text on blue. A red button freezes the image, and pressing it again returns to the live view.","On the back is a fold-away handle that also holds the batteries. Unfold it to hold the RUBY HD like a magnifying glass over a can, pill bottle or price tag. Fold it flat to rest the unit directly on a newspaper, letter or receipt and slide it along.","The guide's diagrams show the HD camera sensor and LED reading lights on the side facing the page, and the power connector, a battery status light and a USB port on the body. The USB port is for copying saved images to a computer.","To change the batteries, unfold the handle fully and slide off the battery cover in the direction of its printed arrow. It takes four AAA batteries, either the included rechargeables or regular alkalines; a full charge takes about 2 hours."]});
U(DEV,"compactplus",{src:[AWCP70],ha:"AccessWorld described the Compact+ in September 2007 as new to the market and a complete redesign of Optelec's earlier handheld Compact. It cost $795, the same as its rival, the Enhanced Vision Nemo. The reviewer found it smaller, lighter and easier to hold, with a single one-finger control, but with a dimmer, more glare-prone screen. Optelec said it was the only product in its class to run on rechargeable AA batteries.",desc:["The Compact+ is a handheld video magnifier about 5 inches long, 3 inches wide and 1.25 inches thick, and it weighs 10.6 ounces. Most of the top is a 4-inch LCD screen.","Next to the screen is a single round control. Turning a lever on it changes the magnification between three levels, 5x, 7.5x and 10x, and the same control switches the viewing modes. A Snapshot feature freezes the picture so you can hold it closer or show it to someone, and you can magnify the frozen image too.","Underneath, the camera is attached to the battery compartment, which slides along a track. Move it directly under the screen for reading, or slide it to the side to leave room for a pen when writing.","A collapsible handgrip also folds out from the underside and snaps into place, so you can hold the unit like a traditional magnifying glass.","It runs on a pack of two rechargeable AA batteries, which charge in the unit in about three hours and last about as long. Ordinary store-bought AA batteries also work. The box included a carrying case, a neck strap and a power supply. The manual is a spiral-bound, postcard-size booklet printed in 14-point type."]});
// Batch 71: histories for RUBY, Viewscan, Emprint, VP Max, SMART Brailler (verified Oct 31, 2026)
const FSRU71="https://support.freedomscientific.com/content/Documents/Manuals/RUBY/RUBY-Users-Guide.pdf",APHVTS71="https://sites.aph.org/museum-virtual-exhibit/vex5/B05FEC63-3118-4C9D-814D-168516371748.htm",VPEM71="https://viewplus.com/viewplus-introduces-emprint-new-braille-printer-with-color-hp-inkjet/",VPMX71="https://viewplus.com/the-max-has-gone-rogue/",WPPB71="https://en.wikipedia.org/wiki/Perkins_Brailler";
U(DEV,"ruby",{src:[FSRU71],ha:"Freedom Scientific's original RUBY user guide (part 440530-001) describes a handheld magnifier with a fold-away handle that also holds four AAA batteries, rechargeable or alkaline. You can hold it like a magnifying glass or rest it flat on a document, and it saves up to 15 images. The RUBY HD later raised that to about 80 images and added an HD camera."});
U(DEV,"viewscan",{src:[APHVTS71],ha:"The APH Museum describes the Viewscan, introduced in 1980, as a portable hand-scanning device that showed print in large type for people with low vision. Its maker, the Sensory Aids Division of Wormald International, followed it in 1983 with the Viewscan Text System, the first large-print word processor. With the optional camera, that system could magnify a page up to 40 times."});
U(DEV,"emprint",{src:[VPEM71],ha:"On May 16, 2006, ViewPlus Technologies of Corvallis, Oregon, announced Emprint, which it called the world's first braille printer to emboss braille along with matching color ink in a single pass. That let sighted teachers and colleagues read the print above or beside the braille. Raised graphics were printed in color, with darker shades embossed higher. It cost $5,995, including braille translation software, and used ordinary inkjet cartridges and paper."});
U(DEV,"vpmax",{src:[VPMX71],ha:"ViewPlus says the VP Max, which users nicknamed the \"Tiger,\" served from 2009 and was chosen by Smarter Balanced to emboss tests for visually impaired students. ViewPlus retired it in its 25th year in business, replacing it with the VP Rogue. The Rogue could still use VP Max print files and was ViewPlus's first new specialty tactile-graphics printer in more than a decade."});
U(DEV,"smartbr",{src:[WPPB71],ha:"Perkins launched a lighter, quieter Next Generation brailler for students in 2008. It won a 2009 International Design Excellence Award but got a mixed response from braille users, and Wikipedia says it was replaced by the SMART Brailler in 2012. Wikipedia notes that the original brailler's design itself remains unchanged."});
// Batch 72: Braillo 200, Juliet 120 (braillo.com about-us; InsideVision product sheet; verified Oct 31, 2026)
const BRAB72="https://braillo.com/about-us/",IVJ72="https://www.insidevision.fr/pdf_cat/Fiche_Produit_Braille_Imprimantes_Romeo60_Juliet120_01.pdf";
U(DEV,"braillo200",{src:[BRAB72],ha:"Braillo, which introduced the world's first double-sided production embosser (the Braillo 270) in January 1980, expanded its line in 1986 with the Braillo 200. Braillo describes it as a compact double-sided embosser known for its reliability and consistent braille quality."});
U(DEV,"juliet120",{y:"Introduction year not found. The Juliet 120 is a later model developed jointly with Index Braille, so the original Juliet's 1992 date does not apply to it.",src:[IVJ72],ha:"French dealer InsideVision describes the Romeo 60 and Juliet 120 as a pair of embossers born of a collaboration between Enabling Technologies in the US and Index Braille in Europe. It priced the Juliet 120 at €3,789 and the Romeo 60 at €3,499. The Juliet embosses double-sided at 120 characters per second, has a built-in Liblouis braille translator, and accepts print jobs from phones, tablets, USB sticks and Windows, Mac or Linux computers.",desc:["The Juliet 120 is a desktop braille embosser about 52 cm (20.5 inches) wide, 26 cm (10.2 inches) deep and 13 cm (5.1 inches) high, and it weighs 7.6 kg (about 16.8 pounds), according to InsideVision's product sheet.","Its control panel keys are labeled in both braille and print. They are backlit, with indicator lights, and the embosser speaks its settings in a high-quality Acapela voice.","A motorized paper drive feeds continuous fan-fold paper. It takes paper from 120 to 180 g/m², the weight of typical braille paper, and can emboss on both sides or one side, including magazine-style layouts.","It connects by USB, wired Ethernet, Wi-Fi or Bluetooth, and can print straight from a USB stick. A web app lets you manage it and print from a browser. The product sheet does not say where each connector sits on the case.","InsideVision lists its noise at 80 dB(A), or 60 dB(A) with the optional sound-reducing cover, which cost €1,395 extra. The embosser stores up to 10 user profiles."]});
// Batch 73: Romeo Attaché and Romeo Pro 50 histories (Enabling Technologies user's manual, revised November 2010; verified Oct 31, 2026)
const ETM73="https://manualzilla.com/doc/5765358/romeo-attach%C3%A9-romeo-attach%C3%A9-pro-romeo-25-and-romeo-pro-50";
U(DEV,"romeo",{src:[ETM73],ha:"Enabling Technologies of Jensen Beach, Florida made the Romeo Attaché and the Attaché Pro as its smallest embossers. They share one user's manual with the Romeo 25 and Romeo Pro 50, and the November 2010 revision describes them. Both are single-sided impact embossers that print 15 characters per second and up to 32 cells per line on sprocket-fed paper 1.5 to 8.5 inches wide. Each weighs 16.75 pounds in a desktop case with a handle. The Pro adds ET Speaks voice feedback, which announces keypad entries and status, and a single-sheet mode. Every model plays an excerpt from Tchaikovsky's Romeo and Juliet when its power-on self-test passes."});
U(DEV,"romeopro50",{src:[ETM73],ha:"The Romeo Pro 50 was the faster, talking sibling of the Romeo 25 in Enabling Technologies' Romeo family. The company's November 2010 user's manual lists it at 50 characters per second with a 40-cell line, on paper up to 13.25 inches wide, in a 32-pound plastic carrying case with a handle. It adds ET Speaks speech feedback, with six voices, and a single-sheet mode for loose paper. It has parallel, serial and USB ports, a 16-key keypad, 16 stored setting menus and an 18,000-character Multi-Copy buffer that can make up to 99 copies."});
// Batch 74: GoVision (AVH CERTAM evaluation, Jan 5, 2017); BrailleSense 6 mini (Selvas BLV product page) (verified Oct 31, 2026)
const CERT74="https://www.avh.asso.fr/implantations/certam/evaluations-de-produits/teleagrandisseur-govision",S6M74="https://selvasblv.com/product/braillesense-6-mini/";
U(DEV,"govision",{src:[CERT74],ha:"HIMS of Korea designed the GoVision with Visiole, its French distributor. France's Association Valentin Haüy (CERTAM) lists its release as November 2016 at €3,500, and the magnifier won a Silmo d'Or low-vision award. CERTAM's January 2017 evaluation, of firmware 1.1.0, found it a complete HD magnifier for near, distance and mirror (self) viewing. It has Android-based firmware, OCR with speech in 18 languages, and playback of documents, PDFs, images and videos from a USB stick. CERTAM's criticisms were that OCR captured only the visible screen area, was slow, and made errors at low zoom.",desc:["The GoVision is a one-piece, foldable desktop video magnifier. It combines a 24-inch widescreen LCD with a camera on a movable arm, and it has a carrying handle. Unfolded, it is about 57 cm (22.4 inches) wide and 55 cm (21.7 inches) tall, and 19 cm (7.5 inches) deep with the camera folded. It weighs 7.4 kg (about 16.3 pounds), according to CERTAM.","To set it up, you unfold the camera arm and the stand. The camera rotates through 260 degrees: it can point down at a page on the desk, out toward a distant board, or back at your face as a mirror. A rocker button on the camera itself changes zoom and colour modes and switches the LED lights on and off. The screen tilts but cannot be raised, swivelled or turned to portrait.","You control it with a wired 14-key remote whose buttons can be told apart by shape, relief, colour and symbol. The top keys set zoom, colours, contrast, and reading lines or masks. The centre keys open menus and navigate. The bottom keys freeze the image, start OCR and speech, and open the file manager for the USB stick. A headphone jack is on the top edge of the remote.","Every command is shown briefly on screen and also spoken; for example, the current zoom level is announced. Near-view magnification runs from 1.8 to 70 times. Up to five users can save their own settings.","Connections include one USB port, an HDMI input for showing a computer, tablet or phone on the screen, and a VGA connector. It runs on a 12-volt, 3-amp power adapter and takes about 35 seconds to start. In the box are the remote, an HDMI cable, headphones, a USB stick, a large-print quick-start guide and a laminated reference card, with an X-Y reading table as an option."]});
U(DEV,"bs6mini",{src:[S6M74],ha:"The BrailleSense 6 mini, which HIMS's product history dates to 2022, is the 20-cell companion to the 32-cell BrailleSense 6. Selvas BLV calls it a lightweight braille tablet and sells it for $3,995. It runs Android 12 on an eight-core processor with 6 GB of memory and 128 GB of storage. It has a Perkins-style keyboard, a 13-megapixel camera, Wi-Fi, Bluetooth 5.1, GPS, an FM radio and a user-replaceable 3,400 mAh battery. It measures 7.08 by 4.06 by 0.91 inches, weighs 0.95 pounds, and can send video to a monitor through USB-C."});
// Batch 75: Perkins 80-cell display history (AFB AccessWorld 11/4/16038, 2010 convention report; verified Oct 31, 2026)
U(DEV,"perk80",{ha:"In its report on the summer 2010 blindness conventions, AccessWorld singled out this display as one of two products that drew attention for their low cost and high value. Perkins Products was selling the 80-cell refreshable braille display for $3,900, then a remarkably low price for 80 cells. It was made by Seika, connected by USB, and was supported by all the major Windows screen readers and by Apple's VoiceOver."});
// Batch 76: consistency fixes (juliet120 yr, vrs1 date, Aicom history, HIMS source) plus Aira Horizon and IrisVision histories (verified Oct 31, 2026)
const HIMS76="https://www.himsintl.com/en/company/prd_history.php";
U(DEV,"juliet120",{yr:0});
U(DEV,"vrs1",{yr:2007,y:"Announced July 2007 and shipping from early September 2007 (AccessWorld). The second-generation Stream replaced it in February 2013.",src:["https://afb.org/aw/14/4/15708"]});
U(DEV,"u2qt",{src:[HIMS76]});
Object.assign(CO.find(x=>x.id==="aicom"),{h:"Aicom Corporation made the Accent line of speech synthesizers: the external Accent SA, which connects over a serial port, and the full-length ISA Accent PC card. The Accent was established by fall 1992, when Artic made its TransPort synthesizer able to emulate it. Users remember the Accent PC as the fastest ISA speech board. In April 2005 a JAWS mailing-list user wrote that Aicom had closed and that he had bought its last stock of Accent SAs and Accent PC cards.",src:CO.find(x=>x.id==="aicom").src.concat(["http://cd.textfiles.com/nfbfiles/newsletters/VN0892.TXT"].filter(u=>!CO.find(x=>x.id==="aicom").src.includes(u)))});
U(DEV,"aira",{src:["https://afb.org/aw/19/6/15088","https://www.afb.org/aw/18/9/15178"],ha:"Aira launched its remote sighted-agent service with Google Glass and Austrian-made camera glasses. Those glasses were tethered to an AT&T Mi-Fi hotspot and used the wearer's own phone, and their side-mounted camera gave agents about a 60-degree view. AccessWorld reviewed the Horizon glasses in June 2018. They look like sunglasses and plug directly into a dedicated Samsung phone, which serves as both the phone line and the hotspot and powers the glasses. Their camera sits above the nose and gives agents a 120-degree view. The phone carried Chloe, an early voice assistant. The reviewer called Aira the biggest game-changer for blind people since the talking and braille PC. Plans then started at $89 a month."});
U(DEV,"irisv",{src:["https://coolblindtech.com/irisvision-harnesses-the-power-of-samsung-galaxy-smartphone-with-a-samsung-gear-vr-headset/","https://afb.org/aw/february2023/irisvisions-new-addition-inspire"],ha:"IrisVision began as a low-cost low-vision aid built from a Samsung Galaxy phone mounted in a Samsung Gear VR headset. It retailed for $2,500 in the US, and Samsung's chief medical officer endorsed it. Its software remaps the camera image with algorithms for macular degeneration and retinitis pigmentosa, and adds zoom, contrast and reading modes. In 2023 AccessWorld reviewed the successor, IrisVision Inspire. Inspire moves a Galaxy S21 out of the headset onto a lanyard and connects it by cable, making the headset lighter, and adds voice commands, offline OCR, and Bubble, RP and Bioptic modes."});
// Batch 77: OpenBook year and history (AFB AccessWorld 2/6/15000; AFB Fruchterman interview; NFB Braille Monitor Feb 2001) (verified Oct 31, 2026)
U(DEV,"openbook",{yr:1989,y:"1989 (Arkenstone; AccessWorld)",src:["https://afb.org/aw/2/6/15000","https://afb.org/blindness-and-low-vision/using-technology/interviews-technology-pioneers/jim-fruchterman/part-3-4","https://nfb.org/images/nfb/publications/bm/bm01/bm0102/bm010210.htm"],ha:"Jim Fruchterman founded Arkenstone in February 1989. AccessWorld reports that it introduced OPENBook reading software that year and sold about 35,000 systems over the next decade. A complete system, with computer, scanner and software, cost under $5,000, at a time when an earlier reading system had cost an end user $50,000. Arkenstone also sold OpenBook as a dedicated reading machine: a PC in a special case with an HP scanner and a large keypad designed to pass a 'knuckle test' for seniors. As OCR moved off coprocessor cards and into software, Fruchterman says OpenBook became the first talking Windows application for blind people, ahead of the screen readers. After Freedom Scientific acquired Arkenstone's holdings in 2000, the NFB's Braille Monitor compared An Open Book Ruby Edition with the Kurzweil 1000. It reviewed the public beta of version 5.0, which Freedom Scientific released that fall."});
// Batch 78: Index V5 line description (Index V5 user manual, February 2020; IPD price sheet, February 2025) (verified Oct 31, 2026)
U(DEV,"idxv5",{src:["https://sensorysolutions.co.za/wp-content/uploads/2022/11/Index-V5-manual-eng-2020-Feb.pdf","https://ipd.gmbh/wp-content/uploads/2025/07/Index-Brailledrucker-2025-02.pdf"],desc:["The V5 line includes three main embossers. The Basic-D is a low desktop tractor-feed unit, 52 by 26 by 13 cm (about 20.5 by 10.2 by 5.1 inches), weighing 7.6 kg (about 16.8 pounds). The Everest-D is a taller desktop sheet-fed unit, 56 by 18 by 45 cm, weighing 12 kg. The BrailleBox is a floor-standing production cabinet, 56 by 72 by 90 cm, weighing 68.2 kg. These figures come from German dealer IPD.","All V5 models share the same control panel. Its general keys are ON, OFF, FEED, DOOR (BrailleBox only) and HELP. Its menu keys are MENU, four arrow keys and OK. Its number keys are 1, 10 and CHS. Text on the panel is backlit and lights up to show Bluetooth, Wi-Fi and network status, translation, available updates, paper jams and errors. A built-in speaker gives speech feedback, and pressing HELP explains what a lit indicator means.","The Basic-D has a lid over its print area and left and right paper tractors with a tractor-release lever for fan-fold paper. Optical sensors detect the paper edge and movement. It has a transport lock and holder for shipping, and ventilation inlets and outlets. The Everest-D instead has a sheet feeder with a switch to open and close it, left and right margin guides with locking levers, card and sheet selectors, pick-up rollers, and guides that steady the embossed sheets as they come out.","On the Basic-D and Everest-D, the connectors are a 48-volt DC power input, a Wi-Fi and Bluetooth antenna, a USB 2.0 device port for a computer, a 100-megabit network port, and a USB host port for a memory stick. The BrailleBox takes mains power directly through a fused inlet and has the same data connections.","The BrailleBox has a front service door, a paper tray, and a braille tray with a glass cover and a stack guide. Inside are three embossing heads (bottom, middle and top), and sensors detect paper going in and coming out. Its DOOR key opens and closes the braille tray, and indicators light if the stack gets too high or a tray or door is left open. IPD rates the BrailleBox at about 60 dB(A) and the Basic-D and Everest-D at about 80 dB(A)."]});
// Batch 79: Prodigi (AFB 15/12/15614, Dec 2014), Connect 12 (AFB 17/5/15336, May 2016), Traveller HD (Optelec product page and data sheet; AFB 5/4/14722) (verified Oct 31, 2026)
const PD79="https://afb.org/aw/15/12/15614",PC79="https://afb.org/aw/17/5/15336",TH79=["https://us.optelec.com/products/optelec-traveller-hd/","https://us.optelec.com/download/files/Optelec+Traveller+HD+Data+sheet.pdf","https://afb.org/aw/5/4/14722"];
U(DEV,"prodigi",{src:[PD79],ha:"Prodigi is a line of electronic magnifiers that HumanWare built around a customized Android tablet. It came as the Prodigi Desktop, a fixed base with a 20- or 24-inch monitor, and the Prodigi Duo, which adds a removable 5-inch tablet that also works as a handheld magnifier. In December 2014 AccessWorld called the Duo one of the most sophisticated electronic magnifiers on the market. The reviewer praised its full-page OCR, which HumanWare calls Diamond Edge Text, its speech, and its pinch-to-zoom gestures. The handheld tablet was weaker: the image blurred whenever it moved. OCR took about 10 seconds a page and struggled with faint or decorative fonts. HumanWare replied that fixes were coming, including an accessible Wi-Fi setup screen.",desc:["The Prodigi Duo is a desktop video magnifier with a black and silver base and a removable handheld tablet. The base takes up about 21 inches (53 cm) of depth and 14 inches (36 cm) of width on the desk, so it may not fit on small desks or under an overhead hutch.","A 20- or 24-inch LCD monitor sits on an arm above the base. The arm raises it through about 5 inches, from 17.5 to 22.5 inches above the desk, and the monitor also tilts forward and back and swivels from side to side. The monitor is not a touchscreen.","The Prodigi tablet docks in the base, where two latches hold it; you push them apart to release it. It has a 5-inch touchscreen and Plus and Minus buttons on its side. The Minus button is above the Plus button, the reverse of most phones, which the reviewer found confusing. A small folding reading stand and a carrying case come with it.","At the front centre of the base is a 3.5-inch touchpad for pinch zoom, panning and swipe gestures. The Read button is to its left, and the Plus and Minus magnification buttons are on the right side of the base. The reviewer suggested making these buttons larger and more raised so they are easier to find by touch. Two USB ports on the side of the base take a memory stick for software updates.","Because the camera sees the whole page at once, no sliding X-Y reading table is needed. The tablet charges in the dock or with a USB cable. AccessWorld noted that the cable's plug had no high-contrast marking to show which way up it goes; HumanWare replied that it carries a tactile marker."]});
U(DEV,"connect12",{src:[PC79],ha:"HumanWare's Prodigi Connect 12 combined a 12.2-inch Samsung Galaxy Note Pro tablet with a folding reading stand and, for $300 more, a wireless Sony camera for distance viewing. AccessWorld reviewed it in May 2016. Unlike magnifiers that lock users out of Android, it gave full access to Android 5.0 and the Google Play Store. Alongside that it ran HumanWare's magnification and OCR apps, and apps for Bookshare, BARD, Dropbox and classroom smart boards. The reviewer called it a video magnifier for power users. The weakness was full-page scanning, which required turning the page sideways and was hard to use.",desc:["This description is of the first-generation Prodigi Connect 12 that AccessWorld reviewed in 2016. The tablet has a 12.2-inch screen, and the whole kit weighs under 2 pounds (about 0.9 kg). It packs into a standard laptop bag with a shoulder strap and handles.","The folding reading stand has a base about 12 by 16 inches, with two hinged legs joined at the back. The tablet clamps screen-up onto a hinged platform that tilts. With the legs straight, the tablet sits 8 inches above the desk.","The tablet's 8-megapixel camera with LED light looks down through an opening in the platform. It sits at the edge of the tablet nearest you, so you may need to slide your reading material or adjust the stand to bring the top of a page into view.","In magnifier mode, a strip of large, bright on-screen buttons fills the bottom quarter of the screen for zoom, capture, light and settings. You can also pinch to zoom, or swipe vertically along the right edge to switch between positive and negative contrast.","The optional Sony distance camera is small and round, about the size of an SLR lens. It clips onto the stand or a table with a flexible mount, swivels (it can even turn to face you), and has its own zoom rocker. The tablet has a microSD slot, Wi-Fi, Bluetooth and GPS, and HumanWare rated its battery at up to 12 hours."]});
U(DEV,"traveller",{src:TH79,ha:"Optelec's original Traveller, made by its Dutch parent the Tieman Group, was a hinged portable CCTV. AccessWorld rated it 4 out of 5 in 2004: good for labels, single sheets and signatures, but hard to use on narrow books and for long writing. The Traveller HD replaced it with a 13.3-inch widescreen, a 1080p camera, stepless magnification from 2.4 to 30 times, and storage for up to 1,000 images. Optelec's 'Slide & Read' design lets you glide the screen along a line of text to read more fluently, which it says helps people who find it hard to keep a steady hand.",desc:["The Traveller HD is a portable video magnifier about the size of a large laptop. Optelec's data sheet gives it as 14.4 by 9.5 by 1.9 inches (36.5 by 24 by 4.9 cm) and 4.3 pounds (about 1.95 kg).","Its 13.3-inch widescreen display sits on a base that rests on the page. Instead of moving the paper, you slide the screen across a line of text using its handles. Optelec calls this 'Slide & Read'.","A 1080p high-definition camera underneath looks at the page. It magnifies smoothly from 2.4 to 30 times and offers a colour photo mode plus 16 high-contrast reading modes, up to four of which you can set as favourites.","It runs from a rechargeable battery with no cables while you read, so you can use it at a table, in an armchair or in bed. Optelec's data sheet gives about 2 hours of use per charge and 4 hours to recharge; its product page gives 3 hours of use and 6 hours to charge.","In the box are a protective bag, a power cord and adapter with four plug adapters for different countries, a screen-cleaning cloth and the instruction manual. The magnifier can store up to 1,000 captured images."]});
// Batch 80: TOPAZ history and description (Freedom Scientific press release, Dec 8, 2005; TOPAZ User's Guide, 2013) (verified Oct 31, 2026)
const TPR80="https://www2.freedomscientific.com/fs_news/PressRoom/en/2005/nr_LowVision-Topaz_12-8-2005.asp",TUG80="https://www.freedomscientific.com/Content/Documents/Manuals/TOPAZ/TOPAZ-Users-Guide.pdf";
U(DEV,"topaz",{src:[TPR80,TUG80],ha:"Freedom Scientific announced TOPAZ on December 8, 2005 as its first line of video magnifiers, in five models. A large illuminated work area under the camera was meant for hobbies such as sewing and painting as well as for reading bills, phone books and prescription labels. Each model had a sliding table and 16 magnification levels. President Lee Hamilton presented TOPAZ as a natural extension of the company's MAGic screen magnifier and SARA reading machine. Vice President Brad Davis linked it to the design-for-manufacturability approach that, a year earlier, had let the company sell its Focus braille displays at 40 percent below the prices then current. TOPAZ later grew into a family that includes the TOPAZ HD, XL HD, EZ HD and OCR models.",desc:["This description follows Freedom Scientific's 2013 TOPAZ user's guide. TOPAZ is a desktop video magnifier: a flat-panel monitor on an arm above a camera, which looks down at a sliding reading table. A rear post rises at the back. To carry it, wrap your forearm around the rear post and lift. Do not lift it by its two LED reading lights, which hang over the table.","The XY reading table glides left, right, forward and back, and it has repositioning grips on both sides for sliding the whole unit across the desk. A red brake locks the table: push it away from the unit to lock it. An indentation at the rear of the table cradles a pill bottle so it cannot roll.","The control panel has three coloured dials. The black Magnification dial has 16 positions, and pressing its centre freezes the picture. The yellow Brightness dial has a Find button in its centre: hold it to zoom out with crosshairs so you can find your place. The blue Color Select dial chooses colour modes, and pressing its centre draws a reading line across the screen. There is also a red Focus Lock button, and a green standby power button on the right side of the panel.","A white master power switch sits near the LED reading light on the right side of the unit. You move the monitor up and down by holding its sides, and it turns left and right once you push in the locking pin at the base of the monitor arm. Pull the pin out to lock the arm in the centre before moving the unit.","The rear panel has a modular jack for the control panel cable, the AC power connector, a power connector for the monitor, and a DVI video connector for the monitor. The guide warns against blocking the ventilation slots and asks you to lock both the monitor arm and the reading table before moving the unit."]});
// Batch 81: TOPAZ OCR history and description (TOPAZ OCR User's Guide, 2018) (verified Oct 31, 2026)
const TOU81="https://support.freedomscientific.com/content/documents/manuals/TOPAZ/TOPAZ-OCR_Users-Guide.pdf";
U(DEV,"topazocr",{src:[TOU81],ha:"TOPAZ OCR added a scanning-and-reading camera and speech to Freedom Scientific's TOPAZ desktop magnifier, which first appeared in 2005. The 2018 user's guide explains that one tap on its 24-inch touchscreen switches it from video magnifier to reading machine. An on-screen button bar then captures and processes the page and reads it aloud. A full-page view shows the reading zones, so you can tap any zone to hear it. You can add pages, save documents and photos to an SD card, and zoom into captured pictures. In magnifier mode it keeps the TOPAZ features: autofocus, 16 magnification levels, colour modes, reading lines and masks. It can also serve as a computer monitor over VGA, or connect over USB to the optional GEM image-management software.",desc:["TOPAZ OCR is a large desktop video magnifier weighing about 46 pounds (21 kg). The guide recommends getting help to lift it, either by wrapping a forearm around the rear post from behind or by holding the repositioning grips from the front.","A 24-inch touchscreen monitor sits on an adjustable arm and can be raised, lowered and angled. Below it, a camera looks down at an XY reading table 8.25 inches (21 cm) below. Two diffused lights, one on each side of the camera, light the table without glare. A separate OCR camera with its own light captures whole pages for reading.","The low-friction reading table slides a full 16 inches from left to right and has a brake to lock it. The main power switch is near the reading light on the right side, and a green standby power button is on the right side of the control panel.","The control panel has three dials: Color Select, Magnification and Brightness. The Find, Freeze Frame and Reference Line buttons sit in the centres of the dials; the Reference Line button doubles as the computer-view toggle. The red Focus Lock button is at the bottom left. You can disable the centre buttons to simplify the controls.","The rear panel has connectors for the OCR camera's power and USB, which stay connected, plus AC power, monitor power, the control-panel jack and an HDMI monitor connector, which can also drive a TV or larger monitor. It also has a 15-pin VGA input, for using TOPAZ as your computer's display, and a USB port for the GEM software."]});
// Batch 82: Merlin elite Pro (Enhanced Vision user manual, 2024) and ClearView C (Optelec press release Sep 3, 2014; ClearView C user manual) (verified Oct 31, 2026)
const MEP82="https://www.enhancedvision.com/downloads/product/merlin-elite-pro/usermanual-english.pdf",CVP82="https://www.prweb.com/releases/optelec_launches_the_clearview_c_a_new_desktop_video_magnifier_featuring_a_modern_and_groundbreaking_design/prweb12137661.htm",CVM82="https://www.ceciaa.com/media/file/file/c/l/clearview-c-notice-francais_1.pdf";
U(DEV,"merlin",{src:[MEP82],ha:"Enhanced Vision's 2024 user manual describes the Merlin elite Pro as a fully integrated desktop magnifier that combines a CCTV with OCR. You can read by listening, or by viewing text in colour or in high-contrast positive or negative modes. Its 1080p full-HD camera magnifies from 2.4 to 41 times, or up to 73 times in extended range. It stores at least 1,000 full-page OCR scans, and it carries a three-year warranty. Its detachable console cover switches between a simpler Basic mode and an Advanced mode that adds saving, a document library, OCR zone identifiers and line-by-line navigation. The introduction year was not found in the manual or on Vispero's site.",desc:["Merlin elite Pro is a desktop video magnifier with a 24-inch LCD monitor above a camera and reading area. It stands 27.75 inches (70.5 cm) tall and measures 22.75 inches (57.8 cm) wide by 20 inches (50.8 cm) deep, and it weighs 40.1 pounds (18.2 kg).","Carry it only by the recessed handles on its underside. Enhanced Vision warns against lifting it by the body, the camera housing or the monitor.","The front panel, below the screen, has the Power button, speakers, a 3.5 mm headphone jack (which mutes the speakers), a Color Mode button, and a centre button that switches between CCTV and OCR modes, with a zoom wheel around it.","A separate control console plugs into a USB port on the back. It has a large Zoom wheel around a Find button, up/down Brightness and Color Mode buttons, a Volume knob on the left side, and a Markers knob. A removable cover hides the advanced keys, such as Library and OCR navigation. With the cover on, the unit is in Basic mode; take the cover off and it switches straight to Advanced mode.","It runs from a 19-volt external power supply that plugs in at the back, at a socket labelled 19VDC. A 2-in-1 USB hub is included so you can connect a USB stick or the optional microphone, which records spoken voice tags for saved files, alongside the console. The manual gives power use as about 30 watts when on and under 5 watts in standby."]});
U(DEV,"clearview",{src:[CVP82,CVM82],ha:"Optelec U.S. introduced the ClearView C on September 3, 2014. It billed the ClearView C as the first video magnifier with a contemporary, sleek design built from high-quality materials, developed with end users. CEO Maarten Bosch said the goal was to eliminate the difficulties people had with desktop magnifiers and give a more natural reading experience. U.S. President Stephan Terwolbeck pointed to the emotional side of being diagnosed with low vision. The system is modular. Buyers choose a space-saving Compact or wide Comfort table, an HD or standard camera and a monitor size, and an optional speech module can read text aloud.",desc:["The ClearView C is a modular desktop video magnifier. A monitor and camera box sit on a C-shaped arm that rises from the back of a sliding reading table. It ships fully assembled in one box, with a handle for lifting. The arm can be set to a Compact table setup or, by loosening a black knob under a cap at the top of the arm, to a wider Comfort setup with room for crafts or large documents.","The front edge of the reading table has two wrist supports. The wireless Control Pad sits between them. Turned with the Optelec logo facing you, its top shows the basic controls. Rotated so that five rectangular buttons face you, it gives the advanced functions. It runs on batteries and is paired to the magnifier.","On the basic side, the Zoom dial is in the centre of the pad. Turning it clockwise magnifies more. A white Mode button inside the dial steps through full colour and up to four high-contrast reading modes; holding it for four seconds turns off the lights. An orange round On/Off button sits next to the dial.","Two sliders at the front of the table control how it moves. The left slider adds friction to, or locks, side-to-side movement, and the right slider does the same for forward-and-back movement. Slid to the outer edges, the table moves freely.","The master power switch is on the left side of the camera box, behind the monitor. The connections are HDMI in and out, power in and out, and a camera connection for the optional speech module. The camera takes about 5 seconds to start after switching on."]});
// Batch 83: Eyedaptic EYE series history and description (eyedaptic.com/eye6, fetched Oct 31, 2026)
const EY83="https://eyedaptic.com/eye6/";
U(DEV,"eye",{src:[EY83],h:"Eyedaptic's EYE series of AMD eyewear ran from EYE1 in 2019 to EYE6 in August 2024 (see the entry's dates). According to Eyedaptic's EYE6 page, the EYE5 was its lightest and most comfortable model: under 3 ounces, with 1080p full-HD displays and about 3 hours of battery life. The EYE6 keeps all of the EYE5's features and adds Ivy, a generative-AI visual assistant built on OpenAI's large language models. Ivy offers conversational text and image analysis in 99 languages, including translation, and can help with reading, finding objects and describing rooms. Ivy can be added to existing EYE5 glasses with a remote upgrade, alongside Eyedaptic's patented simulated-natural-vision enhancement software.",desc:["The Eyedaptic EYE6 is a pair of head-worn smart glasses for people with low vision, especially age-related macular degeneration. They are styled to look like everyday eyewear. Eyedaptic says they weigh under 3 ounces, light enough to wear all day.","A small built-in camera on the frame captures the scene in front of you. The glasses enhance it and show it on two 1080p full-HD displays, one in front of each eye. Eyedaptic's simulated-natural-vision software adapts the image to make the most of your remaining vision.","The glasses are controlled hands-free by voice, so you do not need to find buttons for most tasks. Eyedaptic's page does not describe the physical controls or ports in detail.","The built-in battery lasts about 3 hours of use, according to the EYE5 specifications that the EYE6 shares.","The visual assistant, Ivy, answers questions spoken aloud through the glasses. It can read text, describe a room, find objects and translate between languages, in 99 languages. EYE5 owners can add the same features with a remote software upgrade."]});
// Batch 84: Index V3, 4X4 PRO, 4Waves PRO and V4 descriptions (Index manual 2005-04-18 via CECIAA; Index quick-start guide 2007 via InsideVision; Index V4 manual 2015; CECITECH 4Waves page) (verified Oct 31, 2026)
const IFR84="https://www.ceciaa.com/media/file/file/telecharger-le-manuel-d-utilisation-pour-les-imprimantes-braille-index-basic-d-v4-everest-v4-et-braillebox.pdf",IQS84="https://www.insidevision.fr/supports/guide-demarrage-rapide-index.pdf",IV484="https://www.edvisionservices.org/Manuals/Basic-D_V4.pdf",I4W84="https://cecitech.com/en/?product=index-4-waves-pro-braille-printer";
U(DEV,"idxv3",{src:[IFR84,IQS84],desc:["The V3 platform covered four Index embossers: the Basic-S (single-sided) and Basic-D (double-sided), which both use tractor-fed fanfold paper, the Everest, which uses cut sheets, and the 4X4 PRO. Index's 2005 manual calls the Basics the most portable embossers it made, light and compact enough to carry to a meeting. The Basic-D embosses interpoint braille twice as fast as the Basic-S.","According to the UK service note in this entry's history, the cases are black with a red lid and yellow buttons. The control panel keys are labelled in both print and braille. Speech feedback announces each setting, so a blind user can run and configure the embosser without sighted help.","The keys include On Line, Off Line, Form Feed, Help, Setup, Item, Value, Normal, Reformatted and Z-folding. Pressing two keys within half a second gives extra commands. For example, Help speaks the model, firmware version and active setup. Help with Value speaks the network IP address, and Help with On Line embosses a hammer test page.","The Everest's sheet feeder holds 70 sheets of braille paper. You set the width by sliding and locking the guides, and a sensor measures the page length automatically. Index rated mis-feeds at under 5 per 1,000 sheets on good paper. The Everest embosses anything from copy paper to card stock.","The connections are USB, 100-megabit TCP/IP networking with DHCP, a 9-pin serial port and an IEEE 1284 parallel port, with escape-sequence control under MS-DOS. Graphics can be embossed at 0.5 mm resolution using WinBraille 4. The warranty was 2 years or 200,000 pages, with replaceable embossing heads, boards and sheet feeders. Index sold an acoustic cabinet for the Basic (42 kg) and an acoustic hood for the Everest (19.3 kg)."]});
U(DEV,"idx4x4",{src:[IFR84,IQS84],desc:["The 4X4 PRO is Index's embosser for producing braille books and magazines. Index's 2005 manual calls it by far the best-selling embosser in its class, used for years by large braille production centres worldwide.","Its special feature is saddle-stitch magazine format. It embosses double-sided on A3 sheets (420 by 297 mm) and handles the page ordering itself, so the output only needs folding and stapling. The default layout is 29 lines of 35 characters per page.","It shares the Everest's cut-sheet feeder design, which takes ordinary heavy paper available locally rather than imported fanfold braille paper. The Z-folding key switches it to magazine format, and pressing Form Feed twice measures and sets the paper length.","Like the other V3 embossers, it has a control panel with print-and-braille labelled keys and spoken feedback. The connections are USB, network, serial and parallel. It cannot emboss the graphical-letters information page that the other models can, and Index's IbPrint utility does not support tactile graphics on it.","Index sold an Acoustic Cabinet 4X4 PRO (part 1262) to reduce noise. The cabinet itself measures 69 by 51 by 152 cm and weighs 43 kg. The size and weight of the embosser alone were not given in the manuals found."]});
U(DEV,"idx4waves",{src:[I4W84,IFR84],desc:["The 4Waves PRO is a floor-standing, high-volume production embosser for tractor-fed paper. It measures 169 by 70 by 114 cm and weighs 195 kg; the shipping weight is 264 kg, on a pallet. Index called it the first embosser built on a multi-printer design.","Inside are four identical embossing modules working together, which give up to 1,000 pages per hour. Each module measures 58 by 23 by 19 cm and weighs 8.7 kg. A fifth service module comes with it. When a module needs maintenance, you swap in the spare in a few minutes without tools.","The machine adapts automatically to running on three, two or one modules, so it keeps embossing while at least one module works. At power-on it confirms each module by speech: check module, one wave, two wave, three wave, four wave, ready.","Like other Index embossers, it has a speech-equipped control panel with print-and-braille keys. Unlike the other V3 models, it has no 9-pin serial port; it connects by USB, network and parallel. It can restart a job at the point where it stopped after a paper jam.","It embosses high-resolution tactile graphics anywhere in a document using the WinBraille editor. Its warranty was 2 years or 5,000,000 pages, compared with 200,000 for Index's smaller embossers."]});
U(DEV,"idxv4",{src:[IV484],desc:["The V4 platform includes the Basic-D (tractor-fed), the Everest-D (cut sheets) and the BrailleBox, a production embosser with three embossing heads. According to the entry's history, the Basic-D V4 has a white case with a black lid. The Basic-D and Everest-D run from an external 48-volt switched-mode power supply.","On the Basic-D, the control panel and lid are on top, with left and right tractors underneath. Optical sensors detect the paper edge and paper jams. A transport lock is stored in holders on the back plate. The Everest-D has a top sheet feeder with a lock, left and right margin guides with locking levers, card/sheet selectors and pick-up rollers, plus an adjustable front bottom profile and guides that set the angle of the ejected paper.","The control panel has On, Off, Feed, Help and Menu keys, up, down and left arrows, OK, and number keys 1 and 10, plus a CHS key that switches between increasing and decreasing a value. Spoken feedback, in a local language or English, announces each function. Three LEDs show green for power OK, yellow for online and red for menu active.","On the back of the Basic-D and Everest-D are the 48-volt power input and a reset button (hold 3 seconds for factory settings). There are also a service serial port, a serial port, a USB 2.0 port, a 100-megabit network port with an LED, and a headphone jack. Status LEDs between the USB and service ports show paper-edge and paper-movement sensing.","The BrailleBox takes 90 to 250 volts directly and adds a paper tray, a braille output tray, a service door and LED indicators. It embosses A3, tabloid and similar sheets in newspaper format. The Basic-D takes fanfold paper 1 to 17 inches long and 4 to 13 inches wide, and the Everest-D takes cut sheets from 120 to 590 mm long. Index gives a 2-year parts warranty."]});
// Batch 85: NFB/IBTCB "Braille Technology Evaluation" (1994, APH/NIDRR grant H133A20022-93; Duxbury library copy) — Everest V1, Index Basic V1, Thiel Beta/X3, Alva Braille Terminal, Braillex IB80, Navigator (verified Oct 31, 2026)
const NFB94="https://www.duxburysystems.org/downloads/library/history/00-nfb1994-tech-eval.pdf";
U(DEV,"everestd",{src:[NFB94],desc:["The first Everest, as evaluated by the National Federation of the Blind's International Braille and Technology Center in 1994, was an unusual interpoint (double-sided) embosser: wide and tall but not very deep. It measured 20 inches wide by 6.75 inches deep by 25 inches high and weighed 25 pounds. TeleSensory imported it to the US at $5,995.","Single sheets of paper sit in a feeder on top of the unit. The feeder holds 100 to 150 sheets, depending on paper thickness. The paper travels down through the printer and drops out of the bottom into a catch basket.","Control buttons run along the front panel. They have braille markings, which the panel found oddly spaced, and a built-in speech synthesizer announces each button as it is pressed. The panel found the speech somewhat hard to understand.","The power cord, power switch and parallel cable connect at the back, on one of the legs or supports. A stripped-down Duxbury braille translator was built into ROM, and a WordPerfect driver let you print directly from that program.","The importer rated it at 100 characters per second, giving 26 lines of 42 cells. The panel judged the braille quality very good but reported paper jams on roughly one sheet in three. TeleSensory said this was not typical."]});
U(DEV,"idxbluebar",{src:[NFB94],desc:["This description comes from the National Federation of the Blind's 1994 evaluation of the Index Basic, which was then the first-generation (V1) Basic sold in the US. V1 machines are identified by the blue or red bar on the steel case, so it fits this entry. The 1994 report does not say which bar colour its unit had.","The Basic was a single-sided, tractor-fed embosser and somewhat lighter and smaller than its competitors. It measured 20 inches wide by 11.75 inches deep by 7.5 inches high and weighed 14 pounds.","Paper feeds from the front to the back across the top of the unit. There are four switches and a knob for adjusting impression depth on the top plate, in the rear left corner.","On the back are a serial port, a parallel port, the on/off switch and the power cord.","It embossed 50 characters per second, giving 26 lines of 40 cells, and cost $2,995 from the dealer Young Opportunities. The panel found it quieter than most embossers and its braille quite readable, though not the best. US service and importer arrangements were uncertain at the time."]});
U(DEV,"thielbx3",{src:[NFB94],ha:"The National Federation of the Blind's 1994 Braille Technology Evaluation said the Beta/X3 had been available since the mid-1980s and was generally considered very reliable. The NFB's International Braille and Technology Center owned several and called them real workhorses: expensive to repair, but they keep going, and relatively quiet. Blazie Engineering of Forest Hill, Maryland, imported it for about $12,000. It embossed 130 characters per second, with 26 lines of 42 cells. The braille quality was good, but setup, like that of all Thiel printers, could be confusing.",desc:["The Thiel Beta/X3 is a heavy single-sided braille embosser from Thiel GmbH of Germany. It measures 16.25 inches wide by 22.25 inches deep by 5.75 inches high and weighs 84 pounds.","It has a metal lid and a carrying handle, so it can be moved, but the NFB evaluators stressed how heavy it is. Paper feeds in from the front and passes across the top of the printer, drawn by pull-type tractors.","Six buttons and a switch on the right front of the top surface control the printer. Setup is a series of yes/no questions shown in braille, which you answer by pressing different buttons. The evaluators found some questions confusing until you got used to them.","A cut-out on the right side holds the input cable connector and the power cord. The on/off switch there is a key that you turn.","It connects to a computer only through a serial port; there is no parallel connection. It embosses 130 characters per second, 26 lines of 42 cells, and is relatively quiet for an embosser."]});
U(DEV,"abt3",{src:[NFB94],y:"By 1994 (reviewed in the NFB's 1994 Braille Technology Evaluation; exact release year not found)",yr:1994,ha:"The National Federation of the Blind's 1994 Braille Technology Evaluation reviewed the ALVA Braille Terminal (ABT), made by ALVA in the Netherlands and imported by HumanWare of Loomis, California. It cost $14,495 for the 83-cell model and $8,995 for the 43-cell model. The panel called it an all-round good choice for most users: simple, effective and easy to install. Its memory-resident control software caused no problems with other programs. The braille was a little mushy but acceptably readable. The report does not give the ABT-3 series model numbers, so this is the best available record of the ABT as sold at that time.",desc:["The ALVA Braille Terminal is a flat, low, rectangular refreshable braille display in a plastic housing. The 83-cell model reviewed in 1994 measures 23.5 inches wide by 11 inches deep by 1 inch high and weighs 11 pounds 6 ounces. A 43-cell version was also sold.","The braille display runs along the top front edge: 80 cells plus three status cells on the left. The first two status cells show which screen line is displayed, and the third shows attribute information.","Above the cells is a row of 80 dots, one per cell, for cursor routing. Pressing the dot above a cell moves the application's cursor there, where the program allows it; for example, in WordPerfect's editing screen but not at the DOS prompt.","Seven buttons run along the front edge: three round ones on the left, then two short and two long bars, with the long bars in the middle. From left to right they are Program, Home, Cursor, Line Up, Line Down, Line Down and Line Up. The up and down bars can also move the system cursor.","The power cord, on/off switch and input and output connectors are on the back edge. The ABT connects to the computer's parallel port and has its own parallel port to replace the one it occupies, so a printer still works normally."]});
U(DEV,"braillex",{src:[NFB94],desc:["This description is of the BRAILLEX IB80, the model the National Federation of the Blind evaluated in 1994. A 40-cell 4040 was also sold. The IB80 measures 29 inches wide by 11.5 inches deep by 1.25 inches high and weighs 20 pounds 2 ounces. It has a heavy, solid metal case and came with a hard suitcase-style carrying case. In 1994 it cost $15,000 and the 4040 $10,000, through ATR Computers.","The braille display sits on top near the front edge: 80 cells plus four status cells on the left. Behind it are 40 cursor-routing buttons, one for every two cells. Press once to route to the left cell, twice for the right.","On the left end of the top are eight buttons in two vertical rows of four, numbered like braille dots. To the right of the display are five buttons forming the four arrow keys and a Home key. A vertical row of four buttons on the top plate gives three function keys and a Shift key.","Along the front edge are two long bars to move the display up and down, a Home key between them, and two buttons at each end. Those end buttons move each half of the display when the 80 cells are split into two 40-cell banks, so one half can stay parked on part of the screen.","The IB80 is hardware-based. An interface card goes in a PC expansion slot, the PC keyboard plugs into the Braillex, and a cable runs to the PC's keyboard connector, so braille works from the moment the computer starts. The on/off switch is on the left side, and the power cord and connectors are on the back."]});
U(DEV,"navigator",{src:[NFB94],desc:["The TeleSensory Navigator is a low, flat, rectangular refreshable braille display. It came in 20-cell six-dot, 40-cell six- or eight-dot, and 80-cell eight-dot models, priced from $4,500 to $16,000 in 1994. Some models could run on batteries.","The 40-cell six-dot model that the NFB evaluated measures 12 inches wide by 12.5 inches deep by 1.75 inches high and weighs 5 pounds 11 ounces.","Ten buttons on the front panel form two mirror-image groups of five. Each group has two long horizontal up and down buttons in the middle, a vertical left and right button on either side, and a smaller button to the side. The smaller buttons act as Enter, link or unlink the display from the cursor, or start View2, the real-time braille translator. Mostly, the right-hand group moves the reading window and the left-hand group moves the system cursor.","Between the two button groups is a jack like an RJ-11 phone jack for connecting a BrailleMate. Its braille keyboard can then enter six- or eight-dot braille, and the display can be split between the BrailleMate and the computer.","On the back are the input and output connectors, an on/off switch and the power cord. It connects to the PC through a serial port and runs TeleSensory's Gateway software, with a TRACK utility for following alternate cursors and the VBPC VersaBraille emulator."]});
// Batch 86: PowerBraille 40/80 (The PowerBraille User's Guide, Freedom Scientific legacy manual) and Focus 44/70/84 (Focus User's Guide, 2002) (verified Oct 31, 2026)
const PBM86="https://support.freedomscientific.com/Content/Documents/Manuals/Legacy/PowerBraille/PB_User_Manual.pdf",FOM86="https://support.freedomscientific.com/Content/Documents/Manuals/Legacy/Focus/440025-001Focus%20Manual.pdf";
U(DEV,"pb40",{src:[PBM86],desc:["The PowerBraille 40 is a 40-cell refreshable braille display measuring 14 inches wide by 13 inches deep by 1.5 inches tall (35.5 by 33 by 3.8 cm). It weighs 5 pounds (2.25 kg). It is slim enough to slide under a notebook computer or desktop keyboard, and two Velcro strips on its large flat top hold the computer or keyboard in place.","Near the front of the top is a slightly raised ridge. In front of the ridge is a row of tiny cursor-routing buttons, then the 40 braille cells, then a tactile ruler with an indicator dot below each cell. A small square button near each end of the display, slightly to the rear, moves the display backward (left) or forward (right) through the screen.","On the front edge, the Left Rocker on the far left moves the system cursor up and down, and the Right Rocker on the far right moves the braille display up and down. In between, a convex button on the left acts as Enter in DOS programs, and a concave button on the right links and unlinks the display from the cursor. The cells drop after 4 minutes idle to save power, and any key wakes them.","On the rear edge are a rocker on/off switch (right side on), a 2.5 mm DC-in jack, and a 9-pin male DTE serial port for a Braille 'n Speak or second computer. There is also a 25-pin female pass-through port for a printer, a 25-pin male parallel port, and a 9-pin female DCE serial port, which is the preferred connection to the PC at 9600 baud.","The PowerBraille 40 runs on rechargeable C-size nickel-cadmium batteries behind an access panel on the bottom. The product label there gives the serial number in both print and braille. At power-on it shows its name, version and battery use."]});
U(DEV,"pb80",{src:[PBM86],desc:["The PowerBraille 80 is the large desktop model of the line. The manual notes it really has 81 cells. It shares its case with the 65-cell PowerBraille 65: 24 inches wide by 11.5 inches deep by 1.5 inches tall (61 by 29 by 3.8 cm), weighing 10 pounds (4.5 kg). A recessed rubber pad on the rear of the top stops a notebook or keyboard from sliding.","Near the front of the top, in front of a raised ridge, are four bars for moving the display. With ScreenPower software, bar 1 moves backward and bars 2 to 4 move forward. A pair of cursor buttons on each side of the bars moves the application's cursor. Next come the cursor-routing buttons, the braille cells, and a tactile ruler with an indicator dot below each cell.","On the front edge, from left to right: Switch 1 selects six- or eight-dot braille; Switch 2 shows screen attribute codes; the Left Rocker moves the system cursor; a convex button acts as Enter; a concave button links and unlinks the display; and the Right Rocker moves the display up and down.","The rear edge has a power switch, DC-in jack, speaker out and two speaker-in jacks for sharing speech synthesizers, and two pairs of keyboard in and out jacks. There are also a 9-pin DTE serial port (Serial B), a 9-pin DCE serial port (Serial A, the preferred PC connection), a 25-pin parallel port and a 25-pin printer pass-through.","Unlike the PowerBraille 40, the 65 and 80 run only on mains power through the AC adapter. Many control functions can be reassigned in ScreenPower, TeleSensory's screen reader for the line."]});
U(DEV,"focus44",{src:[FOM86],desc:["The first-generation Focus displays came in 44-, 70- and 84-cell sizes. The braille cells are placed near the back of the unit so that they are as close as possible to the computer keyboard. A removable handle doubles as a keyboard stand and height adjuster for a keyboard or laptop.","A cursor-routing key sits above each braille cell. Between the cells and the back of the unit are two advance bars, with two programmable General Display Buttons between them. The status cells can be set to either end of the display, and VariBraille adjusts the firmness of the dots.","In front of the cells are eight Perkins-style braille keys for entering commands. At each end is a Whiz Wheel, which you roll to move through files, lists and menus and press to switch between line, sentence and paragraph. Along the front edge are Left Shift, Spacebar and Right Shift.","The left end has a 9-pin serial port, an AC adapter jack and a USB port. The right end has a second USB port (only one can be used at a time) and four audio jacks: speaker and headphone outputs at the front and two audio inputs behind them.","Over USB the display draws power from the computer, but over serial it needs the AC adapter. It shipped with a keyboard accessory, USB and serial cables, a power supply, a fitted case, and print and braille manuals, with a 30-month warranty. It works with JAWS 4.02 and later."]});
// Batch 87: ALVA 544 Satellite Traveller (Optelec user manual via Manualzz) and ALVA BC640/BC680 (Optelec user manual V1.2, (c) 2007) (verified Oct 31, 2026)
const SAT87="https://manualzz.com/doc/25948963/optelec-satellite-traveller-544-braille-display-user-manual",BC87="https://chaic.co.il/wp-content/uploads/2020/10/Optelec_ALVA_BC640_680_User_Manua_ENG_V1_2.pdf";
U(DEV,"sat544",{src:[SAT87],ha:"Optelec's user manual calls the ALVA 544 Satellite Traveller a fifth-generation braille display. It could run on USB power or an external adapter, had both serial and USB ports and Touch Cursor and Double Touch Cursor buttons, and came in a new thin, light housing. The manual targets Windows 98, 2000 and XP, as well as MS-DOS. One of its front-key layouts copies the classic ABT3 and Delphi arrangement, and it can emulate the PROG key for compatibility with ALVA's DOS software, linking it to the earlier ALVA Braille Terminals. The display followed an 'Open Standard' approach so that it would work with most screen readers.",desc:["The ALVA 544 Satellite Traveller is a 44-cell refreshable braille display. The cells run along the front of a flat surface, and behind them is space to rest a keyboard or laptop; two keyboard supports and a carrying bag come in the box.","Above each braille cell are two small buttons: a Touch Cursor in the lower row and a Double Touch Cursor in the upper row. These route the cursor, click the mouse or give information about that cell. Three status cells, plus a blank separator, can be placed at the left or right end or turned off.","On each side, just below the cells, is a six-key Satellite keypad: four keys in a circle with two larger keys beside them. By default the right keypad gives Windows commands (Back Tab, Forward Tab and the Left, Up, Down and Right pads), and the left keypad gives screen-reader functions (Back Ear, Forward Ear and the West, North, South and East pads). The two can be swapped.","Along the front are six keys: a round Home key on the left, rectangular Left, Up, Down and Right keys, and a round Cursor key on the right. Pressing Back Ear, South Pad and Forward Ear together opens a built-in braille menu for volume, sleep time, dot firmness (1 to 5), status cells and seven saved setting sets.","At the back, partly covered by an overhanging edge with tactile markings underneath, are (from left to right) the on/off switch, a 9-pin serial port, a USB port and the power-adapter socket. It runs from USB power when connected directly to a PC. Over serial it needs the adapter, because it has no battery. It can be connected to two computers at once, one by USB and one by serial."]});
U(DEV,"bc640",{src:[BC87],y:"By 2007 (Optelec's BC640/BC680 user manual is copyright 2007; a user blog reviewed the BC640 in April 2010)",yr:2007,ha:"Optelec's user manual, copyright 2007, introduces the ALVA Braille Controller 6 series as the first series of wireless braille controllers to combine classic braille display access with advanced functions. The series offered Bluetooth and USB in an ultra-compact design for computers, PDAs and smartphones. There were two models: the 40-cell BC640, which could take an optional Braille Audio Feature Pack with a braille keyboard and stereo speakers, and the 80-cell BC680, with a USB keyboard connection. Battery life was about 15 hours for the BC640, 40 hours with the Feature Pack, and 10 hours for the BC680.",desc:["The ALVA BC640 is a compact 40-cell braille display. The cells sit at the back of its flat top, with a cursor-routing key in front of each cell. The 80-cell BC680 shares the same design.","On each side of the braille line are two eTouch keys for panning and screen-reader functions. The top keys are marked with two vertical lines and the bottom keys with one horizontal line.","In the middle, in front of the routing keys, is the Smartpad of nine keys: two rectangular keys on the left, a five-way navigation key (Left, Up, Down, Right and a dot-marked Middle), and two rectangular keys on the right. Along the front edge are five thumb keys: four large ones for left, right, up and down, and a smaller middle one that returns to the cursor.","The power switch is a rectangular push button on the right side, and it beeps when switched on. The left side holds, from front to back, the power socket, a mini-USB port and a feature connector. A connector at the back attaches the Braille Audio Feature Pack.","The Feature Pack clips on in front and adds an eight-key braille keyboard with a space bar, Ctrl, Windows, Enter and Alt keys, stereo speakers, headphone and microphone jacks, and a volume and mute control. The display connects by USB or Bluetooth (a Class 1 USB dongle was included) and runs on an internal battery when not powered over USB."]});
// Batch 88: ViewPlus Emprint/SpotDot (VP SpotDot User Manual June 2016), VP Max (ViewPlus Desktop Manual 2016-06-13), Tiger Advantage (NFB Braille Monitor Oct 2001; OSU news) (verified Oct 31, 2026)
const SD88="https://viewplus.com/downloads/docs/manuals/VPSpotDotUserManual_2016Jun.pdf",VPM88="https://viewplus.com/downloads/docs/manuals/VPCubJrCubMaxUSB_UM_EN_20160613.pdf",BM88="https://nfb.org/images/nfb/publications/bm/bm01/bm0110/bm011007.htm",OSU88="https://news.oregonstate.edu/news/osu-industry-collaborate-technology-aid-blind";
U(DEV,"emprint",{src:[SD88],desc:["The Emprint, later renamed VP SpotDot, is a desktop braille and tactile-graphics embosser that also prints colour ink, built around an HP inkjet mechanism. ViewPlus calls it the first full-colour ink braille and tactile-graphics printer. It measures 24 inches wide by 7 inches high and 17 inches deep including its extension and input tray (610 by 178 by 432 mm), and weighs 24.4 pounds (11 kg).","Paper sits in an input tray at the front: up to 150 sheets of copy paper, or 60 sheets of braille paper or card stock, or up to 20 envelopes, labels or banners. A fold-out output tray slides onto pins above the input tray. It takes A4, US Letter, Legal and envelopes up to 9 inches wide, on media from copy paper to 110-pound card stock.","The lid on top lifts off without hooks or snaps and must be closed during printing. An HP duplexer, the rear paper-path extension, clips onto the back, released by a button on each side.","It prints ink first from HP 27 (black) and HP 28 (tri-colour) cartridges, waits for a set drying time, then embosses braille and graphics at 20 dots per inch with ViewPlus's patented roller-die mechanism. A calibration aligns the ink with the embossed dots.","It connects to the computer by a single USB port on the back. Power use is 12 watts on standby and up to 110 watts when embossing heavily. It is rated for up to 3,000 pages a month."]});
U(DEV,"vpmax",{src:[VPM88],desc:["The VP Max is ViewPlus's wide-carriage desktop tactile-graphics and braille embosser, powered by Tiger. It measures 22.5 inches wide by 13.2 inches deep by 6 inches high (572 by 335 by 152 mm) and weighs 22 pounds (about 10 kg). The smaller VP Cub and Cub Jr. share the same design at 16.8 inches wide.","It takes tractor-fed paper up to 14 inches (355 mm) wide, or single sheets, up to 0.35 mm thick. The wide paper path suits large tactile graphics as well as braille.","The operator panel has three buttons. From left to right: Cancel stops a job or clears a warning; Up Arrow loads paper or advances it to tear off, moving continuously if held; Down Arrow pulls the paper back to the ready position after tearing.","Two status lights sit beside the buttons. A green Power light glows when ready and blinks while printing, and an orange Warning light blinks when it cannot print. Distinct beep patterns signal paper out (high, low), a jam (high, low, high) and an alignment error (high, high, low), repeating every 10 seconds until you press Cancel.","It connects by USB. Tiger technology embosses graphics at high resolution with 8 dot heights for different shades, and braille dot height can be set to low, normal or high. The Tiger Software Suite lets you emboss directly from Word and other Windows programs."]});
U(DEV,"tigeradv",{src:[BM88,OSU88],desc:["The Tiger Advantage was the first ViewPlus embosser. It came from research at Oregon State University that the university patented and licensed to ViewPlus. Peter Langner invented it for his master's thesis, working with physics professor John Gardner. ViewPlus planned to sell it for about $5,000; by August 2001 the NFB listed it at $9,750.","It embossed tactile graphs, charts, maps and pictures at 20 dots per inch on tractor-fed braille paper, alongside braille text. Langner called it the first embosser that could print directly from standard Windows applications.","It came with a Windows printer driver, so you could print from any program, and with its own braille translation software. In 2001 it could not print directly from Duxbury.","The NFB's International Braille and Technology Center found it one of the quietest embossers available. Its braille quality was acceptable when the punch force was set to seven or higher.","It had a small buffer that held only about 50 braille pages of text at a time, so it suited graphics better than bulk text. On the NFB's 2001 text-only test it embossed 30.4 characters per second against a rated 35. Its physical size and weight were not found in the sources consulted."]});
// Batch 89: Braillo 200 (Braillo B200 manual Sept 1998; NFB 1994 Braille Technology Evaluation), Braillo 270 (Duxbury control file; Braillo brochure 2026), Braillo 440 SF (Braillo brochures 2020/2026) (verified Oct 31, 2026)
const B200M="https://braillo.com/wp-content/uploads/2017/09/B200-Braille-Printer-Manual-1998.pdf",NFB94b="https://www.duxburysystems.org/downloads/library/history/00-nfb1994-tech-eval.pdf",BR26="https://braillo.com/wp-content/uploads/2026/04/Braillo-Products-Brochure-2026.pdf",BR20="https://braillo.com/wp-content/uploads/2020/03/2020-All-Braillo-Braille-Printers-Brochure2.pdf",DUX270="https://duxburysystems.com/documentation/dbt14.1/Content/embossers_and_embossing/Embossers_elt_info/braillo_270.htm";
U(DEV,"braillo200",{src:[B200M,NFB94b,BR26],desc:["The Braillo 200 is a heavy production interpoint embosser that sits on a table. The NFB's 1994 evaluation called it half the price and half the speed of the floor-standing Braillo 400S, adding that the table had better be a strong one. Braillo's 1998 manual gives its weight as 145 kg and says it needs about 1.25 by 1.5 metres (4 by 5 feet) of space. The NFB measured it at 34.5 inches wide, 26 inches deep and 23 inches high, and listed its weight as 386 pounds.","Fan-fold paper feeds from a box placed at the back, opposite the operating panel. It passes between two knobs and through a slit in the paper guide, then locks into the tractor feed at the front. A FINE ADJUST button lines the paper up with a notch for the chosen sheet length.","A green switch marked ON and a red switch marked OFF power it, and a green lamp shows when it is on. A small visual display shows messages and three sheet counters: a total that cannot be reset, and Count 1 and Count 2. An audio alarm sounds when there is a problem, but the messages themselves appear only on the display.","Push buttons on the panel include COUNT1/COUNT2, DUMP BUFFER, PRINT VALUES, SCROLL, RESET COUNT, TEST PRINT (which also restarts after paper runs out), RESET PRINTER, I/O, ASCII-TABLES and LAYOUT 1 to 4. Settings are chosen by holding a button and pressing SCROLL until the value you want appears.","It embosses 6- or 8-dot braille, single- or double-sided, at 200 characters per second (about 600 pages an hour), with 10 to 42 characters per line on paper 140 to 330 mm wide and 4 to 14 inches long. It connects by parallel (Centronics) or RS-232 serial, both electrically isolated, and runs on single-phase 220 V. The NFB listed it at $37,995 in 1994."]});
U(DEV,"braillo270",{src:[BR26,DUX270,NFB94b],desc:["The Braillo 270 was the world's first double-sided (interpoint) braille embosser. Braillo introduced it in January 1980 after developing it with SINTEF, a research institute in Trondheim, Norway.","The first unit was installed at Norway's Tambartun School for the Blind in 1980 and stayed in service until the school closed in 2013.","Duxbury's embosser definition for the Braillo 270 shows that it embossed interpoint braille at up to 42 cells per line, with line widths of 27 to 42 cells. Page lengths were whole inches from 4 to 14, plus 9.5, 10.5, 11.5, 12.5 and 13.5 inches. Settings were sent by escape codes, but there was no escape code to switch between single- and double-sided printing.","The 270 evolved into the Braillo 400S. The NFB's 1994 evaluation describes the 400S as a floor-standing machine shaped like a squared-off refrigerator, with paper running from back to front and a 16-button panel. It is likely the 270 had a similar build, but no source consulted describes it directly.","The Braillo 270's own size, weight, speed and controls were not found in Braillo's or the NFB's published material, or in Duxbury's documentation."]});
U(DEV,"braillo440sf",{src:[BR20,BR26],desc:["The Braillo 440 SF was the final step in the Braillo 270, 400S, 400 SR and 440 SW line. Braillo describes it as the world's first, and at the time only, fully automated braille book production system.","Braillo's description of its workflow: send a file and pick up a finished, folded, covered and stapled book. That made on-demand braille publishing possible.","Its predecessor, the 440 SW, introduced four-page-per-sheet embossing for simpler book production. The SF added the automatic folding, covering and stapling that came after embossing.","After American Thermoform bought Braillo in 2016, the SF line was succeeded by the Braillo 650 SF2. Mechanical and electrical upgrades raised its speed by about 50 percent.","The 440 SF's size, weight and controls could not be verified. A Russian dealer's brochure that search summaries cite for them (1,500 × 1,027 × 4,060 mm; 570 kg) returned a 404 error."]});
// Batch 90: Brailliant 24/40 (original HumanWare Brailliant User Guide; BrailleNote list July 2004), ALVA MPO 5500 (ALVA user manual 3000700 via Manualzz), Handy Tech Braille Wave (user manual v4.2, Oct 2007) (verified Oct 31, 2026)
const BRG90="https://projects.dev.seeinghands.org/files/original_brailliant/Brailliant%20User%20Guide.html",BRL90="https://www.mail-archive.com/braillenote@list.pulsedata.com/msg23904.html",MPO90="https://manualzz.com/doc/60139306/alva-mpo-5500-user-manual",BW90="https://usersmanualguide.com/handytech/keyboard/braille-wave/user-manual/204pr";
U(DEV,"brl2040",{src:[BRG90,BRL90],desc:["The original HumanWare Brailliant is a compact braille display in a light-metal case, built with the same techniques used for modern camera bodies. The guide lists models with 24, 32, 40, 64 and 80 cells. At the 2004 launch, HumanWare gave the weight of the 40-cell model as 560 g (1.23 lb) and the 24-cell model as 389 g (0.86 lb), and a BrailleNote mailing-list post in July 2004 gave US prices of $3,695 for the 24 and $5,895 for the 40.","The braille cells run along the front, with a small cursor-routing key behind each cell. Three navigation keys sit to the left of the cells and three to the right. They are numbered like braille dots: D1, D2 and D3 on the left (from back to front), and D4, D5 and D6 on the right. What they do depends on the screen reader.","The power button is slightly recessed at the back of the top-left side. Hold it for about 3 seconds to turn the display on or off, and it beeps to confirm.","On the left side are three connectors: a rectangular mini-USB port, a round 5-volt power socket in the middle, and a round serial port, shaped like a headset jack, on the right. Bluetooth has no external connector because the antenna is built in. A System Menu, opened with its own key combination and operated with the routing keys, sets the port, protocol and auto-power-off.","An internal battery charges fully in about 2.5 hours from the supplied adapter, or over USB. The guide gives about 25 to 30 hours on Bluetooth and up to 100 hours on USB or serial. It worked with VIRGO, Blindows, JAWS, Talks and Mobile Speak."]});
U(DEV,"mpo",{src:[MPO90],desc:["The ALVA MPO 5500 combines a GSM mobile phone with a braille and speech organiser. It measures 240 × 109 × 47 mm (9.8 × 4.3 × 1.9 in), weighs about 800 g (1 lb 9 oz), runs Windows CE .NET 4.1, has 64 MB of RAM and a built-in tri-band antenna.","All the keys are on top. Twenty braille cells sit centred on the upper half, each with a touch-cursor button above it, and the ON/OFF switch sits above the middle of that row of buttons. A Scroll Left key and a Scroll Right key sit just below each end of the braille line.","The 8-dot braille keyboard sits below the cells. Dot 7 doubles as Backspace and dot 8 as New Line. Along the edge nearest you are three keys: a Programs key, the space bar in the middle and a Menu key.","In the upper left corner is a round four-way Cursor Pad with two triangular keys beside it: a ribbed Cancel key and a smooth OK key. The upper right corner mirrors it with a round Audio Pad (Stop Speech, Mute Speech, Volume Up and Volume Down) and triangular Disconnect (ribbed) and Connect (smooth) keys. A setting swaps the two sides for left-handed users.","All the connectors are on the back. On the right, from right to left: the power jack, a stereo headset jack marked with one line, a phone headset jack marked with two lines, and a USB port marked with three lines. On the left is the SIM slot, with a small eject button. A 7.2 V 1800 mAh lithium-ion battery gives over 8 hours of use and charges in about 3 hours. It has a microphone and speaker, and syncs with Outlook through ActiveSync."]});
U(DEV,"bwave",{src:[BW90],desc:["The Handy Tech Braille Wave is a very compact 40-cell braille display with a built-in notetaker. It stores up to 4 MB in as many as 512 files, which the HTCom software transfers to and from a PC. It ships in a carrying case with a Velcro flap and an adjustable shoulder strap.","Along the front edge are three keys: Escape on the left, a wide space bar in the middle and Enter on the right. Behind them is a row of eight braille-input keys in two groups of four, ordered 7, 3, 2, 1 and 4, 5, 6, 8 from left to right. They also act as function keys.","Behind the keys are 40 ergonomic braille cells with a cursor-routing key built into each cell. A back-reading key [L] sits flush with the cells at the left end, and a forward-reading key [R] at the right end.","On the right side, near the front, is the main power switch: flip it towards you to turn the unit on. Behind it is the power socket (9 V DC, 1.5 A). On the left side are a telephone-style serial port for the PC, with a round port behind it for an optional external keyboard. Bluetooth models add a small slide switch near the front of the left side that chooses between Bluetooth and serial.","It runs on a set of four NiMH batteries in two compartments in the base, which came with an insulating strip to remove before first use. Also in the box were two foam keyboard pads, the power supply and a braille quick reference. A free DOS screen reader, BW-PRO, was available. The manual's size and weight figures could not be read in the online copy."]});
// Batch 91: HumanWare ClassMate Reader (User Guide rev. 9, 2009-02-02) and APH Braille Plus 18 (APH online documentation) (verified Oct 31, 2026)
const CM91="https://manualzz.com/doc/29275645/humanware-classmate-user-manual",BP91="https://tech.aph.org/plus_doc.htm";
U(DEV,"classmate",{src:[CM91],h:"HumanWare introduced the ClassMate Reader as a revolutionary device for people with reading difficulties. It was a handheld reader for students and adults that played the audio of textbooks while highlighting the text on screen, to help with comprehension, reading speed and vocabulary. Revision 9 of its user guide is dated February 2, 2009. It played DAISY, NISO Z39.86 and NIMAS books, Bookshare.org text, Audible books, podcasts and music. Its built-in dictionary was based on the 2004 Oxford American Minidictionary, and it read text aloud with Nuance Vocalizer. Recording for the Blind & Dyslexic sold a $20 authorization key that unlocked its protected books.",desc:["The ClassMate Reader is a handheld reader about the size of a portable game console. It measures 157 × 91 × 30 mm (6.2 × 3.6 × 1.2 in) and weighs 250 g (8.8 oz) with its battery. The front is mostly a colour LCD touchscreen, operated with a stylus that stores in the right edge.","Down the left side of the screen, from top to bottom, are Escape, Study Tools, Home, Dictionary and Record, with the microphone above Study Tools. On the right are a four-way arrow pad with Enter in the centre, a Go To Page/Heading button and a Play button, with the speaker above the Up arrow. Holding Home for two seconds turns on Key Describer mode, which announces each button as you press it.","On the left edge, from back to front, are the headphone jack, a Volume/Speed up-and-down rocker and a Volume/Speed toggle button. On the right edge are the Power button near the top corner, an SD card slot in the centre and the built-in stylus.","The top edge has a mini-USB port on the left, used for computer transfers and for USB memory sticks and book cartridges, and the power input jack on the right. The back holds a battery door, secured with a screw, with a retractable stand around it.","It uses a 3.7 V, 2 Ah lithium-ion battery that gives about 7 hours of DAISY playback over headphones and takes 4 to 5 hours to charge. It reads SD and SDHC cards up to 8 GB, records voice notes, and came with earbuds, a carrying pouch and two USB cables."]});
U(DEV,"bplus18",{src:[BP91],desc:["The APH Braille Plus 18 is an Android smartphone and notetaker built for braille users, which APH called the world's first Android smartphone for blind students and professionals. It measures under 6.5 by 4.1 inches and is just over an inch high.","Along the front of the top face are Shift, a wide Space bar and Control; Shift and Control double as dots 7 and 8. Behind them are 18 eight-dot braille cells, each with a cursor-routing bar. An oval Key Lock slide switch sits to the left of the cells, and green power and red charging lights to the right. Six braille keys sit further back in an ergonomic arc, with a cursor pad (four arrows and Select) between dots 1 and 4.","Long vertical Menu (left) and Home (right) bars flank the cursor pad. Beside Menu are Back and S1, which dials a number. Beside Home are Search and S2: press S2 to read everything, or hold it for braille and speech settings. There are microphones on both sides of the face and a phone speaker on the right.","The front edge has stereo speakers at each end, buttons that scroll the braille display back and forward, a central joystick that moves accessibility focus, and SIM and SD card slots. The left edge has the Power button about an inch from the front, a recessed Reset button, a full-size USB host port and a micro-USB On-The-Go port for charging and connecting to a computer.","The right edge has a long volume bar, a Camera button that opens the Look text-recognition app, a Record button, an earphone and video-out jack, and a jack reserved for future use. The camera lens and flash sit in the middle of the base. A full charge takes four to six hours."]});
// Batch 92: SMART Brailler, SmartView Graduate, GoVision Pro, BookSense DS (verified Oct 31, 2026)
const SBM92="https://sites.aph.org/files/manuals/Smart-Brailler/sb_manual.html",SBP92="https://brailler.perkins.org/pages/smart-brailler",VA92="https://www.visionaid.co.uk/smartview-graduate",EG92="https://www.ergoguys.com/govisionpro.html",BQ92="https://manualzilla.com/doc/5715468/untitled---hims-inc",NLS92="https://www.loc.gov/nls/services-and-resources/equipment-for-nls-materials/commercial-players-compatible-with-nls-materials-and-additional-products/";
U(DEV,"smartbr",{src:[SBM92,SBP92],desc:["The SMART Brailler is a Perkins-style manual braillewriter with an electronic Smart Module on the front. APH sold it as catalog no. 1-00820-00. Perkins lists it at 8.5 lb (3.9 kg) and 14 × 5.5 × 9.5 in (34 × 15 × 24 cm). It still embosses normally with the power off, and you carry it by a rounded Easy-Grip handle below the keys.","Across the front are nine keys: Line Spacing at far left, then dots 3, 2 and 1, the space bar, dots 4, 5 and 6, and Backspace at far right. Flat wing-shaped paper feed knobs stick out from each side, and two paper release levers sit at the top near the back. The carriage has a triangular release button and an oval Easy-Erase button just right of the embossing head.","The hinged Smart Module tilts forward. In the middle is a roughly 4-inch colour screen that shows SimBraille or large print. To its left are four Quick Buttons, marked with 0 to 3 raised lines (screen on/off, display mode, contracted or uncontracted braille, speech mode), and a speaker. To the right are a round green Menu button with a raised dot and a green diamond Select button, marked with a raised checkmark, surrounded by four navigation buttons.","The headphone jack is on top of the module at the right end, the two volume buttons are high on its right side, and a USB-A port is in a cutout lower on that side, for flash drives or a printer. Behind the module is a slot with left and right margin guides, with 36 raised cell markings above it. A bell sounds at cell 21 and again near the right margin.","A round rocker power switch is on the lower right side, and the power port is at the lower left of the back. The removable lithium-ion battery sits behind a two-screw door underneath and lasts about 5 hours. It embosses 25 lines of up to 28 cells on 8½ × 11 in paper and speaks with Acapela voices; Duxbury provides contracted-braille translation."]});
U(DEV,"svgrad",{src:[VA92],ha:" The UK dealer VisionAid lists the Graduate as discontinued; it was priced at £1,750 there with VAT relief. VisionAid described it as a laptop-connected magnifier for students and travelling professionals: it splits into three parts that fit in a computer bag, sets up in under a minute, and takes its power from the laptop through two USB 2.0 cables. VisionAid lists compatibility with Windows XP, Vista, 7 and 8. No dated launch announcement was found, so the introduction year remains unknown.",desc:["The SmartView Graduate is a HumanWare video magnifier that connects to a laptop and has no screen of its own; the magnified image appears on the computer. Assembled, it measures 12 × 9 × 15.5 in (VisionAid's metric figure is 22.8 × 30 × 39 cm) and weighs 2.5 lb (1.1 kg).","It breaks down into three main parts (the camera, the arm and the base), which fit in a laptop bag or an optional travel case. Setup takes under a minute.","The colour autofocus camera zooms continuously from about 3× to 50× and rotates 360°, so it can switch between reading on the desk and viewing a board across the room.","The included software on the PC provides zoom control, adjustable contrast and brightness, high-contrast viewing modes, image rotation, freeze-frame, and image capture saved to the computer.","It draws all its power from the laptop over two USB 2.0 cables, so no mains adapter is needed. It came with USB cables, a software and documentation CD, and an installation guide."]});
U(DEV,"govisionpro",{src:[EG92],h:"HIMS lists the GoVision Pro as a 2018 product in its official product history. It is an all-in-one, transportable HD video magnifier that combines desktop magnification with a 13-megapixel camera for full-page OCR and speech, a 360° rotating camera for distance viewing such as a classroom whiteboard, and a self-view mode for grooming. The reseller Ergoguys lists its specifications as 460 × 570 × 180 mm and 8.5 kg, with near-view magnification of 1.7× to 68×. It also includes a document viewer, a video player and a digital photo frame.",desc:["The HIMS GoVision Pro is an all-in-one video magnifier with its monitor and camera arm built together. Ergoguys lists it at 460 mm wide, 570 mm high and 180 mm deep (18.1 × 22.4 × 7.1 in), weighing 8.5 kg (18.7 lb).","A camera on an arm in front of the screen magnifies from 1.7× to 68× in Near View and rotates 360° for Distance View and Self View. LED lights with brightness control light the reading area, and there is a built-in guide for the reading table.","For portability you turn the camera arm and head parallel to the screen and lift one lever, which folds them down behind the monitor.","You control it with a remote that has large, high-contrast buttons and speaks the item you are on, or with a jog switch on the side of the camera. There are 7 colour modes (4 user-definable, 57 combinations), focus lock, line markers, a built-in speaker, an earphone jack and volume control.","A separate 13-megapixel camera captures a full letter-size page for OCR with text-to-speech, with a guide frame, column reading and automatic language detection. It also includes a document viewer, a video player with subtitles, a photo frame, a clock and a screen saver."]});
U(DEV,"bksds",{src:[BQ92,NLS92],desc:["The BookSense DS is a pocket digital book player made by HIMS and sold by GW Micro. The Library of Congress NLS equipment list gives its size as 1.77 × 0.63 × 3.82 in and its weight as 0.143 lb (about 2.3 oz). It is the only BookSense model with a visual OLED display.","On the front, the OLED display is at the top, with Up, Down and a jog switch below it. Mode, which cycles through the Media, DAISY, Document Reader and FM Radio programs, is centred just below the jog switch, with Cancel, Play and OK nearby and a 0–9 number pad underneath. Holding the jog switch for 2 seconds turns on Help Mode, which announces what each key does.","On the left side are the Power/Hold slide switch, volume buttons, a USB On-The-Go port for a computer or memory stick, and a reset button. Pulling the switch down for 2 seconds turns the player on or off; sliding it up locks every key.","The right edge has an SD card slot near the bottom. The quick start guide also lists Record and Date & Time buttons, a DC power jack, earphone and microphone jacks, a speaker and a strap holder.","It has 4 GB of internal memory, records MP3 from its microphone or the FM radio, and charges fully in about 2.5 hours. It came with an AC adapter, two USB cables, earbuds, an SD card holding the manual, a silicone case and a lanyard."]});
// Batch 93: NLS eReader (HumanWare), Pronto! 18 V3, Perkins/Seika 80, Franklin Bill Reader; BookSense DS wording fix (verified Oct 31, 2026)
const NLSG93="https://www.loc.gov/nls/services-and-resources/equipment-for-nls-materials/nls-braille-ereader-humanware-user-guide/",AVH93="https://www.avh.asso.fr/implantations/certam/evaluations-de-produits/le-bloc-notes-braille-pronto-18-v3",NT93="https://www.nippontelesoft.com/menu_eng/disp_002.html",FBR93="https://www.eastersealstech.com/2010/10/12/product-description-franklin-bill-reader-br-1000/",ES93="https://www.eastersealstech.com/2010/07/22/gw-micro-presents-the-booksense-ds/";
U(DEV,"nlsereader",{src:[NLSG93],desc:["The NLS Braille eReader from HumanWare is a 20-cell braille reader that the Library of Congress lends free to its braille patrons. The NLS user guide (version 3.0) describes a flat unit with an eight-key Perkins-style keyboard across the back half of the top and the braille display in front of it.","The keyboard is numbered from the centre out: dots 1, 2, 3 and 7 to the left, and 4, 5, 6 and 8 to the right. Dot 7 doubles as Backspace and dot 8 as Enter. In front of the keys are 20 braille cells, each with a cursor-routing button, and two identical Space keys run along the front edge of the top.","On the front edge are five thumb keys, from left to right: Up, Left, a round Select, Right and Down. Each rectangular key has a small tactile ridge showing its direction, and Left and Right have vertical tactile lines on their outer sides.","On the left side, from back to front, are a USB-C port for charging and connecting to a computer or phone, a green power light, an oval Power button with a raised dot, a USB-A port for a flash drive or keyboard, and a lanyard hole. The right side has an audio jack and two volume buttons, which the NLS eReader does not use, plus a second lanyard hole. The back edge has an SD card slot near the left end.","It charges fully in about three hours and runs about 15 hours on a charge. It came with a USB-A to USB-C cable, an AC adapter, an NLS cartridge USB cable, a lanyard, and print and braille getting-started guides."]});
U(DEV,"pronto",{src:[AVH93],desc:["The Pronto! 18 V3 is a small braille notetaker from BAUM (VisioBraille – BAUM Retec) with an 18-cell display. France's Association Valentin Haüy evaluated it in June 2014 (software 3.6.6, €4,290). It comes in a carrying case worn on a shoulder strap or belt, and is small enough for a large coat pocket.","On the top face, from front to back: a Space key under the right thumb and an Enter key under the left, flanked by small round system buttons (S1 and S2 on the left, S3 and S4 on the right). Behind them are the 18 braille cells with routing keys, then an eight-key braille keyboard. Three round navigation keys (D1–D3 and D4–D6) stand vertically on each side of the cells, and a round, slightly raised speaker sits between dots 1 and 4.","On the front edge, from left to right, are a Record button, a built-in microphone and a five-way joystick (up, down, left, right and a centre press).","On the back edge, from left to right, are the power socket, an SD card reader, a serial port for screen readers, the Bluetooth antenna, a USB-A port for a keyboard or flash drive, a 3.5 mm headphone jack, a 3.5 mm microphone jack and a mini-USB port for ActiveSync with a PC.","It runs Windows CE from 1 GB of flash memory, with about 10 hours of battery life and Nuance speech. Its apps include an editor, calendar, contacts, email, web browser, DAISY and MP3 players, and PDF and Excel readers. It also works as a braille display for a PC or for iOS and Android phones over USB, serial or Bluetooth."]});
U(DEV,"perk80",{src:[NT93],desc:["The Perkins 80-cell display is the Seika 80, made by Nippon Telesoft of Tokyo. It has 80 eight-dot braille cells in a single long, slim case.","Nippon Telesoft lists it at 58 × 9 × 2.5 cm (23 × 3.5 × 0.8 in) and 1,000 g; its English page also gives 3.3 lb.","There is a touch cursor (routing) key above each of the 80 cells, plus 8 function keys, including pan-left and pan-right keys and thumb keys.","It connects to the computer with one USB cable and draws its power over USB, so it has no battery or power adapter. It came with a leather carrying case and strap.","Nippon Telesoft lists support for NVDA, JAWS, SuperNova, Window-Eyes and COBRA, and supplies driver and screen-reader patch downloads."]});
U(DEV,"franklinbill",{src:[FBR93],desc:["The Franklin Bill Reader, model BR-1000, is a small handheld money identifier. It measures 79 × 42 × 20 mm, about the size of a small pager.","A large CAPTURE button sits in the top corner. You hold the reader 3 to 8 inches above a single U.S. bill, lens facing the bill, and press CAPTURE.","A built-in digital camera takes a picture, and Evolution Robotics' ViPR visual pattern recognition identifies the denomination.","A built-in speaker announces the value in English or Spanish. It recognises current and recent designs of the $1, $2, $5, $10, $20, $50 and $100 bills.","It runs on two AAA batteries, rated for about 1,000 scans or about 200 days on standby."]});
U(DEV,"bksds",{src:[ES93],desc:["The BookSense DS is a pocket digital book player made by HIMS and sold by GW Micro. The Library of Congress NLS equipment list gives its size as 1.77 × 0.63 × 3.82 in and its weight as 0.143 lb (about 2.3 oz). In July 2010, Easter Seals Crossroads called it the only book player with an OLED display, for higher contrast.","On the front, the OLED display is at the top, with Up, Down and a jog switch below it. Mode, which cycles through the Media, DAISY, Document Reader and FM Radio programs, is centred just below the jog switch, with Cancel, Play and OK nearby and a 0–9 number pad underneath. Holding the jog switch for 2 seconds turns on Help Mode, which announces what each key does.","On the left side are the Power/Hold slide switch, volume buttons, a USB On-The-Go port for a computer or memory stick, and a reset button. Pulling the switch down for 2 seconds turns the player on or off; sliding it up locks every key.","The right edge has an SD card slot near the bottom. The quick start guide also lists Record and Date & Time buttons, a DC power jack, earphone and microphone jacks, a speaker and a strap holder.","It has 4 GB of internal memory, records MP3 from its microphone or the FM radio, and charges fully in about 2.5 hours. It came with an AC adapter, two USB cables, earbuds, an SD card holding the manual, a silicone case and a lanyard."]});
// Batch 94: BD-3, LED-120, ELba, NuEyes Pro 4, BT Braille descriptions (verified Oct 31, 2026)
const BD94="https://sites.aph.org/museum-virtual-exhibit/vex1/FC37273C-26B8-431D-B445-033067776821.htm",JN94="https://homepage.divms.uiowa.edu/~jones/making/brailleprinter/Text.html",EL94="https://manualzz.com/doc/1887502/papenmeier-elba-braille-assistant-user-s-manual",NU94="https://www.nueyes.com/pro4",NUB94="https://nelowvision.com/wp-content/uploads/2024/10/NuEyes-Pro-4-Brochure.pdf",BT94="https://www.blazietech.com/bt-braille",BTD94="https://brailledb.seeinghands.org/device/blazietech_btbraille_20";
U(DEV,"bd3",{src:[BD94],desc:["The Triformation BD-3 Braille Terminal was a portable braille embosser built into a brown plastic suitcase. The case has a pebbled faux-leather finish with real stitching, brushed-aluminium trim, chrome latches and a carrying handle. The APH Museum example, serial #00048, is labelled 'TRIFORMATIONS SYSTEMS, INC./BRAILLE TERMINAL BD-3'. APH says it weighed 15 pounds and cost $1,850.","Inside the opened case is a plastic table covered in walnut-woodgrain vinyl. The embossing head sits under a brown cover at the lower left.","It embossed onto paper tape rather than sheets. An 8.5-inch grey plastic spool of tape mounts on an aluminium hub at the upper right and feeds around a spring-loaded aluminium bar.","Behind the embossing head is a small panel with a female RCA input jack, an on/off toggle switch and a red indicator light; the grey power cord comes out of the table above it. APH records the case's dimensions as H 14.5, W 19, D 60 inches.","Sold as a 'braille verifier', it produced braille tape of whatever was being typed on a connected teletype or computer terminal. The donor's brother used it with a Teletype Model 33 at the University of Connecticut in 1976. He found that moving between the keyboard and the tape was slow and awkward, and that it was faster to have someone read the teletype output aloud."]});
U(DEV,"led120",{src:[BD94,JN94],desc:["The Triformation LED-120 was a full-page braille embosser, the full-sheet successor to the company's BD-3 tape embosser. APH says it became available in June 1974 at $9,000, much more than the BD-3, and was far more popular.","A 1979 University of Iowa braille printer report cited it, alongside SAGEM's TEM/REM 8 BR, as representing the state of the art. It ran at 120 characters per second, against 15 for the SAGEM.","Its electronics were 'random' logic with some LSI chips, and it used a mechanical control system rather than a microprocessor.","It took the ASCII character set and mapped 64 characters directly to the 64 six-dot braille signs. That mapping matched Grade 1 English Braille only for letters, so separate translation software was needed for proper Grade 1 or Grade 2 braille. It also supported an 8-dot cell.","No source found in this research gives the LED-120's physical size, weight or control layout, so those details are not included."]});
U(DEV,"elba",{src:[EL94],desc:["The BRAILLEX ELba (EL Braille Assistant) is a portable, Linux-based braille notetaker from F. H. Papenmeier of Schwerte, Germany. The August 2003 user manual describes it with either 20 or 32 braille cells, and with either an eight-dot braille keyboard or a QWERTY keyboard.","The rounded front houses Papenmeier's patented Easy Access Bar, a long joystick-like bar with rubber nubs for grip. You push it up, down, left or right with your thumbs, in two steps each way, to move around the screen without leaving the braille. The braille display sits behind the bar, with a routing key built into each cell, a speaker grille to its right and a small microphone to its left.","Above the display is the keyboard. The braille version's eight keys run 7, 3, 2, 1, 4, 5, 6, 8 from left to right, with a long Space key below and a thumb key on each side of it. The QWERTY version has a notebook-style layout with Windows and context-menu keys.","On the back panel, from left to right, are the on/off switch, the charger jack, a 25-pin parallel port, a PS/2 keyboard port, an RJ-11 modem jack, a USB client port, a 9-pin serial port and a speaker/headphone jack. A PCMCIA/CardBus slot sits above the modem, USB and serial connectors, with an RJ-45 Ethernet jack to its right.","It has 16 MB of flash memory and 32 MB of RAM, and a built-in lithium-ion battery rated for at least 10 hours, charging overnight in at most 6 hours. It ran email (Pine), the Lynx web browser, an editor, a spreadsheet, a day planner and an MP3 player, and could act as a braille display for a Windows PC. It shipped with a Velcro-lined carrying pouch."]});
U(DEV,"nuepro4",{src:[NU94,NUB94],desc:["The NuEyes Pro 4 is a pair of lightweight augmented-reality smart glasses weighing 102 grams, with arms that fold for storage.","Two 1080p OLED displays, one for each eye, give a 43° field of view. A 12-megapixel camera and a gyroscope, accelerometer, light sensor and distance sensor are built into the frame.","The glasses have no battery. They plug into a compatible phone, tablet or computer by USB-C and draw power from it; NuEyes says that gives about 6 hours with a Samsung S21. The page also notes 5G compatibility through the connected phone.","In the low-vision version, the Pro 4 LV, the October 2024 brochure lists variable magnification from 1× to 12×, OCR with text-to-speech, and a range of colour and contrast settings. It also says the glasses help with reading, writing, watching TV and seeing faces.","The Pro 4 LV ships with a Samsung phone and a case and has a one-year warranty. NuEyes' Smart Bundle adds its low-vision software, a two-year support plan and dedicated tech support. Standard and DoD/Federal USB-C standalone versions are also sold."]});
U(DEV,"btbraille",{src:[BT94,BTD94],ha:" Blazie Technologies lists the BT Braille at $4,495 for the 20-cell model and $6,495 for the 40-cell model, and the BrailleDB device database records it as released in 2026.",desc:["The BT Braille from Blazie Technologies is a braille computer and notetaker in 20-cell and 40-cell sizes. Blazie gives the 20-cell model as 6.38 × 4.63 × 1.25 in and 618 g (1 lb 6 oz), and the 40-cell as 11.38 × 4.63 × 1.25 in and 885 g (1 lb 15 oz). It notes these figures are within 0.2 in of the final design.","It has a 9-key Perkins-style braille keyboard. BrailleDB describes the keyboard as non-linear, with the space bar above the display and dots 7 and 8 on either side of it.","Below the keyboard is a piezoelectric braille display (eight-dot cells with cursor routing) with three navigation buttons at each end, six in all.","According to BrailleDB, the two USB-C ports (one also used for charging) are on the rear edge and the 3.5 mm headphone jack is on the right side. There are also a mini-HDMI port for classroom screen sharing, a microSD slot, dual speakers, a microphone and haptic feedback.","Inside are a Raspberry Pi Compute Module 5, 16 GB of RAM and a 1 TB SSD, with Wi-Fi and Bluetooth. A 15,000 mAh lithium-polymer battery gives at least 10 hours. It runs a Linux-based, self-voicing text interface, with an optional MATE desktop running the Orca screen reader. Terminal Mode lets it act as a braille display for iPhone, iPad, Mac and Windows."]});
// Batch 95: led120 desc correction (source is Appel & Jones, Univ. of Illinois; 8-dot claim removed)
U(DEV,"led120",{src:["https://sites.aph.org/museum-virtual-exhibit/vex1/FC37273C-26B8-431D-B445-033067776821.htm","https://homepage.divms.uiowa.edu/~jones/making/brailleprinter/Text.html"],desc:["The Triformation LED-120 was a full-page braille embosser, the full-sheet successor to the company's BD-3 tape embosser. APH says it became available in June 1974 at $9,000, much more than the BD-3, and was far more popular.","In 'A Braille Printer', Andrew W. Appel and Douglas W. Jones of the University of Illinois Medical Computing Laboratory cited it, alongside SAGEM's TEM/REM 8 BR, as representative of the state of the art. They give its speed as 120 characters per second, against 15 for the SAGEM.","The paper says its electronics were 'random' logic with some LSI chips, and that it used a mechanical control system rather than a built-in microcomputer.","It took the ASCII character set and mapped 64 characters directly to the 64 six-dot braille signs, including space. That mapping matched Grade 1 English Braille only for letters, so typical computer output was hard to read and separate translation programs were needed for standard Grade 1 or Grade 2 braille.","No source found in this research gives the LED-120's physical size, weight or control layout. The APH museum record covers only the BD-3, and the Appel and Jones paper discusses only its speed and logic, so those details are not included."]});
// Batch 96: idxv2 desc; viewscan, bslx, idx37 descs with documented gaps
const SA96="https://sastltd.zohodesk.eu/portal/en/kb/articles/index-embosser-version-identification",NFB96="https://www.duxburysystems.org/downloads/library/history/00-nfb1994-tech-eval.pdf",BC96="https://www.braillecast.com/podcast/e020/",VA96="https://sites.aph.org/museum-virtual-exhibit/vex5/B05FEC63-3118-4C9D-814D-168516371748.htm",AFB96="https://afb.org/aw/6/6/14572",CEO96="https://doi.org/10.1111/j.1444-0938.1982.tb03034.x",HI96="https://www.himsintl.com/en/company/prd_history.php";
U(DEV,"idxv2",{src:[SA96,NFB96,BC96],desc:["Index Braille's version 2 platform (V2) covered the Basic single-sided embosser and the Everest sheet-fed interpoint embosser. Braillecast dates it to 1995, and SAST's identification guide gives production as February 1995 to 2002.","SAST says the V2 Basic has a red lid on a black case. Every V2 printed through a Centronics parallel interface only. The serial port on V2 and V3 machines is for service and cannot be used for embossing, and SAST adds that USB-to-parallel leads generally do not work well.","No V2 spec sheet turned up in this research. The nearest source is the 1994 NFB/APH Braille Technology Evaluation, which tested the models sold just before V2. It gives the Basic as 20 × 11.75 × 7.5 in, 14 lb, 50 characters per second and $2,995. Its paper fed from front to back across the top, with four switches and an impression knob at the rear left of the top plate, and serial and parallel ports, a power switch and the power cord on the back.","That report gives the Everest as 20 in wide, 6.75 in deep and 25 in tall, weighing 25 lb, rated at 100 characters per second and priced at $5,995. A feeder on top held 100 to 150 single sheets, which passed down through the printer into a catch basket at the bottom. The front-panel buttons had braille labels and spoke through built-in speech, and a cut-down Duxbury translator was built into ROM.","These measurements describe the pre-1995 models, not the V2 machines, and are given only as the closest documented reference. SAST says Index stopped supporting V2 embossers on January 1, 2011."]});
U(DEV,"viewscan",{src:[AFB96,VA96,CEO96],desc:["The Viewscan, introduced in 1980, was a portable hand-scanning reading aid for people with low vision. It was made by the Sensory Aids Division of Wormald International, and AccessWorld credits its design to Russell Smith.","AccessWorld and the APH Museum describe it as a portable large-print hand-scanning device: you passed a camera over printed text and it appeared enlarged on the unit's display. A user AccessWorld quotes recalled Wormald's displays for 'gorgeous orange-on-black scrolling words', though he was describing the later Viewscan Text System.","APH says the Viewscan Text System (VTS-100, 1983), with the optional scanning camera, could magnify a library-book page up to 40 times. The APH example is a modified Epson HX-20 laptop, 1.875 × 14.75 × 8.5 in, with a 25-pin camera jack on its left side.","A 1982 technical note by Alan W. Johnston of the University of Melbourne, 'The Viewscan – a new reading aid for the visually impaired' (Clinical and Experimental Optometry), evaluated the device. Its full text was not accessible in this research.","No museum record, manual or accessible review of the original 1980 Viewscan was found. Its size, weight, display, controls and price are therefore not included, rather than borrowed from the later Text System."]});
U(DEV,"bslx",{src:[HI96,"https://selvasblv.com/product-history-grid/"],desc:["The BrailleSense LX is a HIMS braille notetaker that the company's official product history lists under 2008.","In that history it comes after the original BrailleSense (2004) and before the BrailleSense OnHand (2010). HIMS is now Selvas BLV.","Searches for a BrailleSense LX spec sheet, user manual, brochure, dealer listing or review all came up empty. The HIMS and Selvas history pages give only its name, year and product photo slot.","The NVDA screen reader's HIMS driver uses the device ID 'LX' for a BrailleSense model with four scroll keys. Nothing in the driver connects that ID to this product name, though, so no physical details are taken from it.","Its cell count, keyboard type, ports, battery, size and weight are not included, because no source found in this research documents them."]});
U(DEV,"idx37",{src:[BC96,"https://indexbraille.com/about-us/"],desc:["The Index Computer Braille Printer was the first embosser made by what became Index Braille. Braillecast says a small batch was built in Björn Löfstedt's garage in Sweden by 1984.","These machines became known as 'Index 3.7' embossers, after their firmware version.","They came out of a 1979 university project to build a braille typewriter that could also make copies. Polar Print Production, the company Löfstedt and Torvald Lundqvist formed in 1982, built them.","Index Braille became a brand in its own right in the late 1980s with the Index Blue Bar, a tractor-feed embosser, followed in 1992 by the cut-sheet Everest. SAST describes the first-generation (V1) Basic as having a steel case with a blue and red bar, but no source ties that description to the Index 3.7 itself.","No photograph, museum record, manual or contemporary review of the Index 3.7 turned up in this research. Its size, weight, speed, paper handling and interfaces are therefore not included."]});
// Batch 97: hardware histories (h) from facts already verified in each entry; numeric years where the entry's own dated evidence gives one
U(DEV,"tns",{h:"Blazie Engineering brought out the Type 'n Speak in late 1992 as the typewriter-keyboard sibling of its 1987 Braille 'n Speak. Deane Blazie said it was for people who liked the Braille 'n Speak but did not know braille. It was a screenless, speech-only notetaker with RAM and flash storage, and its line passed to Freedom Scientific when Blazie merged into it."});
U(DEV,"bnapex18",{h:"HumanWare launched the BrailleNote Apex BT18 in May 2010, for the BrailleNote's tenth anniversary, and called it the tenth notetaker in the line. It is the 18-cell version of the Apex, with the same case design, keyboard and thumb-key layout."});
U(DEV,"vnapex",{h:"HumanWare introduced the VoiceNote Apex in July 2010, the Friday before that year's NFB convention, as the speech-only member of the Apex family. It came with a braille (BT) or QWERTY (QT) keyboard. It is physically identical to the BrailleNote Apex, and HumanWare said a braille display could be added later."});
U(DEV,"bookportplus",{h:"APH announced the Book Port Plus as available on March 10, 2010, as the successor to its original Book Port. It added Wi-Fi for internet radio, podcast downloads and wireless file transfer, and it is smaller and lighter than the first model."});
U(DEV,"u2qt",{h:"HIMS released the BrailleSense U2 QWERTY (model H432Q) in 2012 as the typewriter-keyboard version of the BrailleSense U2. HIMS (now Selvas BLV) has since discontinued it and points buyers to the BrailleSense 6."});
U(DEV,"orcam3",{h:"OrCam released the MyEye 3 Pro in 2024 as the current generation of its clip-on MyEye reader. It is a single bar that clips magnetically to glasses with no cable. It adds a desktop mode: on its stand, it connects to a browser at cast.orcam.com and has an AI assistant that answers questions about a scanned page."});
U(DEV,"envgl",{h:"Envision released Envision Glasses in November 2020. They are built on Google Glass Enterprise Edition 2 and run Envision's AI reading and scene-description software. Envision later partnered with Solos on the Ally Solos Glasses (2025), which run its Ally assistant."});
U(DEV,"nueasy",{h:"The NuEyes Easy (2016) was NuEyes' first head-worn magnifier. It was developed with Osterhout Design Group (ODG), which made glasses for military uses, and was listed at $5,995. NuEyes followed it with the Pro line, including the Pro 3 (2020) and the Pro 4."});
U(DEV,"sara",{h:"Freedom Scientific introduced SARA (Scanning and Reading Appliance) in 2006. It is a stand-alone reading machine that combines a flatbed scanner, text recognition and RealSpeak speech in one box, so no computer is needed."});
U(DEV,"nuepro3",{h:"NuEyes announced the Pro 3 augmented-reality glasses on December 15, 2020, and put them on sale on December 18. Versions were offered for low vision, medical and training use, including a USB-C Pro 3-C and a thermal-imaging model. They were succeeded by the Pro 4."});
U(DEV,"echovision",{h:"AGIGA's EchoVision smart glasses shipped as a Pioneer Edition in late October and November 2025, priced at $599. They offer AI scene description, text reading, face recognition, and calls to Aira and Be My Eyes."});
U(DEV,"allysolos",{h:"Envision and Solos opened pre-orders for the Ally Solos Glasses on August 14, 2025, and began shipping in October 2025 at $699. The glasses run Envision's Ally conversational AI assistant, and they follow Envision's Google Glass-based Envision Glasses (2020)."});
U(DEV,"forav20",{yr:2012,h:"The Fora V20 is a talking blood glucose meter from Fora Care. It was on the US market by 2012, when AccessWorld tested it alongside the Fora V22 and the Solo V2. The reviewer found its buttons among the easiest to tell apart, but its PC software and electronic manual were not screen-reader accessible."});
U(DEV,"forav22",{yr:2012,h:"The Fora V22 is a slim talking blood glucose meter from Fora Care with a built-in rechargeable battery. It was on the US market by 2012, when AccessWorld tested it and found it the slimmest of the talking meters in that review."});
U(DEV,"solov2",{yr:2012,h:"The Solo V2 is a talking blood glucose meter from BioSense Medical Devices. It was on the US market by 2012, when AccessWorld found it the cheapest fully talking meter tested, at $17, with the largest display characters."});
U(DEV,"talkingthermo",{yr:2012,h:"The TALKiNG Fast Reading Thermometer was on the market by 2012, when AccessWorld reviewed it at $12.95. Its packaging did not name the maker, and a search identified it as the Ultmost HE-113-EN. AccessWorld found it accurate but criticized the lack of an accessible manual or usable website."});
U(DEV,"lumiscopeear",{yr:2012,h:"The Lumiscope Talking Digital Ear Thermometer was on the market by 2012, when AccessWorld reviewed it alongside the TALKiNG oral thermometer. The reviewer found it very fast but consistently higher than the oral thermometer, by as much as three degrees during a fever."});
U(DEV,"rt8400",{yr:2012});
